import React from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import "./index.css";

// --- Core Pages & Layouts ---
import LoginPage from "./pages/LoginPage";
import CoreDashboard from "./core/components/CoreDashboard";
import GlobalSettings from "./core/pages/GlobalSettings";
import MasterLayout from "./core/layout/MasterLayout";
import ProtectedRoute from "./core/authentication/ProtectedRoute";
import SuperAdminRoute from "./core/authentication/SuperAdminRoute";
import RealtimeLogoutListener from "./components/RealtimeLogoutListener";
import { MagicToastProvider } from "./context/MagicToastContext";
import systemRegistry from "./core/registry/systemRegistry";

// --- System Module Registrations ---
import "./systems/checklist-delegation";
import "./systems/mis_summary/index.jsx"; // MIS Summary system
import "./systems/whatsapp-management";
import "./systems/HR_fms";
import "./systems/greetings";
import "./systems/inventory";
import "./systems/purchase";

function App() {
  const systems = systemRegistry.getAllSystems();

  return (
    <MagicToastProvider>
      <Router>
        {/* Realtime listener handles logout logic across tabs */}
        <RealtimeLogoutListener />

        <Routes>
          {/* --- Public Routes --- */}
          <Route path="/" element={<Navigate to="/login" replace />} />
          <Route path="/login" element={<LoginPage />} />

          {/* --- Master Layout Protected Shell --- */}
          <Route element={<MasterLayout />}>
            {/* Core Platform Dashboard */}
            <Route
              path="/dashboard"
              element={
                <ProtectedRoute>
                  <CoreDashboard />
                </ProtectedRoute>
              }
            />

            {/* Global Settings */}
            <Route
              path="/dashboard/global-settings"
              element={
                <ProtectedRoute>
                  <SuperAdminRoute>
                    <GlobalSettings />
                  </SuperAdminRoute>
                </ProtectedRoute>
              }
            />

            {/* Dynamically register routes of all registered systems */}
            {systems.map((sys) =>
              sys.routes.map((route) => {
                let element = route.element;
                if (route.protected) {
                  if (route.superAdminOnly) {
                    element = <SuperAdminRoute>{element}</SuperAdminRoute>;
                  } else {
                    element = (
                      <ProtectedRoute allowedRoles={route.allowedRoles}>
                        {element}
                      </ProtectedRoute>
                    );
                  }
                }

                return (
                  <Route
                    key={route.path}
                    path={route.path}
                    element={element}
                  />
                );
              })
            )}
          </Route>

          {/* --- Backward Compatibility Redirects --- */}
          <Route path="/admin/*" element={<Navigate to="/dashboard/admin" replace />} />
          <Route path="/admin/dashboard" element={<Navigate to="/dashboard/admin" replace />} />
          <Route path="/admin/quick" element={<Navigate to="/dashboard/quick-task" replace />} />
          <Route path="/admin/assign-task" element={<Navigate to="/dashboard/assign-task" replace />} />
          <Route path="/admin/delegation-task" element={<Navigate to="/dashboard/delegation-data" replace />} />
          <Route path="/admin/mis-report" element={<Navigate to="/dashboard/mis-report" replace />} />
          <Route path="/user/*" element={<Navigate to="/dashboard/admin" replace />} />

          {/* Fallback */}
          <Route path="*" element={<Navigate to="/login" replace />} />
        </Routes>
      </Router>
    </MagicToastProvider>
  );
}

export default App;

import { useState, useEffect, useRef, useMemo } from "react";
import { Play, Pause } from "lucide-react";

/**
 * Shared AudioPlayer component to handle voice notes and other audio recordings.
 */
const AudioPlayer = ({ url, className = "" }) => {
    const [isPlaying, setIsPlaying] = useState(false);
    const [hasInteracted, setHasInteracted] = useState(false);
    const audioRef = useRef(null);

    const cacheBustedUrl = useMemo(() => {
        if (!url) return url;
        if (url.startsWith('blob:')) return url;
        const separator = url.includes('?') ? '&' : '?';
        return `${url}${separator}cb=${Date.now()}`;
    }, [url]);

    const togglePlay = (e) => {
        if (e && e.stopPropagation) e.stopPropagation();

        if (!hasInteracted) {
            setHasInteracted(true);
            return;
        }

        if (isPlaying) {
            audioRef.current.pause();
        } else {
            audioRef.current.play().catch(err => {
                console.error("Playback failed:", err);
            });
        }
    };

    useEffect(() => {
        if (hasInteracted && audioRef.current && !isPlaying) {
            audioRef.current.play().catch(err => {
                console.error("Lazy Playback failed:", err);
            });
            setIsPlaying(true);
        }
    }, [hasInteracted]);

    useEffect(() => {
        const audio = audioRef.current;
        if (!audio) return;

        const handleEnded = () => setIsPlaying(false);
        const handlePause = () => setIsPlaying(false);
        const handlePlay = () => setIsPlaying(true);

        audio.addEventListener('ended', handleEnded);
        audio.addEventListener('pause', handlePause);
        audio.addEventListener('play', handlePlay);

        return () => {
            audio.removeEventListener('ended', handleEnded);
            audio.removeEventListener('pause', handlePause);
            audio.removeEventListener('play', handlePlay);
        };
    }, [hasInteracted]);

    return (
        <div className={`flex items-center gap-2.5 px-2.5 py-1.5 rounded-lg border transition-all duration-300 w-fit min-w-[120px] shadow-sm bg-white border-violet-100 hover:border-violet-200 hover:shadow-md ${isPlaying ? 'bg-violet-50/80 border-violet-300 scale-[1.02]' : ''} ${className}`}>
            <button
                type="button"
                onClick={togglePlay}
                className={`w-7 h-7 rounded-full flex items-center justify-center transition-all duration-300 shadow-sm ${isPlaying
                    ? 'bg-gradient-to-r from-rose-500 to-pink-600'
                    : 'bg-gradient-to-r from-violet-500 to-fuchsia-600 hover:scale-110 active:scale-95'
                    }`}
            >
                {isPlaying ? (
                    <Pause size={12} className="text-white fill-white" />
                ) : (
                    <Play size={12} className="text-white fill-white ml-0.5" />
                )}
            </button>
            <div className="flex flex-col">
                <span className={`text-[9px] font-black uppercase tracking-[0.1em] ${isPlaying ? 'text-violet-700' : 'text-gray-400'}`}>
                    {isPlaying ? 'Playing...' : 'Voice Note'}
                </span>
                {isPlaying && (
                    <div className="flex gap-0.5 mt-0.5 h-1.5 items-center">
                        <div className="w-0.5 h-full bg-violet-400 animate-bounce" style={{ animationDuration: '0.6s' }}></div>
                        <div className="w-0.5 h-2/3 bg-violet-500 animate-bounce" style={{ animationDuration: '0.8s' }}></div>
                        <div className="w-0.5 h-full bg-violet-600 animate-bounce" style={{ animationDuration: '0.4s' }}></div>
                        <div className="w-0.5 h-2/3 bg-violet-500 animate-bounce" style={{ animationDuration: '0.7s' }}></div>
                    </div>
                )}
            </div>
            {hasInteracted && <audio ref={audioRef} src={cacheBustedUrl} className="hidden" preload="auto" />}
        </div>
    );
};

export default AudioPlayer;

import React, { useState } from "react";

const CalendarComponent = ({ date, onChange, onClose }) => {
    const [currentMonth, setCurrentMonth] = useState(date && !isNaN(new Date(date).getTime()) ? new Date(date) : new Date());

    const getDaysInMonth = (year, month) => new Date(year, month + 1, 0).getDate();
    const getFirstDayOfMonth = (year, month) => new Date(year, month, 1).getDay();

    const handleDateClick = (day) => {
        const selectedDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
        onChange(selectedDate);
        onClose();
    };

    const renderDays = () => {
        const days = [];
        const daysInMonth = getDaysInMonth(currentMonth.getFullYear(), currentMonth.getMonth());
        const firstDayOfMonth = getFirstDayOfMonth(currentMonth.getFullYear(), currentMonth.getMonth());

        for (let i = 0; i < firstDayOfMonth; i++) {
            days.push(<div key={`empty-${i}`} className="h-8 w-8"></div>);
        }

        for (let day = 1; day <= daysInMonth; day++) {
            const dateToCheck = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
            const isSelected = date &&
                date.getDate() === day &&
                date.getMonth() === currentMonth.getMonth() &&
                date.getFullYear() === currentMonth.getFullYear();

            const isToday = new Date().toDateString() === dateToCheck.toDateString();

            days.push(
                <button
                    key={day}
                    type="button"
                    onClick={() => handleDateClick(day)}
                    className={`h-8 w-8 rounded-full flex items-center justify-center text-sm transition-colors ${isSelected
                            ? "bg-purple-600 text-white font-bold shadow-md"
                            : isToday
                                ? "bg-purple-50 text-purple-600 border border-purple-200 font-bold"
                                : "hover:bg-purple-100 text-gray-700"
                        }`}
                >
                    {day}
                </button>
            );
        }
        return days;
    };

    return (
        <div className="p-4 bg-white border border-gray-200 rounded-xl shadow-2xl w-72 animate-in fade-in zoom-in duration-200">
            <div className="flex justify-between items-center mb-4">
                <button
                    type="button"
                    onClick={() => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1, 1))}
                    className="p-1.5 hover:bg-purple-50 hover:text-purple-600 rounded-full text-gray-600 transition-colors"
                >
                    &lt;
                </button>
                <div className="text-sm font-bold text-gray-800">
                    {currentMonth.toLocaleString("default", { month: "long" })} {currentMonth.getFullYear()}
                </div>
                <button
                    type="button"
                    onClick={() => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 1))}
                    className="p-1.5 hover:bg-purple-50 hover:text-purple-600 rounded-full text-gray-600 transition-colors"
                >
                    &gt;
                </button>
            </div>
            <div className="grid grid-cols-7 gap-1 mb-2">
                {["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"].map((day) => (
                    <div key={day} className="h-8 w-8 flex items-center justify-center text-xs font-bold text-gray-400 uppercase">
                        {day}
                    </div>
                ))}
            </div>
            <div className="grid grid-cols-7 gap-1">
                {renderDays()}
            </div>
            <div className="mt-4 pt-3 border-t border-gray-100 flex justify-center">
                <button
                    type="button"
                    onClick={() => {
                        onChange(new Date());
                        onClose();
                    }}
                    className="text-xs font-bold text-purple-600 hover:text-purple-700 uppercase tracking-wider"
                >
                    Go to Today
                </button>
            </div>
        </div>
    );
};

export default CalendarComponent;

import React, { useEffect, useState, useCallback } from 'react';
import { CheckCircle2, AlertCircle, Info, X, Sparkles } from 'lucide-react';

const MagicToast = ({ message, type, onClose, duration }) => {
    const [isExiting, setIsExiting] = useState(false);
    const [progress, setProgress] = useState(100);

    const handleClose = useCallback(() => {
        setIsExiting(true);
        setTimeout(onClose, 400); // Wait for exit animation
    }, [onClose]);

    useEffect(() => {
        const startTime = Date.now();
        const interval = setInterval(() => {
            const elapsed = Date.now() - startTime;
            const remaining = Math.max(0, 100 - (elapsed / duration) * 100);
            setProgress(remaining);
            if (remaining === 0) {
                handleClose();
            }
        }, 10);

        return () => clearInterval(interval);
    }, [duration, handleClose]);

    const getConfig = () => {
        switch (type) {
            case 'success':
                return {
                    icon: <CheckCircle2 className="w-6 h-6 text-emerald-500" />,
                    bg: 'bg-emerald-50/90',
                    border: 'border-emerald-200',
                    accent: 'bg-emerald-500',
                    shadow: 'shadow-emerald-200/50',
                    title: 'Success'
                };
            case 'error':
                return {
                    icon: <AlertCircle className="w-6 h-6 text-rose-500" />,
                    bg: 'bg-rose-50/90',
                    border: 'border-rose-200',
                    accent: 'bg-rose-500',
                    shadow: 'shadow-rose-200/50',
                    title: 'Action Failed'
                };
            default:
                return {
                    icon: <Info className="w-6 h-6 text-sky-500" />,
                    bg: 'bg-sky-50/90',
                    border: 'border-sky-200',
                    accent: 'bg-sky-500',
                    shadow: 'shadow-sky-200/50',
                    title: 'Information'
                };
        }
    };

    const config = getConfig();

    return (
        <div
            className={`pointer-events-auto relative flex flex-col min-w-[320px] max-w-[400px] overflow-hidden rounded-2xl border ${config.border} ${config.bg} backdrop-blur-md shadow-2xl ${config.shadow} transition-all duration-500 ease-out animate-toast-slide-in ${isExiting ? 'animate-toast-slide-out' : ''}`}
        >
            {/* Main Content */}
            <div className="flex p-4 items-start gap-4">
                <div className={`p-2 rounded-xl bg-white shadow-sm flex-shrink-0`}>
                    {config.icon}
                </div>

                <div className="flex-grow pt-0.5">
                    <div className="flex items-center gap-2 mb-1">
                        <h4 className="text-sm font-black text-gray-900 uppercase tracking-wider">{config.title}</h4>
                        {type === 'success' && <Sparkles className="w-3 h-3 text-amber-400 animate-pulse" />}
                    </div>
                    <p className="text-xs font-semibold text-gray-600 leading-relaxed uppercase">
                        {message}
                    </p>
                </div>

                <button
                    onClick={handleClose}
                    className="p-1 hover:bg-black/5 rounded-lg transition-colors text-gray-400 hover:text-gray-600"
                >
                    <X size={16} strokeWidth={3} />
                </button>
            </div>

            {/* Progress Bar */}
            <div className="h-1 w-full bg-black/5">
                <div
                    className={`h-full ${config.accent} transition-all duration-100 linear`}
                    style={{ width: `${progress}%` }}
                />
            </div>
        </div>
    );
};

export default MagicToast;

import React, { useState } from 'react';
import { Play, FileText, Image as ImageIcon, Link as LinkIcon, X, Maximize2, ExternalLink } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import AudioPlayer from './AudioPlayer';

const getYouTubeId = (url) => {
    if (!url || typeof url !== 'string') return null;
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
};

const MediaViewer = ({ isOpen, onClose, media }) => {
    const isYoutube = media.type === 'youtube';
    const isVideo = media.type === 'video';
    const isImage = media.type.startsWith('image') || media.type === 'image';
    const isPdf = media.type === 'pdf' || (media.url && media.url.toLowerCase().endsWith('.pdf'));

    const modalSizeClass = "max-w-5xl";

    return (
        <AnimatePresence>
            {isOpen && (
                <div key="media-viewer-container" className="fixed inset-0 z-[10000] flex items-center justify-center p-4 md:p-8">
                    <motion.div 
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        onClick={onClose}
                        className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm"
                    />

                    <motion.div 
                        initial={{ opacity: 0, scale: 0.95, y: 30 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: 30 }}
                        transition={{ type: 'spring', damping: 25, stiffness: 300 }}
                        className={`relative w-full ${modalSizeClass} max-h-full bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col border border-white/20`}
                    >
                        {/* Modal Header */}
                        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 bg-white/80 backdrop-blur-md sticky top-0 z-10">
                            <div className="flex items-center gap-3">
                                <div className={`p-2 rounded-xl ${isYoutube ? 'bg-red-50 text-red-600' : isVideo ? 'bg-indigo-50 text-indigo-600' : isImage ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'}`}>
                                    {isYoutube ? <Play size={18} fill="currentColor" /> : 
                                    isVideo ? <Play size={18} fill="currentColor" /> : 
                                    isImage ? <ImageIcon size={18} /> : 
                                    <FileText size={18} />}
                                </div>
                                <div className="flex flex-col">
                                    <span className="text-xs font-black text-gray-400 uppercase tracking-widest leading-none mb-1">
                                        {isYoutube ? 'YouTube Content' : isVideo ? 'Video Content' : isImage ? 'Image Content' : 'Document Content'}
                                    </span>
                                    <span className="text-sm font-black text-gray-900 truncate max-w-[200px] sm:max-w-md">
                                        {(media.url.split('/').pop().split('?')[0])}
                                    </span>
                                </div>
                            </div>
                            <div className="flex items-center gap-2">
                                <button 
                                    onClick={() => window.open(media.url, '_blank')}
                                    className="p-2.5 text-gray-500 hover:text-indigo-600 hover:bg-indigo-50 rounded-2xl transition-all group hidden lg:flex items-center gap-2"
                                    title="Open in new tab"
                                >
                                    <span className="text-xs font-bold uppercase tracking-wider">Expand</span>
                                    <ExternalLink size={18} />
                                </button>
                                <button 
                                    onClick={onClose}
                                    className="p-2.5 text-gray-500 hover:text-rose-600 hover:bg-rose-50 rounded-2xl transition-all"
                                >
                                    <X size={22} className="stroke-[2.5]" />
                                </button>
                            </div>
                        </div>

                        {/* Modal Content */}
                        <div className="flex-grow overflow-auto flex items-center justify-center bg-[#0a0a0a] min-h-[40vh] relative group">
                            {isYoutube ? (
                                <div className="w-full aspect-video max-h-[80vh]">
                                    <iframe
                                        key={media.ytId || 'yt'}
                                        src={`https://www.youtube.com/embed/${media.ytId}?autoplay=1&rel=0&modestbranding=1`}
                                        className="w-full h-full border-none shadow-2xl"
                                        title="YouTube Video"
                                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                                        allowFullScreen
                                    />
                                </div>
                            ) : isVideo ? (
                                <video 
                                    key={media.url || 'vid'}
                                    src={media.url} 
                                    controls 
                                    autoPlay 
                                    className="max-w-full max-h-[80vh] shadow-2xl"
                                />
                            ) : isImage ? (
                                <img 
                                    src={media.url} 
                                    alt="Shared Media" 
                                    className="max-w-full max-h-[80vh] object-contain shadow-2xl select-none"
                                    onContextMenu={(e) => e.preventDefault()}
                                />
                            ) : (
                                <iframe 
                                    key={media.url || 'doc'}
                                    src={media.url} 
                                    className="w-full h-[80vh] bg-white border-none shadow-2xl"
                                    title="Document Viewer"
                                />
                            )}

                            {/* Overlay Controls Hint for Image/Video */}
                            {(isImage || isVideo) && (
                                <div className="absolute bottom-6 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none">
                                    <div className="px-4 py-2 bg-black/50 backdrop-blur-md rounded-full border border-white/10 flex items-center gap-3">
                                        <div className="flex items-center gap-1.5 px-2 border-r border-white/20">
                                            <Maximize2 size={12} className="text-white" />
                                            <span className="text-[10px] font-bold text-white uppercase tracking-widest whitespace-nowrap">Full Gallery View</span>
                                        </div>
                                        <span className="text-[10px] font-bold text-gray-300 uppercase tracking-widest whitespace-nowrap">Scroll to Zoom</span>
                                    </div>
                                </div>
                            )}
                        </div>
                    </motion.div>
                </div>
            )}
        </AnimatePresence>
    );
};

const RenderDescription = ({ text, audioUrl, instructionUrl, instructionType }) => {
    const [viewerOpen, setViewerOpen] = useState(false);
    const [viewerMedia, setViewerMedia] = useState({ url: '', type: '', ytId: '' });

    if (!text && !audioUrl && !instructionUrl) return <span className="text-gray-400">—</span>;

    const urlRegex = /(https?:\/\/[^\s]+(?:voice-notes|audio-recordings)[^\s]*\.(?:mp3|wav|ogg|webm|m4a|aac)(\?.*)?)/i;
    let match = null;
    if (text && typeof text === 'string') {
        match = text.match(urlRegex);
    }

    let url = audioUrl || (match ? match[0] : null);
    let cleanText = text || '';

    if (match && !audioUrl) {
        cleanText = text.replace(match[0], '')
            .replace(/Voice Note Link:/i, '')
            .replace(/Voice Note:/i, '')
            .trim();
    }

    const openViewer = (url, type) => {
        const ytId = getYouTubeId(url);
        if (ytId) {
            setViewerMedia({ url, type: 'youtube', ytId });
            setViewerOpen(true);
            return;
        }

        if (type === 'link') {
            window.open(url, '_blank');
            return;
        }
        setViewerMedia({ url, type });
        setViewerOpen(true);
    };

    const renderInstruction = () => {
        if (!instructionUrl || !instructionType || instructionType === 'none') return null;
        let urls = [];
        let types = [];
        try {
            urls = JSON.parse(instructionUrl);
            types = JSON.parse(instructionType);
            if (!Array.isArray(urls)) {
                urls = [instructionUrl];
                types = [instructionType];
            }
        } catch (e) {
            urls = [instructionUrl];
            types = [instructionType];
        }

        const rules = [];
        const others = [];

        urls.forEach((attachmentUrl, idx) => {
            const type = types[idx] || 'link';
            if (type === 'rule') {
                rules.push({ url: attachmentUrl, idx });
            } else {
                others.push({ url: attachmentUrl, type, idx });
            }
        });

        return (
            <div className="flex flex-col gap-2 w-full">
                {rules.map((rule) => (
                    <div key={`rule-${rule.idx}`} className="mt-1 px-2.5 py-1 bg-rose-50/50 border border-rose-100 rounded-xl w-fit">
                        <p className="text-[12px] font-bold text-rose-600 leading-relaxed italic">
                            {rule.url}
                        </p>
                    </div>
                ))}
                {others.length > 0 && (
                    <div className="flex flex-wrap gap-2 mt-1">
                        {others.map((item) => {
                            const ytId = getYouTubeId(item.url);
                            let iconLabel = "Reference";
                            let Icon = LinkIcon;
                            let colorClass = "text-indigo-700 bg-indigo-50 border-indigo-100";

                            if (item.type === 'video' || ytId) {
                                iconLabel = "Video";
                                Icon = Play;
                                if (ytId) colorClass = "text-red-700 bg-red-50 border-red-100";
                            } else if (item.type === 'image') {
                                iconLabel = "Image";
                                Icon = ImageIcon;
                                colorClass = "text-emerald-700 bg-emerald-50 border-emerald-100";
                            } else if (item.type === 'pdf') {
                                iconLabel = "Doc/PDF";
                                Icon = FileText;
                                colorClass = "text-blue-700 bg-blue-50 border-blue-100";
                            }

                            return (
                                <button
                                    key={item.idx}
                                    onClick={(e) => {
                                        e.preventDefault();
                                        e.stopPropagation();
                                        openViewer(item.url, item.type);
                                    }}
                                    className={`flex items-center gap-1.5 text-[10px] sm:text-xs font-black uppercase tracking-tight border px-2.5 py-1.5 rounded-xl hover:shadow-lg hover:scale-105 active:scale-95 transition-all shadow-sm w-fit ${colorClass}`}
                                    title={`View ${iconLabel}`}
                                >
                                    <Icon size={12} strokeWidth={3} className={ytId ? 'fill-current' : ''} />
                                    {iconLabel}
                                </button>
                            );
                        })}
                    </div>
                )}
            </div>
        );
    };

    return (
        <div className="flex flex-col min-w-[180px] max-w-full">
            {cleanText && (
                <span className="whitespace-pre-wrap text-[13px] font-medium text-gray-800 leading-relaxed mb-1.5">
                    {cleanText}
                </span>
            )}

            <div className="flex flex-wrap items-center gap-2">
