              ) : (
              <div className="p-6 space-y-6 flex flex-col flex-1 overflow-y-auto min-h-0">
                  {/* System Level Access */}
                  <div>
                    <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-3">System Module Access</h4>
