            {/* Selected Date Events */}
            {selectedDate && (
              <div className="bg-white rounded-xl shadow-lg border p-6">
                <h3 className="text-lg font-bold text-gray-800 mb-4">
                  Events on {months[currentDate.getMonth()]} {selectedDate}
