                  <input
                    type="date"
                    required
                    value={form.date_of_leaving}
                    onChange={(e) => set('date_of_leaving', e.target.value)}
                    className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 bg-white text-gray-900"
                  />
