import { useState, useEffect, useRef, useMemo } from "react";
import { Play, Pause } from "lucide-react";

/**
 * Shared AudioPlayer component to handle voice notes and other audio recordings.
 */
const AudioPlayer = ({ url, className = "" }) => {
    const [isPlaying, setIsPlaying] = useState(false);
    const [hasInteracted, setHasInteracted] = useState(false);
    const audioRef = useRef(null);

    const cacheBustedUrl = useMemo(() => {
        if (!url) return url;
        if (url.startsWith('blob:')) return url;
        const separator = url.includes('?') ? '&' : '?';
        return `${url}${separator}cb=${Date.now()}`;
    }, [url]);

    const togglePlay = (e) => {
        if (e && e.stopPropagation) e.stopPropagation();

        if (!hasInteracted) {
            setHasInteracted(true);
            return;
        }

        if (isPlaying) {
            audioRef.current.pause();
        } else {
            audioRef.current.play().catch(err => {
                console.error("Playback failed:", err);
            });
        }
    };

    useEffect(() => {
        if (hasInteracted && audioRef.current && !isPlaying) {
            audioRef.current.play().catch(err => {
                console.error("Lazy Playback failed:", err);
            });
            setIsPlaying(true);
        }
    }, [hasInteracted]);

    useEffect(() => {
        const audio = audioRef.current;
        if (!audio) return;

        const handleEnded = () => setIsPlaying(false);
        const handlePause = () => setIsPlaying(false);
        const handlePlay = () => setIsPlaying(true);

        audio.addEventListener('ended', handleEnded);
        audio.addEventListener('pause', handlePause);
        audio.addEventListener('play', handlePlay);

        return () => {
            audio.removeEventListener('ended', handleEnded);
            audio.removeEventListener('pause', handlePause);
            audio.removeEventListener('play', handlePlay);
        };
    }, [hasInteracted]);

    return (
        <div className={`flex items-center gap-2.5 px-2.5 py-1.5 rounded-lg border transition-all duration-300 w-fit min-w-[120px] shadow-sm bg-white border-violet-100 hover:border-violet-200 hover:shadow-md ${isPlaying ? 'bg-violet-50/80 border-violet-300 scale-[1.02]' : ''} ${className}`}>
            <button
                type="button"
                onClick={togglePlay}
                className={`w-7 h-7 rounded-full flex items-center justify-center transition-all duration-300 shadow-sm ${isPlaying
                    ? 'bg-gradient-to-r from-rose-500 to-pink-600'
                    : 'bg-gradient-to-r from-violet-500 to-fuchsia-600 hover:scale-110 active:scale-95'
                    }`}
            >
                {isPlaying ? (
                    <Pause size={12} className="text-white fill-white" />
                ) : (
                    <Play size={12} className="text-white fill-white ml-0.5" />
                )}
            </button>
            <div className="flex flex-col">
                <span className={`text-[9px] font-black uppercase tracking-[0.1em] ${isPlaying ? 'text-violet-700' : 'text-gray-400'}`}>
                    {isPlaying ? 'Playing...' : 'Voice Note'}
                </span>
                {isPlaying && (
                    <div className="flex gap-0.5 mt-0.5 h-1.5 items-center">
                        <div className="w-0.5 h-full bg-violet-400 animate-bounce" style={{ animationDuration: '0.6s' }}></div>
                        <div className="w-0.5 h-2/3 bg-violet-500 animate-bounce" style={{ animationDuration: '0.8s' }}></div>
                        <div className="w-0.5 h-full bg-violet-600 animate-bounce" style={{ animationDuration: '0.4s' }}></div>
                        <div className="w-0.5 h-2/3 bg-violet-500 animate-bounce" style={{ animationDuration: '0.7s' }}></div>
                    </div>
                )}
            </div>
            {hasInteracted && <audio ref={audioRef} src={cacheBustedUrl} className="hidden" preload="auto" />}
        </div>
    );
};

export default AudioPlayer;

import React, { useState } from "react";

const CalendarComponent = ({ date, onChange, onClose }) => {
    const [currentMonth, setCurrentMonth] = useState(date && !isNaN(new Date(date).getTime()) ? new Date(date) : new Date());

    const getDaysInMonth = (year, month) => new Date(year, month + 1, 0).getDate();
    const getFirstDayOfMonth = (year, month) => new Date(year, month, 1).getDay();

    const handleDateClick = (day) => {
        const selectedDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
        onChange(selectedDate);
        onClose();
    };

    const renderDays = () => {
        const days = [];
        const daysInMonth = getDaysInMonth(currentMonth.getFullYear(), currentMonth.getMonth());
        const firstDayOfMonth = getFirstDayOfMonth(currentMonth.getFullYear(), currentMonth.getMonth());

        for (let i = 0; i < firstDayOfMonth; i++) {
            days.push(<div key={`empty-${i}`} className="h-8 w-8"></div>);
        }

        for (let day = 1; day <= daysInMonth; day++) {
            const dateToCheck = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
            const isSelected = date &&
                date.getDate() === day &&
                date.getMonth() === currentMonth.getMonth() &&
                date.getFullYear() === currentMonth.getFullYear();

            const isToday = new Date().toDateString() === dateToCheck.toDateString();

            days.push(
                <button
                    key={day}
                    type="button"
                    onClick={() => handleDateClick(day)}
                    className={`h-8 w-8 rounded-full flex items-center justify-center text-sm transition-colors ${isSelected
                            ? "bg-purple-600 text-white font-bold shadow-md"
                            : isToday
                                ? "bg-purple-50 text-purple-600 border border-purple-200 font-bold"
                                : "hover:bg-purple-100 text-gray-700"
                        }`}
                >
                    {day}
                </button>
            );
        }
        return days;
    };

    return (
        <div className="p-4 bg-white border border-gray-200 rounded-xl shadow-2xl w-72 animate-in fade-in zoom-in duration-200">
            <div className="flex justify-between items-center mb-4">
                <button
                    type="button"
                    onClick={() => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1, 1))}
                    className="p-1.5 hover:bg-purple-50 hover:text-purple-600 rounded-full text-gray-600 transition-colors"
                >
                    &lt;
                </button>
                <div className="text-sm font-bold text-gray-800">
                    {currentMonth.toLocaleString("default", { month: "long" })} {currentMonth.getFullYear()}
                </div>
                <button
                    type="button"
                    onClick={() => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 1))}
                    className="p-1.5 hover:bg-purple-50 hover:text-purple-600 rounded-full text-gray-600 transition-colors"
                >
                    &gt;
                </button>
            </div>
            <div className="grid grid-cols-7 gap-1 mb-2">
                {["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"].map((day) => (
                    <div key={day} className="h-8 w-8 flex items-center justify-center text-xs font-bold text-gray-400 uppercase">
                        {day}
                    </div>
                ))}
            </div>
            <div className="grid grid-cols-7 gap-1">
                {renderDays()}
            </div>
            <div className="mt-4 pt-3 border-t border-gray-100 flex justify-center">
                <button
                    type="button"
                    onClick={() => {
                        onChange(new Date());
                        onClose();
                    }}
                    className="text-xs font-bold text-purple-600 hover:text-purple-700 uppercase tracking-wider"
                >
                    Go to Today
                </button>
            </div>
        </div>
    );
};

export default CalendarComponent;

import React, { useEffect, useState, useCallback } from 'react';
import { CheckCircle2, AlertCircle, Info, X, Sparkles } from 'lucide-react';

const MagicToast = ({ message, type, onClose, duration }) => {
    const [isExiting, setIsExiting] = useState(false);
    const [progress, setProgress] = useState(100);

    const handleClose = useCallback(() => {
        setIsExiting(true);
        setTimeout(onClose, 400); // Wait for exit animation
    }, [onClose]);

    useEffect(() => {
        const startTime = Date.now();
        const interval = setInterval(() => {
            const elapsed = Date.now() - startTime;
            const remaining = Math.max(0, 100 - (elapsed / duration) * 100);
            setProgress(remaining);
            if (remaining === 0) {
                handleClose();
            }
        }, 10);

        return () => clearInterval(interval);
    }, [duration, handleClose]);

    const getConfig = () => {
        switch (type) {
            case 'success':
                return {
                    icon: <CheckCircle2 className="w-6 h-6 text-emerald-500" />,
                    bg: 'bg-emerald-50/90',
                    border: 'border-emerald-200',
                    accent: 'bg-emerald-500',
                    shadow: 'shadow-emerald-200/50',
                    title: 'Success'
                };
            case 'error':
                return {
                    icon: <AlertCircle className="w-6 h-6 text-rose-500" />,
                    bg: 'bg-rose-50/90',
                    border: 'border-rose-200',
                    accent: 'bg-rose-500',
                    shadow: 'shadow-rose-200/50',
                    title: 'Action Failed'
                };
            default:
                return {
                    icon: <Info className="w-6 h-6 text-sky-500" />,
                    bg: 'bg-sky-50/90',
                    border: 'border-sky-200',
                    accent: 'bg-sky-500',
                    shadow: 'shadow-sky-200/50',
                    title: 'Information'
                };
        }
    };

    const config = getConfig();

    return (
        <div
            className={`pointer-events-auto relative flex flex-col min-w-[320px] max-w-[400px] overflow-hidden rounded-2xl border ${config.border} ${config.bg} backdrop-blur-md shadow-2xl ${config.shadow} transition-all duration-500 ease-out animate-toast-slide-in ${isExiting ? 'animate-toast-slide-out' : ''}`}
        >
            {/* Main Content */}
            <div className="flex p-4 items-start gap-4">
                <div className={`p-2 rounded-xl bg-white shadow-sm flex-shrink-0`}>
                    {config.icon}
                </div>

                <div className="flex-grow pt-0.5">
                    <div className="flex items-center gap-2 mb-1">
                        <h4 className="text-sm font-black text-gray-900 uppercase tracking-wider">{config.title}</h4>
                        {type === 'success' && <Sparkles className="w-3 h-3 text-amber-400 animate-pulse" />}
                    </div>
                    <p className="text-xs font-semibold text-gray-600 leading-relaxed uppercase">
                        {message}
                    </p>
                </div>

                <button
                    onClick={handleClose}
