              { id: "part_name", label: "Part" },
              { id: "part_area", label: "Area" },
              { id: "planned_date", label: "Planned" },
              { id: "freq", label: "Freq" },
              { id: "require_attachment", label: "Attach" },
              { id: "submission_date", label: "Actual" },
