// --- AUDIO UTILITIES ---
const isAudioUrl = (url) => {
    if (!url || typeof url !== 'string') return false;
    return url.startsWith('http') && (
        url.includes('audio-recordings') ||
        url.includes('voice-notes') ||
        url.match(/\.(mp3|wav|ogg|webm|m4a|aac)(\?.*)?$/i)
    );
};

const defaultTask = () => ({
    id: Date.now() + Math.random(),
    filledBy: "",
    assignedPerson: "",
    machineName: "",
    issueDetails: "",
    duration: "",
    attachment: false,
    recordedAudio: null,
});

// Single Repair Task Card
function RepairTaskCard({ task, index, total, givenBy, userData, machineOptions, onUpdate, onRemove }) {
    const handleChange = (e) => onUpdate(task.id, { [e.target.name]: e.target.value });

    // Filter doers based on user status, leave, and HOD permissions
    const getFilteredDoers = () => {
        if (!userData || !Array.isArray(userData)) return [];
        const today = new Date();
        today.setHours(0, 0, 0, 0);

        return userData.filter(u => {
            // If they are on leave, check the dates
            if ((u.status === 'on leave' || u.status === 'on_leave') && u.leave_date && u.leave_end_date) {
                const leaveS = new Date(u.leave_date);
                const leaveE = new Date(u.leave_end_date);
                leaveS.setHours(0, 0, 0, 0);
                leaveE.setHours(0, 0, 0, 0);

                if (today >= leaveS && today <= leaveE) {
                    return false; // Currently on leave
                }
            } else if (u.status !== 'active') {
                return false; // Skip inactive and other non-active statuses
            }

            // HOD Restriction & Reporting Group Filter
            const currentU = (localStorage.getItem("user-name") || "").toLowerCase().trim();
            const currentR = (localStorage.getItem("role") || "").toLowerCase().trim();

            if (currentR === "hod") {
                const dName = (u.user_name || u.name || "").toLowerCase().trim();
                const reportedBy = (u.reported_by || "").toLowerCase().trim();

                // Only show themselves OR their direct reports
                if (dName !== currentU && reportedBy !== currentU) return false;

                // If it's themselves, check for explicit self-assign rights
                if (dName === currentU && !u.can_self_assign) return false;
            }

            return true;
        });
    };

    return (
        <div className="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-visible hover:shadow-md transition-all duration-300">
            {/* Card Header */}
            <div className="flex items-center justify-between px-5 py-3.5 bg-gradient-to-r from-purple-50 to-indigo-50 border-b border-purple-100 rounded-t-2xl">
                <div className="flex items-center gap-2.5">
                    <div className="w-7 h-7 rounded-full bg-purple-600 text-white flex items-center justify-center text-xs font-black shadow-sm">
                        {index + 1}
                    </div>
                    <span className="text-sm font-bold text-purple-800">Repair Request {index + 1}</span>
                    {task.machineName && <span className="text-xs text-purple-500 font-medium">— {task.machineName}</span>}
                </div>
                {total > 1 && (
                    <button type="button" onClick={() => onRemove(task.id)} className="p-1.5 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all">
                        <Trash2 className="w-4 h-4" />
                    </button>
                )}
            </div>

            <div className="p-5 space-y-4">
                {/* Assign From (Filled By) */}
                <div>
                    <label className="block text-xs font-bold text-gray-600 mb-1.5 uppercase tracking-wide">Assign From (Filled By) <span className="text-red-500">*</span></label>
                    <select
                            name="filledBy"
                            value={task.filledBy}
                            onChange={handleChange}
                            className={`w-full p-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 outline-none bg-gray-50 focus:bg-white transition-all text-sm`}
                        >
                            <option value="">Select person...</option>
                            {givenBy.map(opt => <option key={opt} value={opt}>{opt}</option>)}
                        </select>
                </div>

                {/* Machine Name & Assign To */}
                <div className="grid grid-cols-2 gap-3">
                    <div>
                        <label className="block text-xs font-bold text-gray-600 mb-1.5 uppercase tracking-wide">Machine Name <span className="text-red-500">*</span></label>
                        <select name="machineName" value={task.machineName} onChange={handleChange} className="w-full p-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 outline-none bg-gray-50 focus:bg-white transition-all text-sm">
                            <option value="">Select machine...</option>
                            {machineOptions.map(opt => <option key={opt} value={opt}>{opt}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-600 mb-1.5 uppercase tracking-wide">Assign To <span className="text-red-500">*</span></label>
                        <select name="assignedPerson" value={task.assignedPerson} onChange={handleChange} className="w-full p-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 outline-none bg-gray-50 focus:bg-white transition-all text-sm">
                            <option value="">Select person...</option>
                            {getFilteredDoers().map(user => (
                                <option key={user.id} value={user.user_name}>{user.user_name}</option>
                            ))}
                        </select>
                    </div>
                </div>

                {/* Duration */}
                <div>
                    <label className="block text-xs font-bold text-gray-600 mb-1.5 uppercase tracking-wide flex items-center gap-1">
                        <Clock className="w-3 h-3" /> Duration
                    </label>
                    <div className="relative">
                        <input
                            type="number"
                            min="1"
                            name="duration"
                            value={task.duration ? task.duration.replace(' MIN', '') : ''}
                            onChange={(e) => {
                                const val = e.target.value;
                                onUpdate(task.id, { duration: val ? `${val} MIN` : '' });
                            }}
                            placeholder="e.g. 30"
                            className="w-full pl-3 pr-12 p-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 outline-none bg-gray-50 focus:bg-white transition-all text-sm"
                        />
                        <span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs font-bold text-gray-400">MIN</span>
                    </div>
                </div>

                {/* Issue Details with Voice Note */}
                <div>
                    <label className="block text-xs font-bold text-gray-600 mb-1.5 uppercase tracking-wide">Issue Details <span className="text-red-500">*</span></label>
                    <ReactMediaRecorder
                        audio
                        onStop={(blobUrl, blob) => onUpdate(task.id, { recordedAudio: { blobUrl, blob } })}
                        render={({ status, startRecording, stopRecording, clearBlobUrl }) => (
                            <div>
                                {status !== 'recording' && (
                                    <div className="relative mb-3">
                                        <textarea
                                            name="issueDetails"
                                            value={task.issueDetails}
                                            onChange={handleChange}
                                            rows="3"
                                            placeholder="Describe the issue in detail..."
                                            className="w-full p-3 pr-11 border border-gray-200 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 outline-none resize-none bg-gray-50 focus:bg-white transition-all text-sm"
                                        />
                                        <button type="button" onClick={startRecording} className="absolute bottom-2.5 right-2.5 p-1.5 bg-purple-100 text-purple-600 rounded-full hover:bg-purple-200 transition-all" title="Record Voice Note">
                                            <Mic className="w-4 h-4" />
                                        </button>
                                    </div>
                                )}
                                {status === 'recording' && (
                                    <div className="flex items-center justify-between p-3 bg-red-50 border border-red-200 rounded-lg animate-pulse mb-3">
                                        <div className="flex items-center gap-2">
                                            <div className="w-2 h-2 bg-red-500 rounded-full animate-ping" />
                                            <span className="text-red-600 font-bold text-sm">Recording...</span>
                                        </div>
                                        <button type="button" onClick={stopRecording} className="flex items-center gap-1.5 px-3 py-1.5 bg-red-600 text-white rounded-lg text-xs font-bold">
                                            <Square className="w-3 h-3" /> Stop
                                        </button>
                                    </div>
                                )}
                                {task.recordedAudio && status !== 'recording' && (
                                    <div className="p-3 bg-purple-50 border border-purple-200 rounded-lg">
                                        <div className="flex items-center justify-between mb-2">
                                            <span className="text-xs font-bold text-purple-700 flex items-center gap-1.5">
                                                <Mic className="w-3 h-3" /> Voice Note Attached
                                            </span>
                                            <button type="button" onClick={() => { clearBlobUrl(); onUpdate(task.id, { recordedAudio: null }); }} className="text-xs text-red-500 hover:text-red-700 font-bold flex items-center gap-1">
                                                <Trash2 className="w-3 h-3" /> Remove
                                            </button>
                                        </div>
                                        <AudioPlayer url={task.recordedAudio.blobUrl} />
                                    </div>
                                )}
                            </div>
                        )}
                    />
                </div>

                {/* Attachment Toggle */}
                <div className="pt-2">
                    <button
                        type="button"
                        onClick={() => onUpdate(task.id, { attachment: !task.attachment })}
                        className={`w-full flex items-center justify-between px-4 py-2.5 rounded-xl border text-xs font-bold transition-all duration-200 ${task.attachment ? 'bg-purple-50 border-purple-200 text-purple-700 shadow-sm' : 'bg-gray-50 border-gray-200 text-gray-400 group-hover:border-gray-300'}`}
                    >
                        <div className="flex items-center gap-2">
                            <Plus className={`w-3.5 h-3.5 transition-transform ${task.attachment ? 'rotate-45' : ''}`} />
                            <span>Require Attachment / Proof</span>
                        </div>
                        <div className={`w-9 h-5 flex items-center rounded-full p-1 transition-colors ${task.attachment ? 'bg-purple-600' : 'bg-gray-300'}`}>
                            <div className={`bg-white w-3 h-3 rounded-full shadow-sm transform transition-transform ${task.attachment ? 'translate-x-4' : ''}`} />
                        </div>
                    </button>
                    {task.attachment && (
                        <p className="mt-1.5 px-1 text-[10px] text-purple-500 font-medium">
                            The doer will be required to upload a photo to complete this repair task.
                        </p>
                    )}
                </div>
            </div>
        </div>
    );
}

export default function RepairTask() {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const { showToast } = useMagicToast();
    const { givenBy } = useSelector((state) => state.assignTask);
    const { customDropdowns = [], userData = [] } = useSelector((state) => state.setting || {});
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [tasks, setTasks] = useState([
        { 
            ...defaultTask(), 
            filledBy: (localStorage.getItem("role") === "HOD" || (localStorage.getItem("role") === "admin" && localStorage.getItem("user-name") !== "admin")) ? localStorage.getItem("user-name") : "" 
        }
    ]);
    const [holidays, setHolidays] = useState([]);
    const [isTodayWorkingDay, setIsTodayWorkingDay] = useState(true);

    const getUniqueDropdownValues = (category) => {
        const items = customDropdowns.filter(item => item.category === category);
        const uniqueValues = [...new Set(items.map(item => item.value))];
        return uniqueValues.map(value => { const item = items.find(i => i.value === value); return { ...item, value }; });
    };

    useEffect(() => {
        const fetchHolidaysAndWorkingDays = async () => {
            const todayStr = new Date().toISOString().split('T')[0];

            // Fetch holidays
            const { data: holidayData } = await supabase.from('holidays').select('holiday_date');
            if (holidayData) setHolidays(holidayData.map(h => h.holiday_date));

            // Fetch working days for today
            const { data: workingData } = await supabase
                .from('working_day_calender')
                .select('working_date')
                .eq('working_date', todayStr)
                .single();

            if (workingData) setIsTodayWorkingDay(true);
            else setIsTodayWorkingDay(false);
        };
        fetchHolidaysAndWorkingDays();
        dispatch(uniqueGivenByData());
        dispatch(customDropdownDetails());
        dispatch(userDetails());
    }, [dispatch]);

    const machineOptions = getUniqueDropdownValues("Machine Name").map(i => i.value).length > 0
        ? getUniqueDropdownValues("Machine Name").map(i => i.value)
        : ["A", "B", "C", "D", "E", "F", "G", "H", "I", "Atlas compressor", "ELGI Compreser", "Transformers", "65/18 Pipe Extruder", "52/18 Pipe Extruder", "C/c Capping Exturder", "Polveiger machine", "Printer A", "Printer B", "Other"];

    const updateTask = (id, updates) => setTasks(prev => prev.map(t => t.id === id ? { ...t, ...updates } : t));
    const addTask = () => setTasks(prev => {
        const lastTask = prev[prev.length - 1];
        return [...prev, {
            ...defaultTask(),
            filledBy: (localStorage.getItem("role") === "HOD" || (localStorage.getItem("role") === "admin" && localStorage.getItem("user-name") !== "admin")) ? localStorage.getItem("user-name") : (lastTask?.filledBy || ""),
            assignedPerson: lastTask?.assignedPerson || ""
        }];
    });
    const removeTask = (id) => setTasks(prev => prev.filter(t => t.id !== id));

    const handleSubmitAll = async () => {
        for (let i = 0; i < tasks.length; i++) {
            const t = tasks[i];
            if (!t.filledBy) {
                showToast(`Request ${i + 1}: Please select 'Assign From' (Filled By).`, 'error');
                return;
            }
            if (!t.assignedPerson || !t.machineName || (!t.issueDetails && !t.recordedAudio)) {
                showToast(`Request ${i + 1}: Please fill in all required fields.`, 'error');
                return;
            }

        }

        // Holiday & Working Day check for today (Repairs are created for today)
        const todayStr = new Date().toISOString().split('T')[0];

        if (holidays.includes(todayStr) || !isTodayWorkingDay) {
            showToast(`Cannot submit repair requests today as it is a ${holidays.includes(todayStr) ? 'holiday' : 'non-working day'} (${todayStr}).`, 'error');
            return;
        }

        setIsSubmitting(true);
        try {
            // 1. Parallelize Audio Uploads
            const audioUploadPromises = tasks.map(async (task) => {
                if (task.recordedAudio && task.recordedAudio.blob) {
                    const fileName = `voice-notes/${Date.now()}-${Math.random().toString(36).substring(7)}.webm`;
                    const { error: uploadError } = await supabase.storage
                        .from('audio-recordings')
                        .upload(fileName, task.recordedAudio.blob, {
                            contentType: task.recordedAudio.blob.type || 'audio/webm',
                            upsert: false
                        });

                    if (uploadError) throw new Error(`Audio Upload Error: ${uploadError.message}`);

                    const { data: publicUrlData } = supabase.storage.from('audio-recordings').getPublicUrl(fileName);
                    return { id: task.id, audioUrl: publicUrlData.publicUrl };
                }
                return { id: task.id, audioUrl: null };
            });

            const uploadedAudioResults = await Promise.all(audioUploadPromises);
            const audioUrlMap = uploadedAudioResults.reduce((map, item) => {
                map[item.id] = item.audioUrl;
                return map;
            }, {});

            // 2. Prepare payload for insertion
            const requestsToInsert = tasks.map(task => ({
                filled_by: task.filledBy,
                assigned_person: task.assignedPerson,
                machine_name: task.machineName,
                issue_description: task.issueDetails,
                audio_url: audioUrlMap[task.id],
                duration: task.duration || null,
                status: 'pending',
                attachment: task.attachment
            }));

            // 3. Chunked Database Inserts (though repairs are usually fewer than Checklist)
            const CHUNK_SIZE = 50;
            const allResults = [];

            for (let i = 0; i < requestsToInsert.length; i += CHUNK_SIZE) {
                const chunk = requestsToInsert.slice(i, i + CHUNK_SIZE);
                const { data, error } = await supabase.from('repair_tasks').insert(chunk).select();
                if (error) throw error;
                if (data) allResults.push(...data);
            }

            // 4. Send WhatsApp notifications
            try {
                if (!isWhatsAppConnected()) {
                    showToast("WhatsApp notifications are currently disabled. They will be enabled later.", "info");
                }
                for (const insertedTask of allResults) {
                    const assignee = insertedTask.assigned_person;
                    if (assignee) {
                        await sendTaskAssignmentNotification({
                            doerName: assignee,
                            taskId: insertedTask.id || insertedTask.task_id,
                            description: insertedTask.issue_description,
                            audioUrl: insertedTask.audio_url,
                            startDate: new Date(insertedTask.created_at).toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' }),
                            givenBy: insertedTask.filled_by,
                            taskType: 'repair',
                            machineName: insertedTask.machine_name,
                        });
                    }
                }
            } catch (whatsappError) {
                console.error('WhatsApp notification error:', whatsappError);
            }

            showToast(`${tasks.length} Repair Request(s) submitted successfully!`, 'success');
            setTasks([defaultTask()]);
            setTimeout(() => navigate('/dashboard/assign-task'), 2000);
        } catch (error) {
            console.error("Submission failed:", error);
            showToast("Failed to submit requests: " + error.message, 'error');
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <AdminLayout>
            <div className="max-w-3xl mx-auto p-4 sm:p-6">
                {/* Header */}
                <div className="flex items-center justify-between mb-6">
                    <div className="flex items-center gap-3">
                        <div className="p-2.5 bg-purple-600 rounded-xl text-white shadow-md">
                            <Save size={20} />
                        </div>
                        <div>
                            <h1 className="text-xl font-black text-gray-900">Repair Request Form</h1>
                            <p className="text-sm text-gray-500 mt-0.5">Submit one or multiple repair requests at once</p>
                        </div>
                    </div>
                    <button onClick={() => navigate(-1)} className="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-xl transition-all">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Task Cards */}
                <div className="space-y-4">
                    {tasks.map((task, index) => (
                        <RepairTaskCard
                            key={task.id}
                            task={task}
                            index={index}
                            total={tasks.length}
                            givenBy={givenBy}
                            userData={userData}
                            machineOptions={machineOptions}
                            onUpdate={updateTask}
                            onRemove={removeTask}
                        />
                    ))}
                </div>

                {/* Add Another */}
                <button
                    type="button"
                    onClick={addTask}
                    className="mt-4 w-full flex items-center justify-center gap-2 py-3 border-2 border-dashed border-purple-300 text-purple-600 font-bold rounded-2xl hover:border-purple-500 hover:bg-purple-50 transition-all duration-200 group"
                >
                    <Plus className="w-5 h-5 group-hover:scale-110 transition-transform" />
                    Add Another Repair Request
                </button>

                {/* Summary & Submit */}
                <div className="mt-5 bg-white rounded-2xl border border-gray-200 shadow-sm p-4">
                    <div className="flex items-center justify-between mb-3">
                        <div>
                            <p className="text-sm font-bold text-gray-700">{tasks.length} request{tasks.length !== 1 ? 's' : ''} ready to submit</p>
                            <p className="text-xs text-gray-400 mt-0.5">Admin will fill in additional details after submission</p>
                        </div>
                        <div className="text-right">
                            <span className="text-2xl font-black text-purple-600">{tasks.length}</span>
                            <p className="text-xs text-gray-400">Total</p>
                        </div>
                    </div>
                    <div className="flex gap-3">
                        <button
                            type="button"
                            onClick={() => navigate('/dashboard/assign-task')}
                            className="flex-1 py-3 bg-gray-100 text-gray-700 font-bold rounded-xl hover:bg-gray-200 transition-all flex items-center justify-center gap-2"
                        >
                            <X className="w-4 h-4" /> Cancel
                        </button>
                        <button
                            type="button"
                            onClick={handleSubmitAll}
                            disabled={isSubmitting}
                            className="flex-grow py-3 bg-purple-600 hover:bg-purple-700 text-white font-bold rounded-xl shadow-md transform transition-all active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? (
                                <><Loader2 size={18} className="animate-spin" /> Submitting...</>
                            ) : (
                                <><Save size={18} /> Submit {tasks.length} Request{tasks.length !== 1 ? 's' : ''}</>
                            )}
                        </button>
                    </div>
                </div>
            </div>
        </AdminLayout>
    );
}

"use client"
import { useState, useEffect, useCallback, useMemo, useRef } from "react"
import { CheckCircle2, Upload, X, Search, History, ArrowLeft, Filter, Calendar, Save, Loader2 } from "lucide-react"
import AdminLayout from "../../components/layout/AdminLayout"
import { useDispatch, useSelector } from "react-redux"
import { checklistData, checklistHistoryData, updateChecklist } from "../../redux/slice/checklistSlice"
import { postChecklistAdminDoneAPI } from "../../redux/api/checkListApi"
import { uniqueDoerNameData } from "../../redux/slice/assignTaskSlice";

export default function AccountDataPage({ showLayout = true, departmentFilter = "" }) {
  const [searchTerm, setSearchTerm] = useState("")
  const [selectedItems, setSelectedItems] = useState(new Set())
  const [additionalData, setAdditionalData] = useState({})
  const [remarksData, setRemarksData] = useState({})
  const [uploadedImages, setUploadedImages] = useState({})
  const [showHistory, setShowHistory] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [successMessage, setSuccessMessage] = useState("")

  // Pagination
  const [currentPagePending, setCurrentPagePending] = useState(1);
  const [currentPageHistory, setCurrentPageHistory] = useState(1);
  const [isFetchingMore, setIsFetchingMore] = useState(false);
  const [isLoadingMoreHistory, setIsLoadingMoreHistory] = useState(false);
  const [hasMoreHistory, setHasMoreHistory] = useState(true);

  // Admin
  const [selectedHistoryItems, setSelectedHistoryItems] = useState([])
  const [markingAsDone, setMarkingAsDone] = useState(false)

  const dispatch = useDispatch();
  const { checklist, loading, history, hasMore, currentPage } = useSelector((state) => state.checkList);

  const userRole = localStorage.getItem("role") || "";

  useEffect(() => {
    dispatch(checklistData(1))
    dispatch(checklistHistoryData(1))
    dispatch(uniqueDoerNameData());
  }, [dispatch])

  // --- Helpers ---
  const handleCheckboxClick = (e, id) => {
    e.stopPropagation()
    const isChecked = e.target.checked
    setSelectedItems(prev => {
      const newSet = new Set(prev)
      if (isChecked) newSet.add(id)
      else {
        newSet.delete(id)
        setAdditionalData(p => { const d = { ...p }; delete d[id]; return d; })
        setRemarksData(p => { const d = { ...p }; delete d[id]; return d; })
      }
      return newSet
    })
  }

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      const allIds = filteredData.map(item => item.id);
      setSelectedItems(new Set(allIds));
    } else {
      setSelectedItems(new Set());
      setAdditionalData({});
      setRemarksData({});
    }
  }

  const handleImageUpload = (id, e) => {
    const file = e.target.files[0];
    if (!file) return;
    const previewUrl = URL.createObjectURL(file);
    setUploadedImages(prev => ({ ...prev, [id]: { file, previewUrl } }));
  };

  const handleSubmit = async () => {
    const selectedIds = Array.from(selectedItems);
    if (selectedIds.length === 0) return alert("Please select items to submit");

    const missingStatus = selectedIds.filter(id => !additionalData[id]);
    if (missingStatus.length > 0) return alert("Please select Status (Yes/No) for all selected items.");

    setIsSubmitting(true);
    try {
      const submissionData = selectedIds.map(id => {
        const item = checklist.find(t => t.id === id);
        const img = uploadedImages[id];
        return {
          taskId: item.id,
          department: item.department,
          givenBy: item.given_by,
          name: item.name,
          taskDescription: item.task_description, // Map correctly
          taskStartDate: item.task_start_date,
          frequency: item.frequency,
          enableReminder: item.enable_reminder,
          requireAttachment: item.require_attachment,
          status: additionalData[id] || "",
          remarks: remarksData[id] || (additionalData[id] === 'no' ? 'Not completed' : ''),
          image: img ? { name: img.file.name, type: img.file.type, previewUrl: img.previewUrl } : null
        };
      });

      await dispatch(updateChecklist(submissionData)).unwrap();
      setSuccessMessage(`Successfully submitted ${selectedIds.length} tasks!`);
      setSelectedItems(new Set());
      setAdditionalData({});
      setRemarksData({});
      setUploadedImages({});
      setTimeout(() => window.location.reload(), 800);
    } catch (e) {
      console.error(e);
      alert("Submission failed");
    } finally {
      setIsSubmitting(false);
    }
  }

  const handleMarkMultipleDone = async () => {
    if (!selectedHistoryItems.length) return;
    if (!confirm(`Mark ${selectedHistoryItems.length} items as Admin Done?`)) return;
    setMarkingAsDone(true);
    try {
      const { error } = await postChecklistAdminDoneAPI(selectedHistoryItems);
      if (error) throw error;
      dispatch(checklistHistoryData(1));
      setSelectedHistoryItems([]);
      setSuccessMessage("Items marked as done.");
    } catch (e) {
      alert("Failed: " + e.message);
    } finally {
      setMarkingAsDone(false);
    }
  }

  const filteredData = useMemo(() => {
    let rawData = showHistory ? history : checklist;
    if (searchTerm) {
      const lower = searchTerm.toLowerCase();
      rawData = rawData.filter(item => Object.values(item).some(v => v && String(v).toLowerCase().includes(lower)));
    }
    if (departmentFilter && departmentFilter !== 'all') {
      rawData = rawData.filter(item => item.department === departmentFilter);
    }

    if (showHistory) return rawData;

    // --- Smart Pending Logic (Deduplication) ---
    const seen = new Set();
    const today = new Date();
    today.setHours(23, 59, 59, 999);

    // Sort ascending by planned_date (or task_start_date)
    const sorted = [...rawData].sort((a, b) => {
      const dateA = new Date(a.planned_date || a.task_start_date).getTime();
      const dateB = new Date(b.planned_date || b.task_start_date).getTime();
      return dateA - dateB;
    });

    return sorted.filter(item => {
      const taskDate = new Date(item.planned_date || item.task_start_date);
      const isUpcoming = taskDate.getTime() > today.getTime();

      if (isUpcoming) {
        // UPCOMING: only show the NEXT (earliest) occurrence per series
        const key = `upcoming::${item.task_description}::${item.name}`;
        if (seen.has(key)) return false;
        seen.add(key);
      } else {
        // OVERDUE & TODAY: show each day individually
        const dateKey = taskDate.toDateString();
        const key = `${item.task_description}::${item.name}::${dateKey}`;
        if (seen.has(key)) return false;
        seen.add(key);
      }
      return true;
    });
  }, [checklist, history, searchTerm, showHistory, departmentFilter]);

  // Infinite Scroll
  const tableRef = useRef(null);
  const handleScroll = () => {
    if (!tableRef.current) return;
    const { scrollTop, scrollHeight, clientHeight } = tableRef.current;
    if (scrollTop + clientHeight >= scrollHeight - 50) {
      if (showHistory) {
        if (!isLoadingMoreHistory && hasMoreHistory) {
          setIsLoadingMoreHistory(true);
          dispatch(checklistHistoryData(currentPageHistory + 1))
            .then(r => {
              if (r.payload?.length < 50) setHasMoreHistory(false);
              setCurrentPageHistory(p => p + 1);
            })
            .finally(() => setIsLoadingMoreHistory(false));
        }
      } else {
        if (!isFetchingMore && hasMore) {
          setIsFetchingMore(true);
          dispatch(checklistData(currentPagePending + 1))
            .then(() => setCurrentPagePending(p => p + 1))
            .finally(() => setIsFetchingMore(false));
        }
      }
    }
  };

  const content = (
    <div className="space-y-4 h-[calc(100vh-100px)] flex flex-col">
      {/* Header - System Standard */}
      <div className="flex flex-col gap-3 flex-shrink-0">
        <div className="flex justify-between items-center">
          <h1 className="text-xl font-bold text-gray-800 flex items-center gap-2">
            {showHistory ? "History Records" : "Checklist Tasks"}
            <span className="text-xs font-normal bg-purple-100 text-purple-700 px-2 py-0.5 rounded-full border border-purple-200">
              {filteredData.length}
            </span>
          </h1>
        </div>

        <div className="flex flex-col sm:flex-row items-center gap-3 bg-gradient-to-r from-purple-50 to-pink-50 p-3 border border-purple-100 rounded-lg shadow-sm">
          <div className="relative flex-grow w-full sm:w-auto">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-purple-400 w-4 h-4" />
            <input
              className="w-full pl-9 pr-3 py-1.5 text-sm border border-purple-200 rounded-md focus:ring-1 focus:ring-purple-400 outline-none bg-white/80"
              placeholder="Search tasks..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="flex items-center gap-2 w-full sm:w-auto flex-shrink-0">
            <button
              onClick={() => setShowHistory(!showHistory)}
              className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-3 py-1.5 text-sm font-medium text-purple-700 bg-white border border-purple-200 rounded-md hover:bg-purple-50 transition-colors shadow-sm"
            >
              {showHistory ? <ArrowLeft className="w-4 h-4" /> : <History className="w-4 h-4" />}
              {showHistory ? "Back to Tasks" : "View History"}
            </button>

            {!showHistory && (
              <button
                onClick={handleSubmit}
                disabled={isSubmitting || selectedItems.size === 0}
                className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-1.5 text-sm font-medium text-white bg-purple-600 rounded-md hover:bg-purple-700 disabled:opacity-50 shadow-sm transition-colors"
              >
                {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                Submit ({selectedItems.size})
              </button>
            )}

            {showHistory && userRole === 'admin' && (
              <button
                onClick={handleMarkMultipleDone}
                disabled={markingAsDone || selectedHistoryItems.length === 0}
                className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-1.5 text-sm font-medium text-white bg-green-600 rounded-md hover:bg-green-700 disabled:opacity-50 transition-colors shadow-sm"
              >
                Mark Done
              </button>
            )}
          </div>
        </div>
      </div>

      {successMessage && (
        <div className="bg-green-50 border border-green-200 text-green-700 px-4 py-2 rounded-md flex items-center justify-between text-sm flex-shrink-0 animate-fade-in">
          <span className="flex items-center gap-2"><CheckCircle2 className="w-4 h-4" /> {successMessage}</span>
          <button onClick={() => setSuccessMessage("")}><X className="w-4 h-4" /></button>
        </div>
      )}

      {/* Table Area - Standard Grid View */}
      <div className="flex-grow bg-white border border-gray-200 rounded-lg shadow-sm overflow-hidden flex flex-col">
        <div ref={tableRef} className="overflow-auto flex-grow" onScroll={handleScroll}>
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50 sticky top-0 z-20 transition-all">
              <tr>
                <th className="px-3 py-3 text-left w-10 bg-gray-50">
                  {!showHistory && (
                    <input
                      type="checkbox"
                      onChange={handleSelectAll}
                      checked={filteredData.length > 0 && selectedItems.size === filteredData.length}
                      className="rounded border-gray-300 text-purple-600 focus:ring-purple-500"
                    />
                  )}
                </th>
                <th className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Task ID</th>
                <th className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Department Name</th>
                <th className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Given By</th>
                <th className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Name</th>
                <th className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider min-w-[250px]">Task Description</th>
                <th className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap bg-yellow-50">Task Start Date & Time</th>
                <th className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Freq</th>
                <th className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Enable Reminders</th>
                <th className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Require Attachment</th>
                <th className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider min-w-[140px]">Status</th>
                <th className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider min-w-[150px]">Remarks</th>
                <th className="px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Upload Image</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-100">
              {filteredData.map((item, idx) => {
                const isSelected = selectedItems.has(item.id);
                const isHistorySelected = selectedHistoryItems.includes(item.id);

                return (
                  <tr
                    key={item.id || idx}
                    className={`hover:bg-gray-50 transition-colors ${isSelected || isHistorySelected ? 'bg-purple-50' : ''}`}
                  >
                    <td className="px-3 py-4 align-top w-10">
                      {!showHistory ? (
                        <input
                          type="checkbox"
                          checked={isSelected}
                          onChange={(e) => handleCheckboxClick(e, item.id)}
                          className="rounded border-gray-300 text-purple-600 focus:ring-purple-500"
                        />
                      ) : (
                        userRole === 'admin' && (
                          <input
                            type="checkbox"
                            checked={isHistorySelected}
                            onChange={(e) => {
                              if (e.target.checked) setSelectedHistoryItems(p => [...p, item.id])
                              else setSelectedHistoryItems(p => p.filter(id => id !== item.id))
                            }}
                            className="rounded border-gray-300 text-purple-600 focus:ring-purple-500"
                          />
                        )
                      )}
                    </td>
                    <td className="px-3 py-4 text-sm font-medium text-gray-900 whitespace-nowrap align-top">
                      #{item.id}
                    </td>
                    <td className="px-3 py-4 text-sm text-gray-600 whitespace-nowrap align-top">
                      {item.department || "-"}
                    </td>
                    <td className="px-3 py-4 text-sm text-gray-600 whitespace-nowrap align-top">
                      {item.given_by || "-"}
                    </td>
                    <td className="px-3 py-4 text-sm text-gray-600 whitespace-nowrap align-top">
                      {item.name || "-"}
                    </td>
                    <td className="px-3 py-4 text-sm text-gray-800 align-top min-w-[250px]">
                      <div className="whitespace-normal break-words leading-relaxed">
                        {item.task_description}
                      </div>
                    </td>
                    <td className="px-3 py-4 text-sm text-gray-600 whitespace-nowrap align-top bg-yellow-50">
                      {item.task_start_date ? new Date(item.task_start_date).toLocaleString('en-IN', {
                        day: '2-digit', month: '2-digit', year: 'numeric',
                        hour: '2-digit', minute: '2-digit', hour12: true
                      }) : '-'}
                    </td>
                    <td className="px-3 py-4 text-sm text-gray-600 whitespace-nowrap align-top">
                      <span className={`px-2 py-0.5 rounded-full text-xs uppercase font-bold border ${item.frequency === 'daily' ? 'bg-blue-50 text-blue-700 border-blue-100' :
                        item.frequency === 'weekly' ? 'bg-green-50 text-green-700 border-green-100' :
                          'bg-gray-50 text-gray-600 border-gray-100'
                        }`}>
                        {item.frequency}
                      </span>
                    </td>
                    <td className="px-3 py-4 text-sm text-gray-600 whitespace-nowrap align-top text-center">
                      {item.enable_reminder ? "Yes" : "No"}
                    </td>
                    <td className="px-3 py-4 text-sm text-gray-600 whitespace-nowrap align-top text-center">
                      {item.require_attachment ? "Yes" : "No"}
                    </td>

                    {/* Status Column */}
                    <td className="px-3 py-4 align-top">
                      {showHistory ? (
                        <span className={`inline-flex px-2 py-0.5 text-xs font-bold uppercase rounded-full border 
                          ${item.status === 'yes' ? 'bg-green-50 text-green-700 border-green-200' : 'bg-red-50 text-red-700 border-red-200'}`}>
                          {item.status === 'yes' ? 'Done' : 'Not Done'}
                        </span>
                      ) : (
                        <select
                          className={`w-full text-sm border rounded p-1.5 outline-none focus:border-gray-400 cursor-pointer
                            ${additionalData[item.id] === 'yes' ? 'bg-green-50 border-green-300 text-green-700' :
                              additionalData[item.id] === 'no' ? 'bg-red-50 border-red-300 text-red-700' : 'border-gray-300 text-gray-600'}`}
                          value={additionalData[item.id] || (item.status === 'yes' || item.status === 'Done' ? 'yes' : item.status === 'no' || item.status === 'Not Done' ? 'no' : '')}
                          onChange={e => setAdditionalData(p => ({ ...p, [item.id]: e.target.value }))}
                          disabled={!isSelected}
                        >
                          <option value="">Select...</option>
                          <option value="yes">Done</option>
                          <option value="no">Not Done</option>
                        </select>
                      )}
                    </td>

                    {/* Remarks Column */}
                    <td className="px-3 py-4 align-top">
                      {showHistory ? (
                        <span className="text-sm text-gray-500 italic block min-w-[150px]">{item.remark || item.remarks || "-"}</span>
                      ) : (
                        <textarea
                          rows={1}
                          className="w-full text-sm border border-gray-300 rounded p-1.5 focus:border-purple-500 outline-none resize-none overflow-hidden focus:ring-1 focus:ring-purple-200 transition-shadow"
                          placeholder="Add remarks..."
                          value={remarksData[item.id] || ""}
                          onChange={e => setRemarksData(p => ({ ...p, [item.id]: e.target.value }))}
                          disabled={!isSelected}
                        />
                      )}
                    </td>

                    {/* Upload Image Column */}
                    <td className="px-3 py-4 align-top">
                      {showHistory ? (
                        item.image ? (
                          <a href={item.image} target="_blank" className="text-purple-600 hover:text-purple-800 hover:underline text-sm flex items-center gap-1 font-medium">
                            <CheckCircle2 className="w-3 h-3" /> View
                          </a>
                        ) : <span className="text-gray-300 text-sm">-</span>
                      ) : (
                        <div className="flex items-center gap-2">
                          <label className={`
                              cursor-pointer flex items-center justify-center p-1.5 rounded-md border transition-all duration-200
                              ${uploadedImages[item.id] ? 'bg-green-50 border-green-300 text-green-700 shadow-sm' : 'border-gray-300 text-gray-500 hover:bg-gray-50 hover:border-purple-300 hover:text-purple-600'}
                           `}>
                            <Upload className="w-4 h-4" />
                            <input type="file" className="hidden" onChange={e => handleImageUpload(item.id, e)} disabled={!isSelected} />
                          </label>
                          {uploadedImages[item.id] && (
                            <span className="text-xs text-green-600 font-medium truncate max-w-[80px]">Attached</span>
                          )}
                        </div>
                      )}
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
          {(isFetchingMore || isLoadingMoreHistory) && (
            <div className="py-4 text-center"><Loader2 className="w-5 h-5 animate-spin mx-auto text-gray-400" /></div>
          )}
        </div>
      </div>
    </div>
  );

  return showLayout ? <AdminLayout>{content}</AdminLayout> : content;
}

import React, { useState, useEffect } from 'react';
import AdminLayout from '../../components/layout/AdminLayout';
import { ChevronLeft, ChevronRight, Calendar as CalendarIcon, List, CheckCircle2, ShieldAlert, Loader2, Plus, Trash2 } from 'lucide-react';
import supabase from '../../SupabaseClient';

const WorkingDayCalendarPage = () => {
    const [currentDate, setCurrentDate] = useState(new Date());
    const [holidays, setHolidays] = useState([]);
    const [workingDays, setWorkingDays] = useState([]);
    const [loading, setLoading] = useState(true);
    const [isProcessing, setIsProcessing] = useState(false);

    const [tasks, setTasks] = useState([]);

    useEffect(() => {
        fetchData();
    }, [currentDate]);

    const fetchData = async () => {
        try {
            setLoading(true);
            const startOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1).toISOString().split('T')[0];
            const endOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0, 23, 59, 59);
            const endStr = `${endOfMonth.getFullYear()}-${String(endOfMonth.getMonth() + 1).padStart(2, '0')}-${String(endOfMonth.getDate()).padStart(2, '0')}T23:59:59`;

            const [holidaysRes, workingDaysRes, checklistRes, maintenanceRes, delegationRes, eaRes] = await Promise.all([
                supabase.from('holidays').select('*'),
                supabase.from('working_day_calender')
                    .select('*')
                    .gte('working_date', startOfMonth)
                    .lte('working_date', endStr)
                    .order('working_date', { ascending: true }),
                supabase.from('checklist').select('planned_date, task_start_date').gte('planned_date', startOfMonth).lte('planned_date', endStr),
                supabase.from('maintenance_tasks').select('planned_date').gte('planned_date', startOfMonth).lte('planned_date', endStr),
                supabase.from('delegation').select('planned_date').gte('planned_date', startOfMonth).lte('planned_date', endStr),
                supabase.from('ea_tasks').select('planned_date').gte('planned_date', startOfMonth).lte('planned_date', endStr)
            ]);

            if (holidaysRes.error && holidaysRes.error.code !== '42P01') throw holidaysRes.error;
            if (workingDaysRes.error && workingDaysRes.error.code !== '42P01') throw workingDaysRes.error;

            setHolidays(holidaysRes.data || []);
            setWorkingDays(workingDaysRes.data || []);

            // Combine task dates for counting
            const allTaskDates = [
                ...(checklistRes.data || []).map(t => (t.planned_date || t.task_start_date || "").split('T')[0]),
                ...(maintenanceRes.data || []).map(t => (t.planned_date || "").split('T')[0]),
                ...(delegationRes.data || []).map(t => (t.planned_date || "").split('T')[0]),
                ...(eaRes.data || []).map(t => (t.planned_date || "").split('T')[0])
            ].filter(Boolean);

            setTasks(allTaskDates);
        } catch (err) {
            console.error('Error fetching calendar data:', err);
        } finally {
            setLoading(false);
        }
    };

    const toggleWorkingDay = async (dateStr, isWorking, isHoliday) => {
        if (isHoliday || isProcessing) return;

        try {
            setIsProcessing(true);
            if (isWorking) {
                // Remove from working days (Make it an Off Day)
                const { error } = await supabase
                    .from('working_day_calender')
                    .delete()
                    .eq('working_date', dateStr);
                if (error) throw error;

                // Also remove tasks for this specific day (Off Day)
                const startOfDay = `${dateStr}T00:00:00.000Z`;
                const endOfDay = `${dateStr}T23:59:59.999Z`;

                await Promise.all([
                    supabase.from('checklist').delete().gte('task_start_date', startOfDay).lte('task_start_date', endOfDay),
                    supabase.from('delegation').delete().gte('task_start_date', startOfDay).lte('task_start_date', endOfDay),
                    supabase.from('maintenance_tasks').delete().gte('task_start_date', startOfDay).lte('task_start_date', endOfDay),
                    supabase.from('ea_tasks').delete().gte('planned_date', startOfDay).lte('planned_date', endOfDay)
                ]);
                console.log(`Cleaned up tasks for Off Day: ${dateStr}`);
            } else {
                // Add to working days
                const dateObj = new Date(dateStr);
                const dow = dateObj.getDay();

                // Only proceed if not Sunday (to match database rules)
                if (dow !== 0) {
                    const hindiDays = {
                        1: 'सोम',
                        2: 'मंगल',
                        3: 'बुध',
                        4: 'गुरु',
                        5: 'शुक्र',
                        6: 'शनि'
                    };

                    const dayName = hindiDays[dow];
                    const monthNum = dateObj.getMonth() + 1;

                    // ISO Week Number calculation
                    const getISOWeek = (date) => {
                        const d = new Date(date);
                        d.setHours(0, 0, 0, 0);
                        d.setDate(d.getDate() + 4 - (d.getDay() || 7));
                        const yearStart = new Date(d.getFullYear(), 0, 1);
                        return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
                    };

                    const weekNum = getISOWeek(dateObj);

                    const { error } = await supabase
                        .from('working_day_calender')
                        .insert([{
                            working_date: dateStr,
                            day: dayName,
                            week_num: weekNum,
                            month: monthNum
                        }]);
                    if (error) throw error;
                }
            }
            await fetchData();
        } catch (err) {
            console.error('Toggle error:', err);
            alert('Failed to update working day');
        } finally {
            setIsProcessing(false);
        }
    };

    const prevMonth = () => {
        setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
    };

    const nextMonth = () => {
        setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
    };

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const monthName = currentDate.toLocaleString('default', { month: 'long' });

    // Function to convert English day names to Hindi
    const getDayInHindi = (englishDay) => {
        const dayMap = {
            'Sunday': 'रविवार',
            'Monday': 'सोमवार',
            'Tuesday': 'मंगलवार',
            'Wednesday': 'बुधवार',
            'Thursday': 'गुरुवार',
            'Friday': 'शुक्रवार',
            'Saturday': 'शनिवार'
        };
        const hindiDay = dayMap[englishDay] || englishDay;
        return `${hindiDay} (${englishDay})`;
    };

    // Get all days in the month
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const allDaysInMonth = [];

    for (let i = 1; i <= daysInMonth; i++) {
        const dateString = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
        const dateObj = new Date(dateString);

        // Use robust matching to handle ISO strings or timestamps from Supabase
        const holiday = holidays.find(h => (h.holiday_date || "").split('T')[0] === dateString);
        const workingDay = workingDays.find(w => (w.working_date || "").split('T')[0] === dateString);

        const englishDayName = dateObj.toLocaleDateString('en-GB', { weekday: 'long' });

        const taskCount = tasks.filter(tDate => tDate === dateString).length;

        allDaysInMonth.push({
            date: dateString,
            day: i,
            dayName: getDayInHindi(englishDayName),
            isHoliday: !!holiday,
            isWorking: !!workingDay,
            holidayName: holiday?.holiday_name,
            weekNum: workingDay?.week_num,
            taskCount
        });
    }

    return (
        <AdminLayout>
            <div className="max-w-7xl mx-auto space-y-4 px-4 pb-10">
                {/* Header Section - Professional & Clean */}
                <div className="flex flex-col md:flex-row justify-between items-center gap-4 py-6 border-b border-gray-200">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-blue-600 rounded text-white font-semibold shadow-sm">
                            <List size={22} />
                        </div>
                        <div>
                            <h1 className="text-2xl font-bold text-gray-900 leading-tight">Working Days Management</h1>
                            <p className="text-sm text-gray-500 font-medium">
                                Configure operational availability and scheduled work days.
                            </p>
                        </div>
                    </div>

                    <div className="flex flex-col sm:flex-row items-center gap-4 w-full md:w-auto">
                        <div className="flex items-center bg-white border border-gray-300 rounded shadow-sm overflow-hidden text-sm w-full sm:w-auto">
                            <button onClick={prevMonth} className="p-2.5 hover:bg-gray-50 transition-colors border-r border-gray-300 text-gray-600">
                                <ChevronLeft size={18} strokeWidth={2.5} />
                            </button>
                            <div className="px-6 py-2.5 font-bold text-gray-800 min-w-[160px] text-center tracking-wide">
                                {monthName} {year}
                            </div>
                            <button onClick={nextMonth} className="p-2.5 hover:bg-gray-50 transition-colors border-l border-gray-300 text-gray-600">
                                <ChevronRight size={18} strokeWidth={2.5} />
                            </button>
                        </div>

                        <div className="flex gap-3 bg-gray-50 p-2 rounded-lg border border-gray-200 w-full sm:w-auto justify-center">
                            <LegendItem label="Working" color="bg-emerald-500" />
                            <LegendItem label="Holiday" color="bg-red-500" />
                            <LegendItem label="Off Day" color="bg-gray-300" />
                        </div>
                    </div>
                </div>

                {/* Days Table List - Classic & Readable */}
                <div className="bg-white border border-gray-200 rounded-xl shadow-sm overflow-hidden">
                    <div className="px-5 py-4 bg-gray-50 border-b border-gray-200 flex justify-between items-center">
                        <h2 className="text-base font-semibold text-gray-800">
                            Schedule for {monthName} {year}
                        </h2>
                        <span className="text-xs font-bold px-2.5 py-1 bg-blue-50 text-blue-700 rounded-full border border-blue-100 uppercase">
                            {workingDays.length} Working Days
                        </span>
                    </div>

                    <div className="overflow-x-auto overflow-y-auto max-h-[70vh]">
                        <table className="w-full text-left text-sm border-collapse min-w-[600px]">
                            <thead>
                                <tr className="bg-white border-b border-gray-200 sticky top-0 z-10">
                                    <th className="px-6 py-3 font-semibold text-gray-600 text-[10px] uppercase tracking-wider">Date</th>
                                    <th className="px-6 py-3 font-semibold text-gray-600 text-[10px] uppercase tracking-wider">Day of Week</th>
                                    <th className="px-6 py-3 font-semibold text-gray-600 text-[10px] uppercase tracking-wider">Week No.</th>
                                    <th className="px-6 py-3 font-semibold text-gray-600 text-[10px] uppercase tracking-wider text-center">Tasks</th>
                                    <th className="px-6 py-3 font-semibold text-gray-600 text-[10px] uppercase tracking-wider">Operational Status</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-200">
                                {loading ? (
                                    <tr>
                                        <td colSpan="5" className="px-6 py-12 text-center text-gray-400">
                                            <div className="flex flex-col items-center gap-2">
                                                <Loader2 className="animate-spin text-blue-500" size={24} />
                                                <span className="text-xs font-medium uppercase tracking-widest">Fetching Data...</span>
                                            </div>
                                        </td>
                                    </tr>
                                ) : allDaysInMonth.length === 0 ? (
                                    <tr>
                                        <td colSpan="5" className="px-6 py-12 text-center text-gray-400">
                                            <span className="text-xs font-bold uppercase tracking-widest">No records available for this period</span>
                                        </td>
                                    </tr>
                                ) : (
                                    allDaysInMonth.map((dayInfo) => (
                                        <tr
                                            key={dayInfo.date}
                                            className={`transition-colors ${dayInfo.isHoliday ? 'bg-red-50/20' :
                                                dayInfo.isWorking ? 'bg-white hover:bg-gray-50' :
                                                    'bg-gray-50 text-gray-400'
                                                }`}
                                        >
                                            <td className="px-6 py-4">
                                                <div className={`font-semibold ${dayInfo.isWorking ? 'text-gray-900' : 'text-gray-500'}`}>
                                                    {new Date(dayInfo.date).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })}
                                                </div>
                                            </td>
                                            <td className="px-6 py-4 font-medium">
                                                {dayInfo.dayName}
                                            </td>
                                            <td className="px-6 py-4 text-xs font-medium">
                                                {dayInfo.weekNum || '—'}
                                            </td>
                                            <td className="px-6 py-4 text-center">
                                                {dayInfo.taskCount > 0 ? (
                                                    <span className="inline-flex items-center justify-center w-6 h-6 rounded bg-blue-600 text-white font-bold text-[10px] shadow-sm">
                                                        {dayInfo.taskCount}
                                                    </span>
                                                ) : (
                                                    <span className="text-gray-300 text-[10px]">0</span>
                                                )}
                                            </td>
                                            <td className="px-6 py-4">
                                                {dayInfo.isHoliday ? (
                                                    <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-red-100 text-red-700 text-[10px] font-bold rounded-full border border-red-200">
                                                        <ShieldAlert size={12} />
                                                        {dayInfo.holidayName}
                                                    </span>
                                                ) : dayInfo.isWorking ? (
                                                    <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-emerald-100 text-emerald-700 text-[10px] font-bold rounded-full border border-emerald-200">
                                                        <CheckCircle2 size={12} />
                                                        WORKING
                                                    </span>
                                                ) : (
                                                    <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-gray-200 text-gray-600 text-[10px] font-bold rounded-full border border-gray-300">
                                                        OFF DAY
                                                    </span>
                                                )}
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Info Card - Professional Tip */}
                <div className="bg-blue-50 border border-blue-100 p-4 rounded-xl flex items-start gap-3">
                    <div className="p-1.5 bg-blue-100 rounded text-blue-600">
                        <ShieldAlert size={18} />
                    </div>
                    <div>
                        <h3 className="text-xs font-bold text-blue-900 uppercase tracking-wide">Operational Guidelines</h3>
                        <p className="text-xs text-blue-700 mt-1 leading-relaxed">
                            Working days represent scheduled availability. Off days will automatically restrict new task assignments for that date.
                            Holidays override manual working day configurations.
                        </p>
                    </div>
                </div>
            </div>
        </AdminLayout>
    );
};

