        const isColumnMEmpty = isEmpty(columnMValue);

        // For pending tasks: Column L is not null and column M is null
        if (hasColumnL && isColumnMEmpty) {
          // Filter for today and tomorrow OR past dates
          if (formattedRowDate === todayStr ||
