    useEffect(() => {
        const fetchTotalUsers = async () => {
            try {
                // Pass departmentFilter to the API
                const count = await getTotalUsersCountApi(departmentFilter)
                setTotalUsersCount(count)
            } catch (error) {
                console.error('Error fetching total users count:', error)
            }
        }

        fetchTotalUsers()
