                      {/* Skip column N (index 13) and show O and P */}
                      {sheetHeaders.slice(14, 16).map((header) => (
                        <th
                          key={header.id}
                          className={`px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider
                            ${header.id === 'col14' ? 'bg-blue-50' : ''}
