                        <tr key={history._id} className="hover:bg-gray-50">
                          {/* Add checkbox in first column */}
                          <td className="px-6 py-4 whitespace-nowrap">
                            <input
                              type="checkbox"
                              className="h-4 w-4 rounded border-gray-300 text-green-600 focus:ring-green-500"
