      })
         .addCase(updateChecklist.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(updateChecklist.fulfilled, (state, action) => {
        state.loading = false;
        state.checklist=action.payload;
      })
      .addCase(updateChecklist.rejected, (state, action) => {
