import React from 'react';
import { Image as ImageIcon, Video, FileText } from 'lucide-react';

const SAMPLE_CONTACT = {
  name: 'John Doe',
  phone_number: '919876543210',
  email: 'john@example.com',
  extra_fields: { business_name: 'Acme Traders' },
};

// WhatsApp templates apply their own *bold*/_italic_/~strike~ markup around
// {{n}} placeholders in the template body itself. If a variable's value also
// contains one of those characters (e.g. someone typed "*Holi" into the
// occasion field), it collides with the template's own marker and renders as
// a stray/mismatched asterisk (e.g. "**Holi*"). Strip them from substituted
// values so only the template's own formatting ever shows.
const stripMarkupChars = (value) => String(value ?? '').replace(/[*_~`]/g, '').trim();

const resolveField = (contact, path, occasion) => {
  if (!path) return null;
  if (path === 'occasion') return occasion || null;
  if (path === 'name') return contact.name;
  if (path === 'phone_number') return contact.phone_number;
  if (path === 'email') return contact.email;
  if (path.startsWith('extra_fields.')) return contact.extra_fields?.[path.slice('extra_fields.'.length)];
  return contact.extra_fields?.[path];
};

// Adapted from WhatsappHistory.jsx's renderTemplate — same {{n}} substitution + bubble layout,
// extended with a header-media block for IMAGE/VIDEO/DOCUMENT headers.
export default function TemplatePreview({ template, variableMapping = {}, previewContact, occasion }) {
  if (!template) {
    return (
      <div className="flex items-center justify-center h-full text-sm text-gray-400 p-8 text-center">
        Pick a template to see a live preview here.
      </div>
    );
  }

  const contact = previewContact || SAMPLE_CONTACT;

  const bodyIndices = Object.keys(variableMapping)
    .filter((k) => /^\d+$/.test(k))
    .map((k) => parseInt(k, 10))
    .sort((a, b) => a - b);

  let formattedBody = template.body_text || '';
  bodyIndices.forEach((idx) => {
    const entry = variableMapping[String(idx)];
    const rawValue = entry?.type === 'field' ? resolveField(contact, entry.value, occasion) : entry?.value;
    const value = stripMarkupChars(rawValue);
    formattedBody = formattedBody.replaceAll(`{{${idx}}}`, value || 'N/A');
  });

  const headerFormat = template.header_format || 'NONE';
  const headerMediaUrl = variableMapping.header_media;
  const MediaIcon = headerFormat === 'IMAGE' ? ImageIcon : headerFormat === 'VIDEO' ? Video : FileText;

  return (
    <div className="bg-[#e5ded8] rounded-xl p-4 h-full flex items-start">
      <div className="bg-white rounded-lg rounded-tl-none shadow-sm p-3 max-w-full w-full space-y-1.5 text-left">
        {['IMAGE', 'VIDEO', 'DOCUMENT'].includes(headerFormat) && (
          <div className="rounded-md bg-gray-100 border border-gray-200 h-28 flex items-center justify-center overflow-hidden mb-1">
            {headerMediaUrl && headerFormat === 'IMAGE' ? (
              <img src={headerMediaUrl} alt="header" className="h-full w-full object-cover" />
            ) : (
              <div className="flex flex-col items-center text-gray-400 text-xs gap-1">
                <MediaIcon className="w-6 h-6" />
                {headerFormat.charAt(0) + headerFormat.slice(1).toLowerCase()} header
              </div>
            )}
          </div>
        )}

        {headerFormat === 'TEXT' && template.header_text && (
          <div className="font-bold text-[#111b21] text-[13px] border-b border-black/5 pb-1 mb-1">
            {template.header_text}
          </div>
        )}

        <div className="text-[13px] text-[#303030] leading-relaxed whitespace-pre-wrap">{formattedBody}</div>

        {template.footer_text && (
          <div className="text-[10px] text-[#667781] mt-1">{template.footer_text}</div>
        )}

        {Array.isArray(template.buttons) && template.buttons.length > 0 && (
          <div className="mt-2.5 pt-2 border-t border-black/5 flex flex-wrap gap-1.5">
            {template.buttons.map((btn, idx) => (
              <span key={idx} className="bg-black/5 text-[#008069] text-[10px] font-semibold px-2 py-0.5 rounded border border-black/5">
                {btn.text || btn.type}
              </span>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useEffect } from 'react';

const FIELD_OPTIONS = [
  { value: 'name', label: 'Client Name' },
  { value: 'phone_number', label: 'Phone Number' },
  { value: 'email', label: 'Email' },
  { value: 'occasion', label: 'Occasion (this schedule)' },
  { value: 'extra_fields.business_name', label: 'Business Name (CSV field)' },
];

const BLANK_ENTRY = { type: 'custom', value: '' };

// WhatsApp templates already wrap {{n}} in their own *bold*/_italic_/~strike~
// markers. A custom value that also contains one of those characters (e.g.
// typing "*Holi") collides with the template's own marker at send time and
// shows up as a stray/mismatched asterisk (e.g. "**Holi*") — so these
// characters aren't allowed in custom variable text at all.
const stripMarkupChars = (value) => value.replace(/[*_~`]/g, '');

// Renders one row per {{n}} body variable (+ 1 header row iff the template's
// header format is TEXT and its header text itself contains a variable).
export default function VariableMapper({ template, variableMapping, onChange }) {
  const bodyCount = template?.body_variable_count || 0;
  const hasHeaderVariable = template?.header_variable_present;

  // Every {{n}} must be explicitly mapped by the admin — no automatic default
  // (e.g. always "Client Name"), otherwise multiple variables silently end up
  // with the same value (this previously made {{2}}, meant for the occasion,
  // resolve to the client's name because both were auto-defaulted the same
  // way). Missing entries are seeded blank so Meta always gets the right
  // *count* of parameters (avoiding error 132000), while the *value* of each
  // one is always a deliberate choice.
  useEffect(() => {
    if (!template) return;
    const requiredKeys = [
      ...(hasHeaderVariable ? ['header'] : []),
      ...Array.from({ length: bodyCount }, (_, i) => String(i + 1)),
    ];
    const missing = requiredKeys.filter((k) => !variableMapping[k]);
    if (missing.length === 0) return;
    const patch = {};
    missing.forEach((k) => { patch[k] = { ...BLANK_ENTRY }; });
    onChange({ ...variableMapping, ...patch });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [template?.name, bodyCount, hasHeaderVariable]);

  if (!template) return null;

  const setEntry = (key, entry) => {
    onChange({ ...variableMapping, [key]: entry });
  };

  const renderRow = (key, label, exampleValue) => {
    const entry = variableMapping[key] || BLANK_ENTRY;
    const isUnset = !entry.value;
    return (
      <div key={key} className={`flex items-center gap-3 py-2 px-2 -mx-2 rounded-lg ${isUnset ? 'bg-amber-50/60' : ''}`}>
        <span className="text-xs font-mono font-semibold text-gray-500 w-16 shrink-0">{label}</span>
        <select
          className="text-sm border border-gray-200 rounded-lg px-2 py-1.5 bg-white"
          value={entry.type}
          onChange={(e) => setEntry(key, { type: e.target.value, value: '' })}
        >
          <option value="field">Client field</option>
          <option value="custom">Custom value</option>
        </select>
        {entry.type === 'field' ? (
          <select
            className={`flex-1 text-sm border rounded-lg px-2 py-1.5 bg-white ${isUnset ? 'border-amber-300' : 'border-gray-200'}`}
            value={entry.value}
            onChange={(e) => setEntry(key, { type: 'field', value: e.target.value })}
          >
            <option value="" disabled>Choose a field…</option>
            {FIELD_OPTIONS.map((opt) => (
              <option key={opt.value} value={opt.value}>{opt.label}</option>
            ))}
          </select>
        ) : (
          <input
            type="text"
            className={`flex-1 text-sm border rounded-lg px-2 py-1.5 ${isUnset ? 'border-amber-300' : 'border-gray-200'}`}
            placeholder={exampleValue ? `e.g. ${exampleValue}` : 'Enter a value'}
            value={entry.value}
            onChange={(e) => setEntry(key, { type: 'custom', value: stripMarkupChars(e.target.value) })}
          />
        )}
        {isUnset && <span className="text-[10px] font-semibold text-amber-600 shrink-0">Required</span>}
      </div>
    );
  };

  const exampleParams = template.example_body_params || [];

  return (
    <div className="divide-y divide-gray-100">
      {hasHeaderVariable && renderRow('header', 'Header', null)}
      {Array.from({ length: bodyCount }, (_, i) => i + 1).map((n) =>
        renderRow(String(n), `{{${n}}}`, exampleParams[n - 1])
      )}
      {bodyCount === 0 && !hasHeaderVariable && (
        <p className="text-xs text-gray-400 py-2">This template has no variables to map.</p>
      )}
    </div>
  );
}

import React, { useEffect, useState, useCallback } from 'react';
import {
  Users, Plus, Pencil, Trash2, Save, X, Settings2, Phone,
  Calendar, RefreshCw, CheckCircle2, AlertCircle, ChevronUp, ChevronDown,
} from 'lucide-react';
import {
  fetchEmployeeBirthdays,
  addEmployeeBirthday,
  updateEmployeeBirthday,
  deleteEmployeeBirthday,
  getGreetingsConfig,
  upsertGreetingsConfig,
  sendBirthdayGreeting,
} from '../services/greetingsService';

const EMPTY_FORM = {
  employee_name: '',
  phone_number: '',
  date_of_birth: '',
  is_active: true,
  notes: '',
};

const monthDay = (dob) => {
  if (!dob) return '—';
  const d = new Date(dob);
  return d.toLocaleDateString('en-IN', { month: 'short', day: 'numeric', timeZone: 'UTC' });
};

export default function BirthdaySetup() {
  const [employees, setEmployees] = useState([]);
  const [config, setConfig] = useState({ birthday_template_name: 'birthday_wishes', birthday_template_language: 'en' });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState(null);

  const [form, setForm] = useState(EMPTY_FORM);
  const [editId, setEditId] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [formError, setFormError] = useState('');

  const [configOpen, setConfigOpen] = useState(false);
  const [testPhone, setTestPhone] = useState('');
  const [testName, setTestName] = useState('');
  const [testSending, setTestSending] = useState(false);

  const [sortField, setSortField] = useState('employee_name');
  const [sortDir, setSortDir] = useState('asc');
  const [search, setSearch] = useState('');
  const [deleteConfirm, setDeleteConfirm] = useState(null);

  const showToast = (msg, type = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3500);
  };

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [emps, cfg] = await Promise.all([fetchEmployeeBirthdays(), getGreetingsConfig()]);
      setEmployees(emps);
      setConfig((prev) => ({ ...prev, ...cfg }));
    } catch (err) {
      showToast(err.message || 'Failed to load data', 'error');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const openAdd = () => {
    setForm(EMPTY_FORM);
    setEditId(null);
    setFormError('');
    setShowForm(true);
  };

  const openEdit = (emp) => {
    setForm({
      employee_name: emp.employee_name,
      phone_number: emp.phone_number,
      date_of_birth: emp.date_of_birth,
      is_active: emp.is_active,
      notes: emp.notes || '',
    });
    setEditId(emp.id);
    setFormError('');
    setShowForm(true);
  };

  const closeForm = () => { setShowForm(false); setEditId(null); setFormError(''); };

  const handleSave = async () => {
    if (!form.employee_name.trim()) return setFormError('Employee name is required.');
    if (!form.phone_number.trim()) return setFormError('Phone number is required.');
    if (!form.date_of_birth) return setFormError('Date of birth is required.');
    setSaving(true);
    try {
      if (editId) {
        const updated = await updateEmployeeBirthday(editId, form);
        setEmployees((prev) => prev.map((e) => (e.id === editId ? updated : e)));
        showToast('Employee updated successfully.');
      } else {
        const added = await addEmployeeBirthday(form);
        setEmployees((prev) => [...prev, added]);
        showToast('Employee added successfully.');
      }
      closeForm();
    } catch (err) {
      setFormError(err.message || 'Save failed.');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id) => {
    try {
      await deleteEmployeeBirthday(id);
      setEmployees((prev) => prev.filter((e) => e.id !== id));
      showToast('Employee removed.');
    } catch (err) {
      showToast(err.message || 'Delete failed.', 'error');
    } finally {
      setDeleteConfirm(null);
    }
  };

  const handleSaveConfig = async () => {
    setSaving(true);
    try {
      await Promise.all([
        upsertGreetingsConfig('birthday_template_name', config.birthday_template_name),
        upsertGreetingsConfig('birthday_template_language', config.birthday_template_language),
      ]);
      showToast('Configuration saved.');
    } catch (err) {
      showToast(err.message || 'Config save failed.', 'error');
    } finally {
      setSaving(false);
    }
  };

  const handleTestSend = async () => {
    if (!testPhone.trim() || !testName.trim()) {
      showToast('Enter a name and phone number to test.', 'error');
      return;
    }
    setTestSending(true);
    try {
      const fakeEmp = {
        id: 'test',
        employee_name: testName,
        phone_number: testPhone,
        date_of_birth: new Date().toISOString().split('T')[0],
        is_active: true,
      };
      const result = await sendBirthdayGreeting(fakeEmp, config);
      if (result.success || result.skipped) showToast('Test message sent!');
      else showToast(result.error || 'Send failed.', 'error');
    } catch (err) {
      showToast(err.message || 'Test failed.', 'error');
    } finally {
      setTestSending(false);
    }
  };

  const toggleSort = (field) => {
    if (sortField === field) setSortDir((d) => (d === 'asc' ? 'desc' : 'asc'));
    else { setSortField(field); setSortDir('asc'); }
  };

  const SortIcon = ({ field }) => {
    if (sortField !== field) return <ChevronUp className="w-3 h-3 opacity-30" />;
    return sortDir === 'asc'
      ? <ChevronUp className="w-3 h-3 text-blue-500" />
      : <ChevronDown className="w-3 h-3 text-blue-500" />;
  };

  const filtered = employees
    .filter((e) =>
      e.employee_name.toLowerCase().includes(search.toLowerCase()) ||
      e.phone_number.includes(search)
    )
    .sort((a, b) => {
      const va = String(a[sortField] || '').toLowerCase();
      const vb = String(b[sortField] || '').toLowerCase();
      return sortDir === 'asc' ? va.localeCompare(vb) : vb.localeCompare(va);
    });

  const today = new Date();
  const upcomingIds = new Set(
    employees
      .filter((e) => {
        const dob = new Date(e.date_of_birth);
        const bday = new Date(today.getFullYear(), dob.getUTCMonth(), dob.getUTCDate());
        if (bday < today) bday.setFullYear(today.getFullYear() + 1);
        const diff = (bday - today) / 86400000;
        return diff >= 0 && diff <= 7;
      })
      .map((e) => e.id)
  );

  return (
    <div className="space-y-6">
      {/* Toast */}
      {toast && (
        <div className={`fixed top-5 right-5 z-50 flex items-center gap-2 px-4 py-3 rounded-lg shadow-lg text-sm font-medium transition-all
          ${toast.type === 'error' ? 'bg-red-50 text-red-700 border border-red-200' : 'bg-green-50 text-green-700 border border-green-200'}`}>
          {toast.type === 'error' ? <AlertCircle className="w-4 h-4" /> : <CheckCircle2 className="w-4 h-4" />}
          {toast.msg}
        </div>
      )}

      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Birthday Setup</h1>
          <p className="text-sm text-gray-500 mt-0.5">Manage employee birthdays and WhatsApp template configuration.</p>
        </div>
        <div className="flex gap-2">
          <button onClick={load} className="flex items-center gap-1.5 px-3 py-2 text-sm rounded-lg border border-gray-200 text-gray-600 hover:bg-gray-50">
            <RefreshCw className="w-4 h-4" /> Refresh
          </button>
          <button onClick={openAdd} className="flex items-center gap-1.5 px-4 py-2 text-sm rounded-lg bg-blue-600 text-white hover:bg-blue-700 font-medium">
            <Plus className="w-4 h-4" /> Add Employee
          </button>
        </div>
      </div>

      {/* Template Config Card */}
      <div className="bg-white rounded-xl border border-gray-200 shadow-sm">
        <button
          onClick={() => setConfigOpen((v) => !v)}
          className="w-full flex items-center justify-between px-5 py-4 text-left"
        >
          <div className="flex items-center gap-2 font-semibold text-gray-800">
            <Settings2 className="w-5 h-5 text-purple-500" />
            WhatsApp Template Configuration
          </div>
          {configOpen ? <ChevronUp className="w-4 h-4 text-gray-400" /> : <ChevronDown className="w-4 h-4 text-gray-400" />}
        </button>

        {configOpen && (
          <div className="px-5 pb-5 border-t border-gray-100 pt-4 space-y-5">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-gray-600 mb-1">Template Name</label>
                <input
                  type="text"
                  value={config.birthday_template_name}
                  onChange={(e) => setConfig((c) => ({ ...c, birthday_template_name: e.target.value }))}
                  placeholder="e.g. birthday_wishes"
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                />
                <p className="text-xs text-gray-400 mt-1">
                  Approved template: <span className="font-mono text-gray-500">birthday_wishes</span> — sends
                  <em> "🎉 Happy Birthday, {`{name}`}! 🎂 Wishing you a day filled with happiness…"</em>
                </p>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-600 mb-1">Language Code</label>
                <input
                  type="text"
                  value={config.birthday_template_language}
                  onChange={(e) => setConfig((c) => ({ ...c, birthday_template_language: e.target.value }))}
                  placeholder="e.g. en"
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                />
              </div>
            </div>

            <div className="flex items-center gap-3">
              <button
                onClick={handleSaveConfig}
                disabled={saving}
                className="flex items-center gap-1.5 px-4 py-2 text-sm bg-purple-600 text-white rounded-lg hover:bg-purple-700 disabled:opacity-60 font-medium"
              >
                <Save className="w-4 h-4" />
                {saving ? 'Saving…' : 'Save Config'}
              </button>
            </div>

            {/* Test Send */}
            <div className="border-t border-gray-100 pt-4">
              <p className="text-xs font-semibold text-gray-600 mb-3 uppercase tracking-wide">Test Send</p>
              <div className="flex flex-wrap gap-3 items-end">
                <div>
                  <label className="block text-xs text-gray-500 mb-1">Name</label>
                  <input
                    type="text"
                    value={testName}
                    onChange={(e) => setTestName(e.target.value)}
                    placeholder="John Doe"
                    className="px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none w-44"
                  />
                </div>
                <div>
                  <label className="block text-xs text-gray-500 mb-1">Phone</label>
                  <input
                    type="text"
                    value={testPhone}
                    onChange={(e) => setTestPhone(e.target.value)}
                    placeholder="9876543210"
                    className="px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none w-44"
                  />
                </div>
                <button
                  onClick={handleTestSend}
                  disabled={testSending}
                  className="px-4 py-2 text-sm bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:opacity-60 font-medium"
                >
                  {testSending ? 'Sending…' : 'Send Test'}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Employee Table */}
      <div className="bg-white rounded-xl border border-gray-200 shadow-sm">
        <div className="px-5 py-4 border-b border-gray-100 flex items-center justify-between gap-3">
          <div className="flex items-center gap-2 font-semibold text-gray-800">
            <Users className="w-5 h-5 text-blue-500" />
            Employees ({employees.length})
          </div>
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search name or phone…"
            className="px-3 py-1.5 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none w-56"
          />
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-16 text-gray-400 text-sm">Loading…</div>
        ) : filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-gray-400">
            <Users className="w-10 h-10 mb-3 opacity-30" />
            <p className="text-sm font-medium">No employees found</p>
            <p className="text-xs mt-1">Add an employee to get started.</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-gray-100 bg-gray-50">
                  {[
                    { label: 'Employee', field: 'employee_name' },
                    { label: 'Phone', field: 'phone_number' },
                    { label: 'Date of Birth', field: 'date_of_birth' },
                    { label: 'Status', field: 'is_active' },
                  ].map(({ label, field }) => (
                    <th
                      key={field}
                      onClick={() => toggleSort(field)}
                      className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide cursor-pointer hover:text-gray-700 select-none"
                    >
                      <span className="inline-flex items-center gap-1">{label} <SortIcon field={field} /></span>
                    </th>
                  ))}
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Notes</th>
                  <th className="px-4 py-3" />
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {filtered.map((emp) => (
                  <tr key={emp.id} className={`hover:bg-gray-50 transition-colors ${upcomingIds.has(emp.id) ? 'bg-yellow-50' : ''}`}>
                    <td className="px-4 py-3 font-medium text-gray-900">
                      <div className="flex items-center gap-2">
                        {upcomingIds.has(emp.id) && (
                          <span className="text-xs bg-yellow-100 text-yellow-700 px-1.5 py-0.5 rounded font-semibold">Soon</span>
                        )}
                        {emp.employee_name}
                      </div>
                    </td>
                    <td className="px-4 py-3 text-gray-600 font-mono text-xs">{emp.phone_number}</td>
                    <td className="px-4 py-3 text-gray-600">
                      <div className="flex items-center gap-1.5">
                        <Calendar className="w-3.5 h-3.5 text-gray-400" />
                        {monthDay(emp.date_of_birth)}
                        <span className="text-gray-400 text-xs">
                          ({new Date(emp.date_of_birth).getUTCFullYear()})
                        </span>
                      </div>
                    </td>
                    <td className="px-4 py-3">
                      <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium
                        ${emp.is_active ? 'bg-green-50 text-green-700' : 'bg-gray-100 text-gray-500'}`}>
                        {emp.is_active ? 'Active' : 'Inactive'}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-gray-400 text-xs max-w-xs truncate">{emp.notes || '—'}</td>
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-1.5 justify-end">
                        <button
                          onClick={() => openEdit(emp)}
                          className="p-1.5 rounded-lg text-gray-400 hover:text-blue-600 hover:bg-blue-50 transition-colors"
                          title="Edit"
                        >
                          <Pencil className="w-3.5 h-3.5" />
                        </button>
                        <button
                          onClick={() => setDeleteConfirm(emp.id)}
                          className="p-1.5 rounded-lg text-gray-400 hover:text-red-600 hover:bg-red-50 transition-colors"
                          title="Delete"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Add/Edit Modal */}
      {showForm && (
        <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/40 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-md mx-4 p-6">
            <div className="flex items-center justify-between mb-5">
              <h2 className="text-lg font-bold text-gray-900">{editId ? 'Edit Employee' : 'Add Employee'}</h2>
              <button onClick={closeForm} className="p-1.5 rounded-lg hover:bg-gray-100"><X className="w-4 h-4" /></button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-gray-600 mb-1">Employee Name *</label>
                <input
                  type="text"
                  value={form.employee_name}
                  onChange={(e) => setForm((f) => ({ ...f, employee_name: e.target.value }))}
                  placeholder="Full name"
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-600 mb-1">Phone Number *</label>
                <div className="relative">
                  <Phone className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-400" />
                  <input
                    type="tel"
                    value={form.phone_number}
                    onChange={(e) => setForm((f) => ({ ...f, phone_number: e.target.value }))}
                    placeholder="10-digit mobile"
                    className="w-full pl-9 pr-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                  />
                </div>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-600 mb-1">Date of Birth *</label>
                <div className="relative">
                  <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-400" />
                  <input
                    type="date"
                    value={form.date_of_birth}
                    onChange={(e) => setForm((f) => ({ ...f, date_of_birth: e.target.value }))}
                    className="w-full pl-9 pr-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                  />
                </div>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-600 mb-1">Notes</label>
                <input
                  type="text"
                  value={form.notes}
                  onChange={(e) => setForm((f) => ({ ...f, notes: e.target.value }))}
                  placeholder="Optional notes"
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                />
              </div>
              <label className="flex items-center gap-2 cursor-pointer select-none">
                <input
                  type="checkbox"
                  checked={form.is_active}
                  onChange={(e) => setForm((f) => ({ ...f, is_active: e.target.checked }))}
                  className="rounded"
                />
                <span className="text-sm text-gray-700">Active (will receive birthday greetings)</span>
              </label>

              {formError && (
                <div className="flex items-center gap-2 text-sm text-red-600 bg-red-50 rounded-lg px-3 py-2">
                  <AlertCircle className="w-4 h-4 shrink-0" />
                  {formError}
                </div>
              )}
            </div>

            <div className="flex gap-3 mt-6">
              <button
                onClick={handleSave}
                disabled={saving}
                className="flex-1 flex items-center justify-center gap-2 py-2.5 text-sm bg-blue-600 text-white rounded-xl hover:bg-blue-700 disabled:opacity-60 font-medium"
              >
                <Save className="w-4 h-4" />
                {saving ? 'Saving…' : editId ? 'Update' : 'Add Employee'}
              </button>
              <button onClick={closeForm} className="px-5 py-2.5 text-sm text-gray-600 border border-gray-200 rounded-xl hover:bg-gray-50">
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirm Modal */}
      {deleteConfirm && (
        <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/40 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-sm mx-4 p-6">
            <div className="flex items-start gap-3 mb-5">
              <div className="p-2 rounded-full bg-red-100"><Trash2 className="w-5 h-5 text-red-600" /></div>
              <div>
                <h3 className="font-bold text-gray-900">Remove Employee?</h3>
                <p className="text-sm text-gray-500 mt-1">
                  This will also delete all associated birthday greeting records. This cannot be undone.
                </p>
              </div>
            </div>
            <div className="flex gap-3">
              <button
                onClick={() => handleDelete(deleteConfirm)}
                className="flex-1 py-2.5 text-sm bg-red-600 text-white rounded-xl hover:bg-red-700 font-medium"
              >
                Yes, Remove
              </button>
              <button
                onClick={() => setDeleteConfirm(null)}
                className="flex-1 py-2.5 text-sm text-gray-600 border border-gray-200 rounded-xl hover:bg-gray-50"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useState, useCallback, useRef } from 'react';
import {
  CalendarClock, Plus, RefreshCw, Search, Clock, Loader, PauseCircle,
  CheckCircle2, Ban, XCircle, FileEdit, Copy, Pencil, Trash2, PlayCircle, Eye,
} from 'lucide-react';
import {
  fetchSchedules, pauseSchedule, resumeSchedule, cancelSchedule, deleteSchedule, duplicateSchedule,
} from '../services/festivalSchedulerService';
import { useMagicToast } from '../../../../context/MagicToastContext';
import CreateScheduleModal from '../components/scheduler/CreateScheduleModal';
import ScheduleProgressPanel from '../components/scheduler/ScheduleProgressPanel';

const STATUS_STYLES = {
  Draft: 'bg-gray-50 text-gray-600 border border-gray-200',
  Scheduled: 'bg-blue-50 text-blue-700 border border-blue-200',
  Running: 'bg-amber-50 text-amber-700 border border-amber-200',
  Paused: 'bg-orange-50 text-orange-700 border border-orange-200',
  Completed: 'bg-green-50 text-green-700 border border-green-200',
  Cancelled: 'bg-gray-100 text-gray-500 border border-gray-300',
  Failed: 'bg-red-50 text-red-700 border border-red-200',
};

const STATUS_ICONS = {
  Draft: FileEdit, Scheduled: Clock, Running: Loader, Paused: PauseCircle,
  Completed: CheckCircle2, Cancelled: Ban, Failed: XCircle,
};

const STATUS_FILTERS = ['All', 'Draft', 'Scheduled', 'Running', 'Paused', 'Completed', 'Cancelled', 'Failed'];

const fmtTime = (iso) => {
  if (!iso) return '—';
  return new Date(iso).toLocaleString('en-IN', {
    day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: true, timeZone: 'Asia/Kolkata',
  });
};

export default function FestivalSchedulerAdmin() {
  const { showToast } = useMagicToast();
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [modalSchedule, setModalSchedule] = useState(undefined); // undefined = closed, null = new, object = edit
  const [progressSchedule, setProgressSchedule] = useState(null);
  const refreshTimer = useRef(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const data = await fetchSchedules({ status: statusFilter, search });
      setRows(data);
    } catch (err) {
      showToast(err.message || 'Failed to load schedules.', 'error');
    } finally {
      setLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [statusFilter, search]);

  useEffect(() => {
    load();
    refreshTimer.current = setInterval(load, 60_000);
    return () => clearInterval(refreshTimer.current);
  }, [load]);

  const counts = STATUS_FILTERS.slice(1).reduce((acc, s) => {
    acc[s] = rows.filter((r) => r.status === s).length;
    return acc;
  }, {});

  const runAction = async (fn, successMsg) => {
    try {
      await fn();
      showToast(successMsg);
      load();
    } catch (err) {
      showToast(err.message || 'Action failed.', 'error');
    }
  };

  const handleDelete = (row) => {
    if (!window.confirm(`Delete schedule "${row.occasion}"? This cannot be undone.`)) return;
    runAction(() => deleteSchedule(row.id), 'Schedule deleted.');
  };

  return (
    <div className="space-y-6">
      <div className="flex items-start justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <CalendarClock className="w-6 h-6 text-pink-500" />
            Festival Scheduler
          </h1>
          <p className="text-xs text-gray-400 mt-1">Auto-refreshes every 60s · sends run automatically via the scheduled cron job.</p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={load}
            disabled={loading}
            className="flex items-center gap-1.5 px-3 py-2 text-sm rounded-lg border border-gray-200 text-gray-600 hover:bg-gray-50 disabled:opacity-60"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} /> Refresh
          </button>
          <button
            onClick={() => setModalSchedule(null)}
            className="flex items-center gap-1.5 px-3 py-2 text-sm rounded-lg bg-blue-600 text-white hover:bg-blue-700"
          >
            <Plus className="w-4 h-4" /> Create Schedule
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-3">
        {STATUS_FILTERS.slice(1).map((s) => {
          const Icon = STATUS_ICONS[s];
          return (
            <button
              key={s}
              onClick={() => setStatusFilter(s)}
              className={`rounded-xl border px-3 py-3 text-left ${STATUS_STYLES[s]} ${statusFilter === s ? 'ring-2 ring-offset-1 ring-blue-300' : ''}`}
            >
              <div className="text-xl font-bold">{counts[s] || 0}</div>
              <div className="text-[11px] font-medium mt-0.5 flex items-center gap-1"><Icon className="w-3 h-3" /> {s}</div>
            </button>
          );
        })}
      </div>

      <div className="bg-white rounded-xl border border-gray-200 shadow-sm">
        <div className="px-5 py-4 border-b border-gray-100 flex items-center gap-3 flex-wrap">
          <div className="relative flex-1 min-w-[200px]">
            <Search className="w-4 h-4 text-gray-300 absolute left-3 top-1/2 -translate-y-1/2" />
            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search by occasion or template…"
              className="w-full pl-9 pr-3 py-2 text-sm border border-gray-200 rounded-lg"
            />
          </div>
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="text-sm border border-gray-200 rounded-lg px-2 py-2 bg-white"
          >
            {STATUS_FILTERS.map((s) => <option key={s} value={s}>{s}</option>)}
          </select>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-20 text-gray-400 text-sm">
            <RefreshCw className="w-5 h-5 animate-spin mr-2" /> Loading…
          </div>
        ) : rows.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-gray-400">
            <CalendarClock className="w-12 h-12 mb-3 opacity-20" />
            <p className="text-sm font-medium">No schedules yet</p>
            <p className="text-xs mt-1">Click "Create Schedule" to plan your first festival campaign.</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-gray-100 bg-gray-50">
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Occasion</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Scheduled For</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Template</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Recipients</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Status</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {rows.map((row) => {
                  const StatusIcon = STATUS_ICONS[row.status] || Clock;
                  const canEdit = ['Draft', 'Scheduled'].includes(row.status);
                  const canPause = ['Scheduled', 'Running'].includes(row.status);
                  const canResume = row.status === 'Paused';
                  const canCancel = ['Draft', 'Scheduled', 'Paused'].includes(row.status);
                  const canDelete = ['Draft', 'Cancelled', 'Completed', 'Failed'].includes(row.status);

                  return (
                    <tr key={row.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-4 py-3 font-medium text-gray-900">{row.occasion}</td>
                      <td className="px-4 py-3 text-gray-500 text-xs">{fmtTime(row.schedule_at)}</td>
                      <td className="px-4 py-3 text-gray-600">{row.template_name}</td>
                      <td className="px-4 py-3 text-gray-600 text-xs">
                        {row.completed_recipients}/{row.total_recipients} sent
                        {row.failed_recipients > 0 && <span className="text-red-500"> · {row.failed_recipients} failed</span>}
                      </td>
                      <td className="px-4 py-3">
                        <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold ${STATUS_STYLES[row.status]}`}>
                          <StatusIcon className="w-3 h-3" /> {row.status}
                        </span>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-1.5 text-gray-400">
                          <button title="View Progress" onClick={() => setProgressSchedule(row)} className="p-1.5 hover:text-blue-600 hover:bg-blue-50 rounded"><Eye className="w-4 h-4" /></button>
                          {canEdit && (
                            <button title="Edit" onClick={() => setModalSchedule(row)} className="p-1.5 hover:text-blue-600 hover:bg-blue-50 rounded"><Pencil className="w-4 h-4" /></button>
                          )}
                          <button title="Duplicate" onClick={() => runAction(() => duplicateSchedule(row.id), 'Duplicated as a new draft.')} className="p-1.5 hover:text-blue-600 hover:bg-blue-50 rounded"><Copy className="w-4 h-4" /></button>
                          {canPause && (
                            <button title="Pause" onClick={() => runAction(() => pauseSchedule(row.id), 'Schedule paused.')} className="p-1.5 hover:text-orange-600 hover:bg-orange-50 rounded"><PauseCircle className="w-4 h-4" /></button>
                          )}
                          {canResume && (
                            <button title="Resume" onClick={() => runAction(() => resumeSchedule(row.id), 'Schedule resumed.')} className="p-1.5 hover:text-green-600 hover:bg-green-50 rounded"><PlayCircle className="w-4 h-4" /></button>
                          )}
                          {canCancel && (
                            <button title="Cancel" onClick={() => runAction(() => cancelSchedule(row.id), 'Schedule cancelled.')} className="p-1.5 hover:text-gray-700 hover:bg-gray-100 rounded"><Ban className="w-4 h-4" /></button>
                          )}
                          {canDelete && (
                            <button title="Delete" onClick={() => handleDelete(row)} className="p-1.5 hover:text-red-600 hover:bg-red-50 rounded"><Trash2 className="w-4 h-4" /></button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {modalSchedule !== undefined && (
        <CreateScheduleModal
          schedule={modalSchedule}
          onClose={() => setModalSchedule(undefined)}
          onSaved={() => { setModalSchedule(undefined); load(); }}
        />
      )}

      {progressSchedule && (
        <ScheduleProgressPanel schedule={progressSchedule} onClose={() => setProgressSchedule(null)} />
      )}
    </div>
  );
}

import React, { useEffect, useState, useCallback, useRef } from 'react';
import {
  Gift, RefreshCw, CheckCircle2, XCircle, Clock, Calendar,
  User, AlertCircle, Play, Cake,
} from 'lucide-react';
import {
  fetchTodaysBirthdayUsers,
  fetchTodaysBirthdayGreetings,
  triggerBirthdayEdgeFunction,
} from '../services/greetingsService';

const STATUS_STYLES = {
  Pending: 'bg-amber-50 text-amber-700 border border-amber-200',
  Sent:    'bg-green-50 text-green-700 border border-green-200',
  Failed:  'bg-red-50 text-red-700 border border-red-200',
};

const STATUS_ICONS = { Pending: Clock, Sent: CheckCircle2, Failed: XCircle };

const fmtDOB = (dob) => {
  if (!dob) return '—';
  return new Date(dob).toLocaleDateString('en-IN', {
    day: '2-digit', month: 'long', timeZone: 'UTC',
  });
};

const fmtTime = (iso) => {
  if (!iso) return '—';
  return new Date(iso).toLocaleString('en-IN', {
    day: '2-digit', month: 'short', year: 'numeric',
    hour: '2-digit', minute: '2-digit', hour12: true,
    timeZone: 'Asia/Kolkata',
  });
};

const getISTDateISO = () => {
  const ist = new Date(Date.now() + 5.5 * 60 * 60 * 1000);
  return ist.toISOString().split('T')[0];
};

export default function GreetingsAdmin() {
  const [rows, setRows] = useState([]);       // merged users + greeting status
  const [loading, setLoading] = useState(true);
  const [triggering, setTriggering] = useState(false);
  const [toast, setToast] = useState(null);
  const [lastRefresh, setLastRefresh] = useState(null);
  const refreshTimer = useRef(null);

  const showToast = (msg, type = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 4000);
  };

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [users, greetings] = await Promise.all([
        fetchTodaysBirthdayUsers(),
        fetchTodaysBirthdayGreetings(),
      ]);

      const greetingMap = Object.fromEntries(greetings.map((g) => [g.user_id, g]));

      const merged = users.map((u) => ({
        ...u,
        greeting: greetingMap[u.id] || null,
      }));

      setRows(merged);
      setLastRefresh(new Date());
    } catch (err) {
      showToast(err.message || 'Failed to load data.', 'error');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
    // Auto-refresh every 60 seconds so status updates appear without manual reload
    refreshTimer.current = setInterval(load, 60_000);
    return () => clearInterval(refreshTimer.current);
  }, [load]);

  const handleTrigger = async () => {
    setTriggering(true);
    try {
      const result = await triggerBirthdayEdgeFunction();
      showToast(
        result?.message ||
        `Ran birthday check — ${result?.sent ?? 0} sent, ${result?.failed ?? 0} failed, ${result?.skipped ?? 0} skipped.`
      );
      await load();
    } catch (err) {
      showToast(err.message || 'Edge function call failed.', 'error');
    } finally {
      setTriggering(false);
    }
  };

  const todayIST = getISTDateISO();
  const sentCount    = rows.filter((r) => r.greeting?.status === 'Sent').length;
  const pendingCount = rows.filter((r) => !r.greeting || r.greeting.status === 'Pending').length;
  const failedCount  = rows.filter((r) => r.greeting?.status === 'Failed').length;

  return (
    <div className="space-y-6">
      {/* Toast */}
      {toast && (
        <div className={`fixed top-5 right-5 z-50 flex items-center gap-2 px-4 py-3 rounded-lg shadow-lg text-sm font-medium
          ${toast.type === 'error'
            ? 'bg-red-50 text-red-700 border border-red-200'
            : 'bg-green-50 text-green-700 border border-green-200'}`}>
          {toast.type === 'error' ? <AlertCircle className="w-4 h-4" /> : <CheckCircle2 className="w-4 h-4" />}
          {toast.msg}
        </div>
      )}

      {/* Header */}
      <div className="flex items-start justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <Gift className="w-6 h-6 text-pink-500" />
            Birthday Greetings
          </h1>
          {lastRefresh && (
            <p className="text-xs text-gray-400 mt-1">
              Last refreshed: {lastRefresh.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', second: '2-digit' })} &nbsp;·&nbsp; auto-refreshes every 60 s
            </p>
          )}
        </div>
        <div className="flex gap-2">
          <button
            onClick={load}
            disabled={loading}
            className="flex items-center gap-1.5 px-3 py-2 text-sm rounded-lg border border-gray-200 text-gray-600 hover:bg-gray-50 disabled:opacity-60"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} /> Refresh
          </button>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        {[
          { label: "Today's Birthdays", value: rows.length,  color: 'text-gray-700',  bg: 'bg-gray-50 border-gray-200',   Icon: Cake },
          { label: 'Pending',           value: pendingCount, color: 'text-amber-700', bg: 'bg-amber-50 border-amber-200', Icon: Clock },
          { label: 'Sent',              value: sentCount,    color: 'text-green-700', bg: 'bg-green-50 border-green-200', Icon: CheckCircle2 },
          { label: 'Failed',            value: failedCount,  color: 'text-red-700',   bg: 'bg-red-50 border-red-200',     Icon: XCircle },
        ].map(({ label, value, color, bg, Icon }) => (
          <div key={label} className={`rounded-xl border px-4 py-4 ${bg}`}>
            <div className={`text-2xl font-bold ${color}`}>{value}</div>
            <div className={`text-xs font-medium mt-0.5 flex items-center gap-1 ${color}`}>
              <Icon className="w-3.5 h-3.5" /> {label}
            </div>
          </div>
        ))}
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl border border-gray-200 shadow-sm">
        <div className="px-5 py-4 border-b border-gray-100">
          <span className="font-semibold text-gray-800 flex items-center gap-2">
            <Calendar className="w-4 h-4 text-blue-500" />
            Today's Birthday Employees
          </span>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-20 text-gray-400 text-sm">
            <RefreshCw className="w-5 h-5 animate-spin mr-2" /> Loading…
          </div>
        ) : rows.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-gray-400">
            <Gift className="w-12 h-12 mb-3 opacity-20" />
            <p className="text-sm font-medium">No birthdays today</p>
            <p className="text-xs mt-1">Check back tomorrow, or ensure employees have their DOB set in their profile.</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-gray-100 bg-gray-50">
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Employee</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Employee ID</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Date of Birth</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Status</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Message Sent At</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {rows.map((row) => {
                  const status = row.greeting?.status || 'Pending';
                  const StatusIcon = STATUS_ICONS[status] || Clock;

                  return (
                    <tr key={row.id} className="hover:bg-gray-50 transition-colors">
                      {/* Employee */}
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-3">
                          {row.profile_image ? (
                            <img
                              src={row.profile_image}
                              alt={row.user_name}
                              className="w-9 h-9 rounded-full object-cover border border-gray-200 shrink-0"
                              onError={(e) => { e.target.style.display = 'none'; e.target.nextSibling.style.display = 'flex'; }}
                            />
                          ) : null}
                          <div className={`w-9 h-9 rounded-full bg-gradient-to-br from-pink-400 to-purple-500 flex items-center justify-center shrink-0 ${row.profile_image ? 'hidden' : 'flex'}`}>
                            <User className="w-4 h-4 text-white" />
                          </div>
                          <div>
                            <p className="font-medium text-gray-900">{row.user_name}</p>
                            <p className="text-xs text-gray-400 capitalize">{row.role}</p>
                          </div>
                        </div>
                      </td>

                      {/* Employee ID */}
                      <td className="px-4 py-3 text-gray-500 font-mono text-xs">
                        {String(row.id).slice(0, 8).toUpperCase()}
                      </td>

                      {/* DOB */}
                      <td className="px-4 py-3 text-gray-600">
                        <div className="flex items-center gap-1.5">
                          <Cake className="w-3.5 h-3.5 text-pink-400" />
                          {fmtDOB(row.dob)}
                        </div>
                      </td>

                      {/* Status */}
                      <td className="px-4 py-3">
                        <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold ${STATUS_STYLES[status]}`}>
                          <StatusIcon className="w-3 h-3" />
                          {status}
                        </span>
                      </td>

                      {/* Sent At */}
                      <td className="px-4 py-3 text-gray-500 text-xs">
                        {row.greeting?.sent_at ? fmtTime(row.greeting.sent_at) : '—'}
                        {row.greeting?.error_message && (
                          <div className="flex items-start gap-1 text-red-500 mt-0.5">
                            <AlertCircle className="w-3 h-3 mt-0.5 shrink-0" />
                            <span>{row.greeting.error_message}</span>
                          </div>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        <div className="px-5 py-3 border-t border-gray-100 text-xs text-gray-400">
          This is a read-only view. Greetings are sent automatically by the scheduled cron job at 11:00 AM IST.
          Use <strong>Run Now</strong> to trigger the edge function manually.
        </div>
      </div>
    </div>
  );
}

// src/systems/inventory/components/AuditLogView.jsx
import React from 'react';
import { useSelector } from 'react-redux';
import { ShieldAlert, Info } from 'lucide-react';

export default function AuditLogView() {
  const { audit } = useSelector((state) => state.inventory);

  const formatTimestamp = (ts) => {
    if (!ts) return '—';
    try {
      const date = new Date(ts);
      if (isNaN(date.getTime())) return ts;

      const yyyy = date.getFullYear();
      const mm = String(date.getMonth() + 1).padStart(2, '0');
      const dd = String(date.getDate()).padStart(2, '0');
      const hh = String(date.getHours()).padStart(2, '0');
      const min = String(date.getMinutes()).padStart(2, '0');
      const ss = String(date.getSeconds()).padStart(2, '0');

      return `${yyyy}-${mm}-${dd} ${hh}:${min}:${ss}`;
    } catch (e) {
      return ts;
    }
  };

  return (
    <div className="bg-white border border-gray-200 rounded-3xl p-6 shadow-sm space-y-6">
      <div className="flex items-center justify-between border-b border-gray-150 pb-4">
        <h3 className="text-lg font-black text-gray-900 flex items-center gap-2">
          <ShieldAlert className="text-indigo-500" size={20} />
          System Audit Trail logs
        </h3>
        <span className="text-xs text-gray-400 font-semibold">{audit.length} entries recorded</span>
      </div>

      <div className="divide-y divide-gray-100 max-h-[65vh] overflow-y-auto pr-2 space-y-0">
        {audit.length === 0 ? (
          <div className="text-center py-10 text-gray-400 flex flex-col items-center justify-center gap-2">
            <Info size={24} className="opacity-40" />
            <span>No audit entries logged yet.</span>
          </div>
        ) : (
          audit.map((log, idx) => (
            <div key={idx} className="py-4 first:pt-0 last:pb-0 flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-4 hover:bg-gray-50/30 px-2 rounded-xl transition-colors">
              <div className="font-mono text-xs text-gray-400 w-44 flex-shrink-0">
                {formatTimestamp(log.ts)}
              </div>
              <div className="flex-1 text-sm text-gray-700 leading-normal">
                <span className="font-bold text-gray-900 mr-1.5">{log.action}</span>
                <span>· {log.detail || ''}</span>
              </div>
              <div className="flex-shrink-0">
                <span className="inline-flex px-2 py-0.5 rounded-md text-[10px] font-bold uppercase tracking-wider bg-indigo-50 text-indigo-700 border border-indigo-100">
                  {log.user}
                </span>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

// src/systems/inventory/components/DashboardView.jsx
import React, { useMemo } from "react";
import { useSelector } from "react-redux";
import {
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
} from "recharts";
import {
  Boxes,
  TrendingDown,
  AlertTriangle,
  FileText,
  Layers,
  ArrowUpRight,
  TrendingUp,
} from "lucide-react";

const COLORS = [
  "#6366f1",
  "#a855f7",
  "#0d9488",
  "#d97706",
  "#0ea5e9",
  "#e11d48",
  "#a21caf",
];
const BAND_COLORS = {
  "Excess Stock": "#a855f7",
  "Normal Stock": "#22c55e",
  "66.33% Stock": "#eab308",
  "Below 33%": "#ef4444",
};

export default function DashboardView({ activeUser, onTabChange }) {
  const { materials, transactions, indents } = useSelector(
    (state) => state.inventory,
  );

  // Helper calculations
  const calculatedData = useMemo(() => {
    // 1. Calculate closing stock for each material
    const matClosing = {};
    materials.forEach((m) => {
      matClosing[m.sku] = Number(m.opening) || 0;
    });

    transactions.forEach((t) => {
      if (matClosing[t.sku] !== undefined) {
        if (t.type === "IN") {
          matClosing[t.sku] += Number(t.qty) || 0;
        } else {
          matClosing[t.sku] -= Number(t.qty) || 0;
        }
      }
    });

    const fullMaterials = materials.map((m) => {
      const closingStock = matClosing[m.sku] || 0;
      const safetyStock = (Number(m.adc) || 0) * (Number(m.safetyFactor) || 0);
      const reorderLevel =
        (Number(m.adc) || 0) * (Number(m.leadTime) || 0) + safetyStock;
      const maxLevel = reorderLevel + (Number(m.moq) || 0);

      // Stock band (only meaningful once ADC/consumption data exists —
      // otherwise maxLevel collapses to just the MOQ and any stock reads as "Excess")
      let band = "Normal Stock";
      if (maxLevel > 0 && (Number(m.adc) || 0) > 0) {
        const pct = (closingStock / maxLevel) * 100;
        if (pct > 100) band = "Excess Stock";
        else if (pct >= 66.33) band = "Normal Stock";
        else if (pct >= 33) band = "66.33% Stock";
        else band = "Below 33%";
      }

      return {
        ...m,
        closingStock,
        safetyStock,
        reorderLevel,
        maxLevel,
        band,
      };
    });

    // 2. Visible materials based on location filter
    const visibleMats = activeUser.location
      ? fullMaterials.filter((m) => m.location === activeUser.location)
      : fullMaterials;

    const visibleSkus = new Set(visibleMats.map((m) => m.sku));
    const visibleTxns = transactions.filter((t) => visibleSkus.has(t.sku));

    // 3. KPIs
    const totalSKUs = visibleMats.length;
    const totalQty = visibleMats.reduce((sum, m) => sum + m.closingStock, 0);
    const excessCount = visibleMats.filter(
      (m) => m.band === "Excess Stock",
    ).length;
    const lowCount = visibleMats.filter(
      (m) => m.band === "66.33% Stock",
    ).length;
    const criticalCount = visibleMats.filter(
      (m) => m.band === "Below 33%",
    ).length;
    const pendingIndents = indents.filter(
      (i) => i.status === "Pending" && visibleSkus.has(i.sku),
    ).length;

    // 4. Charts - Category wise closing stock
    const catMap = {};
    visibleMats.forEach((m) => {
      catMap[m.category] = (catMap[m.category] || 0) + m.closingStock;
    });
    const categoryData = Object.entries(catMap).map(([name, value]) => ({
      name,
      value,
    }));

    // 5. Charts - Inward vs Outward by month (last 6 months)
    const monthMap = {};
    visibleTxns.forEach((t) => {
      const month = t.date.slice(0, 7); // YYYY-MM
      if (!monthMap[month]) monthMap[month] = { month, Inward: 0, Outward: 0 };
      if (t.type === "IN") {
        monthMap[month].Inward = parseFloat(
          (monthMap[month].Inward + (Number(t.qty) || 0)).toFixed(2),
        );
      } else {
        monthMap[month].Outward = parseFloat(
          (monthMap[month].Outward + (Number(t.qty) || 0)).toFixed(2),
        );
      }
    });
    const inOutData = Object.values(monthMap)
      .sort((a, b) => a.month.localeCompare(b.month))
      .slice(-6);

    // 6. Charts - Top 5 Consumption (Outward Qty)
    const consMap = {};
    visibleTxns
      .filter((t) => t.type === "OUT")
      .forEach((t) => {
        consMap[t.name] = (consMap[t.name] || 0) + Number(t.qty);
      });
    const consumptionData = Object.entries(consMap)
      .map(([name, qty]) => ({ name, qty }))
      .sort((a, b) => b.qty - a.qty)
      .slice(0, 5);

    // 7. Charts - Stock Band Distribution
    const bandMap = {
      "Excess Stock": 0,
      "Normal Stock": 0,
      "66.33% Stock": 0,
      "Below 33%": 0,
    };
    visibleMats.forEach((m) => {
      bandMap[m.band] = (bandMap[m.band] || 0) + 1;
    });
    const bandData = Object.entries(bandMap).map(([name, count]) => ({
      name,
      count,
      fill: BAND_COLORS[name],
    }));

    return {
      kpis: {
        totalSKUs,
        totalQty,
        excessCount,
        lowCount,
        criticalCount,
        pendingIndents,
      },
      categoryData,
      inOutData,
      consumptionData,
      bandData,
    };
  }, [materials, transactions, indents, activeUser]);

  const { kpis, categoryData, inOutData, consumptionData, bandData } =
    calculatedData;

  const kpiCards = [
    {
      title: "Total SKU",
      value: kpis.totalSKUs,
      sub: `${materials.filter((m) => m.status === "Active").length} active SKUs`,
      icon: Layers,
      color: "from-blue-500 to-indigo-600",
      textColor: "text-indigo-600",
    },
    {
      title: "Total Inventory Qty",
      value: kpis.totalQty.toLocaleString(undefined, {
        maximumFractionDigits: 2,
      }),
      sub: "Items in all storage areas",
      icon: Boxes,
      color: "from-sky-400 to-blue-500",
      textColor: "text-sky-500",
    },
    {
      title: "Excess Stock Items",
      value: kpis.excessCount,
      sub: "Holding above Max levels",
      icon: ArrowUpRight,
      color: "from-blue-500 to-pink-600",
      textColor: "text-blue-600",
    },
    {
      title: "Low Stock (66.33%)",
      value: kpis.lowCount,
      sub: "Approaching reorder level",
      icon: TrendingDown,
      color: "from-amber-400 to-orange-500",
      textColor: "text-amber-600",
    },
    {
      title: "Critical (Below 33%)",
      value: kpis.criticalCount,
      sub: "Immediate reorder needed",
      icon: AlertTriangle,
      color: "from-rose-500 to-red-600",
      textColor: "text-rose-600",
    },
    {
      title: "Pending Indents",
      value: kpis.pendingIndents,
      sub: "Awaiting completion",
      icon: FileText,
      color: "from-emerald-500 to-teal-600",
      textColor: "text-emerald-600",
    },
  ];

  return (
    <div className="space-y-6">
      {/* KPI Summary Grid */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
        {kpiCards.map((c, i) => (
          <div
            key={i}
            className="relative overflow-hidden bg-white border border-gray-200 rounded-2xl p-4 shadow-sm hover:shadow-md transition-all duration-300"
          >
            <div className="flex items-center justify-between mb-2">
              <span className="text-xs font-bold text-gray-500 uppercase tracking-wider">
                {c.title}
              </span>
              <div
                className={`p-1.5 rounded-lg bg-gray-50 ${c.textColor}`}
              >
                <c.icon size={16} />
              </div>
            </div>
            <div className="text-2xl font-black text-gray-900 mb-1">
              {c.value}
            </div>
            <div className="text-xs text-gray-400 truncate">
              {c.sub}
            </div>
            <div
              className={`absolute bottom-0 left-0 right-0 h-1 bg-gradient-to-r ${c.color}`}
            />
          </div>
        ))}
      </div>

      {/* Main Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* Category distribution */}
        <div className="lg:col-span-5 bg-white border border-gray-200 rounded-3xl p-5 shadow-sm">
          <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wider mb-4 flex items-center gap-2">
            <span className="h-2.5 w-2.5 rounded-full bg-indigo-500" />
            Category-wise Stock Volume
          </h3>
          <div className="h-64 flex items-center justify-center">
            {categoryData.length === 0 ? (
              <div className="text-gray-400 text-xs">
                No stock data available
              </div>
            ) : (
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={categoryData}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={85}
                    paddingAngle={3}
                    dataKey="value"
                  >
                    {categoryData.map((entry, index) => (
                      <Cell
                        key={`cell-${index}`}
                        fill={COLORS[index % COLORS.length]}
                      />
                    ))}
                  </Pie>
                  <Tooltip
                    contentStyle={{
                      backgroundColor: "rgba(15, 23, 42, 0.9)",
                      border: "none",
                      borderRadius: "8px",
                      color: "#fff",
                      fontSize: "12px",
                    }}
                  />
                  <Legend
                    layout="horizontal"
                    verticalAlign="bottom"
                    align="center"
                    iconSize={8}
                    wrapperStyle={{ fontSize: "10px" }}
                  />
                </PieChart>
              </ResponsiveContainer>
            )}
          </div>
        </div>

        {/* Inward vs Outward */}
        <div className="lg:col-span-7 bg-white border border-gray-200 rounded-3xl p-5 shadow-sm">
          <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wider mb-4 flex items-center gap-2">
            <span className="h-2.5 w-2.5 rounded-full bg-teal-500" />
            Stock Movements (Inward vs Outward)
          </h3>
          <div className="h-64">
            {inOutData.length === 0 ? (
              <div className="h-full flex items-center justify-center text-gray-400 text-xs">
                No transactions recorded
              </div>
            ) : (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={inOutData}
                  margin={{ top: 10, right: 10, left: -10, bottom: 0 }}
                >
                  <XAxis
                    dataKey="month"
                    tickLine={false}
                    axisLine={false}
                    style={{ fontSize: "10px" }}
                  />
                  <YAxis
                    tickLine={false}
                    axisLine={false}
                    style={{ fontSize: "10px" }}
                  />
                  <Tooltip
                    contentStyle={{
                      backgroundColor: "rgba(15, 23, 42, 0.9)",
                      border: "none",
                      borderRadius: "8px",
                      color: "#fff",
                      fontSize: "12px",
                    }}
                    formatter={(value) => [
                      parseFloat(value).toFixed(2),
                      undefined,
                    ]}
                  />
                  <Legend
                    verticalAlign="bottom"
                    height={36}
                    iconSize={8}
                    wrapperStyle={{ fontSize: "10px" }}
                  />
                  <Bar dataKey="Inward" fill="#0d9488" radius={[4, 4, 0, 0]} />
                  <Bar dataKey="Outward" fill="#e11d48" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            )}
          </div>
        </div>
      </div>

      {/* Secondary Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Top 5 Consumption */}
        <div className="bg-white border border-gray-200 rounded-3xl p-5 shadow-sm">
          <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wider mb-4 flex items-center gap-2">
            <TrendingUp size={16} className="text-indigo-500" />
            Monthly Consumption (Top 5 Materials)
          </h3>
          <div className="h-64">
            {consumptionData.length === 0 ? (
              <div className="h-full flex items-center justify-center text-gray-400 text-xs">
                No consumption recorded (OUT transactions)
              </div>
            ) : (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={consumptionData}
                  layout="vertical"
                  margin={{ top: 10, right: 10, left: 20, bottom: 0 }}
                >
                  <XAxis
                    type="number"
                    tickLine={false}
                    axisLine={false}
                    style={{ fontSize: "10px" }}
                  />
                  <YAxis
                    dataKey="name"
                    type="category"
                    tickLine={false}
                    axisLine={false}
                    style={{ fontSize: "9px", fontWeight: "bold" }}
                    width={90}
                  />
                  <Tooltip
                    contentStyle={{
                      backgroundColor: "rgba(15, 23, 42, 0.9)",
                      border: "none",
                      borderRadius: "8px",
                      color: "#fff",
                      fontSize: "12px",
                    }}
                  />
                  <Bar
                    dataKey="qty"
                    fill="#6366f1"
                    radius={[0, 4, 4, 0]}
                    barSize={16}
                  />
                </BarChart>
              </ResponsiveContainer>
            )}
          </div>
        </div>

        {/* Stock band distribution */}
        <div className="bg-white border border-gray-200 rounded-3xl p-5 shadow-sm">
          <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wider mb-4 flex items-center gap-2">
            <span className="h-2.5 w-2.5 rounded-full bg-blue-500" />
            Stock Band Distribution (SKU Counts)
          </h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={bandData}
                margin={{ top: 10, right: 10, left: -25, bottom: 0 }}
              >
                <XAxis
                  dataKey="name"
                  tickLine={false}
                  axisLine={false}
                  style={{ fontSize: "10px" }}
                />
                <YAxis
                  tickLine={false}
                  axisLine={false}
                  allowDecimals={false}
                  style={{ fontSize: "10px" }}
                />
                <Tooltip
                  contentStyle={{
                    backgroundColor: "rgba(15, 23, 42, 0.9)",
                    border: "none",
                    borderRadius: "8px",
                    color: "#fff",
                    fontSize: "12px",
                  }}
                />
                <Bar dataKey="count" radius={[4, 4, 0, 0]} barSize={40}>
                  {bandData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
}

// src/systems/inventory/components/IndentView.jsx
import React, { useState, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import {
  Search,
  SlidersHorizontal,
  FileSpreadsheet,
  X,
  FileText,
  CheckCircle,
  Clock
} from 'lucide-react';
import Papa from 'papaparse';
import { jsPDF } from 'jspdf';
import { updateIndentStatus } from '../redux/slice/inventorySlice';

export default function IndentView({ activeUser }) {
  const dispatch = useDispatch();
  const { indents, settings } = useSelector((state) => state.inventory);

  const isViewer = activeUser.role === 'Viewer';

  // Filters state
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [supplier, setSupplier] = useState('');

  // Modal State
  const [selectedIndentNo, setSelectedIndentNo] = useState(null);

  // Sorting & Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const [sortKey, setSortKey] = useState('indentNo');
  const [sortDir, setSortDir] = useState(-1); // latest first

  // Select indent details
  const activeIndent = useMemo(() => {
    return indents.find(i => i.indentNo === selectedIndentNo);
  }, [indents, selectedIndentNo]);

  // Filter indents
  const filteredIndents = useMemo(() => {
    let rows = indents.slice();

    if (search) {
      const q = search.toLowerCase();
      rows = rows.filter(r =>
        r.indentNo.toLowerCase().includes(q) ||
        r.sku.toLowerCase().includes(q) ||
        r.name.toLowerCase().includes(q) ||
        r.requestedBy.toLowerCase().includes(q)
      );
    }
    if (statusFilter) {
      rows = rows.filter(r => r.status === statusFilter);
    }
    if (fromDate) {
      rows = rows.filter(r => r.date >= fromDate);
    }
    if (toDate) {
      rows = rows.filter(r => r.date <= toDate);
    }
    if (supplier) {
      rows = rows.filter(r => (r.supplierName || '').toLowerCase().includes(supplier.toLowerCase()));
    }

    // Sort
    return rows.sort((a, b) => {
      let va = a[sortKey], vb = b[sortKey];
      if (typeof va === 'string') va = va.toLowerCase();
      if (typeof vb === 'string') vb = vb.toLowerCase();
      if (va < vb) return -1 * sortDir;
      if (va > vb) return 1 * sortDir;
      return 0;
    });
  }, [indents, search, statusFilter, fromDate, toDate, supplier, sortKey, sortDir]);

  // Pagination details
  const pageSize = settings?.pageSize?.txn || 6;
  const totalPages = Math.max(1, Math.ceil(filteredIndents.length / pageSize));
  const paginatedIndents = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return filteredIndents.slice(start, start + pageSize);
  }, [filteredIndents, currentPage, pageSize]);

  const requestSort = (key) => {
    if (sortKey === key) {
      setSortDir(prev => -prev);
    } else {
      setSortKey(key);
      setSortDir(1);
    }
    setCurrentPage(1);
  };

  // Toggle Approved / Pending
  const handleToggleStatus = () => {
    if (!activeIndent) return;
    const newStatus = activeIndent.status === 'Approved' ? 'Pending' : 'Approved';
    dispatch(updateIndentStatus({
      indentNo: activeIndent.indentNo,
      status: newStatus,
      currentUser: activeUser.name
    }));
  };

  // Download PDF
  const handleDownloadPdf = () => {
    if (!activeIndent) return;
    const r = activeIndent;
    const doc = new jsPDF();

    // Premium styling headers
    doc.setFontSize(20);
    doc.setTextColor(79, 70, 229); // Indigo theme color
    doc.text('IMS — Material Indent', 14, 22);

    doc.setFontSize(10);
    doc.setTextColor(100);
    doc.text('System Generated PDF · Date: ' + new Date().toLocaleString(), 14, 29);

    doc.setDrawColor(227, 225, 245);
    doc.line(14, 34, 196, 34);

    doc.setFontSize(12);
    doc.setTextColor(20);

    const lines = [
      ['Indent Number', r.indentNo],
      ['Date Generated', r.date],
      ['Requested By', r.requestedBy],
      ['Requester Department', r.department],
      ['SKU Code / Material ID', r.sku],
      ['Material Description', r.name],
      ['Current Closing Stock', r.currentStock.toLocaleString()],
      ['Reorder Quantity Shortage', r.reorderQty.toLocaleString()],
      ['Assigned Supplier', r.supplierName],
      ['Current Indent Status', r.status]
    ];

    let y = 48;
    lines.forEach(([k, v]) => {
      doc.setFont(undefined, 'bold');
      doc.text(k + ':', 14, y);
      doc.setFont(undefined, 'normal');
      doc.text(String(v), 70, y);
      y += 10;
    });

    doc.save(`${r.indentNo}.pdf`);
  };

  // Export CSV
  const handleExport = () => {
    const exportData = filteredIndents.map(r => ({
      'Indent No': r.indentNo,
      'Date': r.date,
      'Requested By': r.requestedBy,
      'Department': r.department,
      'SKU Code': r.sku,
      'Material Name': r.name,
      'Current Stock': r.currentStock,
      'Reorder Qty': r.reorderQty,
      'Supplier': r.supplierName,
      'Status': r.status
    }));

    const csv = Papa.unparse(exportData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `Purchase_Indents_${new Date().toISOString().slice(0, 10)}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      {/* Toolbar */}
      <div className="flex flex-wrap items-center gap-3 bg-white border border-gray-200 rounded-3xl p-4 shadow-xs">
        <div className="relative flex-1 min-w-[220px]">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input
            type="text"
            value={search}
            onChange={(e) => { setSearch(e.target.value); setCurrentPage(1); }}
            placeholder="Search indent no, SKU, requester..."
            className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-xl bg-gray-50 text-gray-900 text-sm focus:ring-2 focus:ring-indigo-500 outline-hidden"
          />
        </div>

        <select
          value={statusFilter}
          onChange={(e) => { setStatusFilter(e.target.value); setCurrentPage(1); }}
          className="px-3 py-2 border border-gray-200 rounded-xl bg-gray-50 text-gray-900 text-sm cursor-pointer"
        >
          <option value="">All Status</option>
          <option value="Pending">Pending</option>
          <option value="Approved">Approved</option>
          <option value="Rejected">Rejected</option>
        </select>

        <button
          onClick={() => setShowFilters(prev => !prev)}
          className={`flex items-center gap-2 px-4 py-2 border rounded-xl text-sm font-bold transition-all cursor-pointer ${
            showFilters
              ? 'border-indigo-500 bg-indigo-50 text-indigo-700'
              : 'border-gray-200 text-gray-700 hover:border-indigo-500 hover:text-indigo-600'
          }`}
        >
          <SlidersHorizontal size={16} />
          More Filters
        </button>

        <button
          onClick={handleExport}
          className="flex items-center gap-1.5 px-4 py-2 border border-gray-200 rounded-xl text-sm font-bold text-gray-700 bg-white cursor-pointer"
        >
          <FileSpreadsheet size={16} />
          Export CSV
        </button>
      </div>

      {/* Expanded Filters */}
      {showFilters && (
        <div className="flex flex-wrap gap-4 bg-gray-50 border border-dashed border-gray-200 p-4 rounded-2xl">
          <div className="flex flex-col gap-1.5">
            <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">From Date</label>
            <input
              type="date"
              value={fromDate}
              onChange={(e) => { setFromDate(e.target.value); setCurrentPage(1); }}
              className="px-3.5 py-1.5 border border-gray-200 rounded-xl bg-white text-sm text-gray-950"
            />
          </div>
          <div className="flex flex-col gap-1.5">
            <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">To Date</label>
            <input
              type="date"
              value={toDate}
              onChange={(e) => { setToDate(e.target.value); setCurrentPage(1); }}
              className="px-3.5 py-1.5 border border-gray-200 rounded-xl bg-white text-sm text-gray-955"
            />
          </div>
          <div className="flex flex-col gap-1.5">
            <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Supplier</label>
            <input
              type="text"
              value={supplier}
              onChange={(e) => { setSupplier(e.target.value); setCurrentPage(1); }}
              placeholder="e.g. Tata Steel"
              className="px-3.5 py-1.5 border border-gray-200 rounded-xl bg-white text-sm text-gray-950 w-40"
            />
