                </div>
                <div className="flex flex-col gap-1.5">
                  <label className="text-[10px] font-black text-gray-450 uppercase tracking-wider">Date</label>
                  <div className="px-4 py-2.5 bg-indigo-50/40 text-indigo-700 font-bold rounded-lg text-sm">
                    {activeIndent.date}
                  </div>
                </div>
                <div className="flex flex-col gap-1.5">
                  <label className="text-[10px] font-black text-gray-450 uppercase tracking-wider">Requested By</label>
                  <div className="px-4 py-2.5 bg-indigo-50/40 text-indigo-700 font-bold rounded-lg text-sm">
                    {activeIndent.requestedBy}
                  </div>
                </div>
                <div className="flex flex-col gap-1.5">
                  <label className="text-[10px] font-black text-gray-450 uppercase tracking-wider">Department</label>
                  <div className="px-4 py-2.5 bg-indigo-50/40 text-indigo-700 font-bold rounded-lg text-sm">
                    {activeIndent.department}
                  </div>
                </div>
                <div className="flex flex-col gap-1.5">
                  <label className="text-[10px] font-black text-gray-450 uppercase tracking-wider">SKU Code</label>
                  <div className="px-4 py-2.5 bg-indigo-50/40 text-indigo-700 font-bold rounded-lg text-sm">
                    {activeIndent.sku}
                  </div>
                </div>
                <div className="flex flex-col gap-1.5">
                  <label className="text-[10px] font-black text-gray-450 uppercase tracking-wider">Material Name</label>
                  <div className="px-4 py-2.5 bg-indigo-50/40 text-indigo-700 font-bold rounded-lg text-sm truncate" title={activeIndent.name}>
                    {activeIndent.name}
                  </div>
                </div>
                <div className="flex flex-col gap-1.5">
                  <label className="text-[10px] font-black text-gray-450 uppercase tracking-wider">Current Stock</label>
                  <div className="px-4 py-2.5 bg-indigo-50/40 text-indigo-700 font-bold rounded-lg text-sm">
                    {activeIndent.currentStock.toLocaleString()}
                  </div>
                </div>
                <div className="flex flex-col gap-1.5">
                  <label className="text-[10px] font-black text-gray-450 uppercase tracking-wider">Reorder Quantity</label>
                  <div className="px-4 py-2.5 bg-indigo-50/40 text-indigo-700 font-bold rounded-lg text-sm">
                    {activeIndent.reorderQty.toLocaleString()}
                  </div>
                </div>
                <div className="flex flex-col gap-1.5 col-span-2">
                  <label className="text-[10px] font-black text-gray-450 uppercase tracking-wider">Supplier Name</label>
                  <div className="px-4 py-2.5 bg-indigo-50/40 text-indigo-700 font-bold rounded-lg text-sm">
                    {activeIndent.supplierName}
                  </div>
                </div>
                <div className="flex flex-col gap-1.5 col-span-2">
                  <label className="text-[10px] font-black text-gray-450 uppercase tracking-wider">Status</label>
                  <div className="px-4 py-2.5 bg-indigo-50/40 text-indigo-700 font-bold rounded-lg text-sm">
                    {activeIndent.status}
                  </div>
                </div>
              </div>

              {/* Status change actions */}
              {!isViewer && (
                <div className="pt-2 flex gap-2">
                  {activeIndent.status !== 'Approved' && (
                    <button
                      onClick={() => dispatch(updateIndentStatus({ indentNo: activeIndent.indentNo, status: 'Approved', currentUser: activeUser.name }))}
                      className="px-4 py-2 border border-emerald-200 bg-emerald-50 text-emerald-700 rounded-xl text-xs font-bold transition-all hover:bg-emerald-100 cursor-pointer"
                    >
                      ✓ Mark as Approved
                    </button>
                  )}
                  {activeIndent.status !== 'Rejected' && (
                    <button
                      onClick={() => dispatch(updateIndentStatus({ indentNo: activeIndent.indentNo, status: 'Rejected', currentUser: activeUser.name }))}
                      className="px-4 py-2 border border-red-200 bg-red-50 text-red-700 rounded-xl text-xs font-bold transition-all hover:bg-red-100 cursor-pointer"
                    >
                      ✕ Mark as Rejected
                    </button>
                  )}
                  {activeIndent.status !== 'Pending' && (
                    <button
                      onClick={() => dispatch(updateIndentStatus({ indentNo: activeIndent.indentNo, status: 'Pending', currentUser: activeUser.name }))}
                      className="px-4 py-2 border border-amber-200 bg-amber-50 text-amber-700 rounded-xl text-xs font-bold transition-all hover:bg-amber-100 cursor-pointer"
                    >
                      ↩ Reset to Pending
                    </button>
                  )}
                </div>
              )}
            </div>

            <div className="flex justify-between items-center border-t border-gray-150 px-6 py-4 bg-gray-50 rounded-b-3xl">
              <button
                onClick={handleDownloadPdf}
                className="flex items-center gap-1.5 px-4 py-2.5 border border-gray-200 hover:border-indigo-500 rounded-xl text-xs font-bold bg-white text-gray-700 hover:bg-gray-50 cursor-pointer"
              >
                <span>↓</span> Download PDF
              </button>
              <button
                onClick={() => setSelectedIndentNo(null)}
                className="px-6 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-sm font-bold shadow-xs cursor-pointer active:scale-95 transition-all"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// src/systems/inventory/components/MasterDataView.jsx
import React, { useState, useMemo } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  Plus,
  Search,
  SlidersHorizontal,
  ChevronDown,
  Download,
  Upload,
  Edit2,
  Trash2,
  X,
  FileSpreadsheet,
} from "lucide-react";
import Papa from "papaparse";
import {
  saveMaterial,
  deleteMaterial,
  saveList,
} from "../redux/slice/inventorySlice";

export default function MasterDataView({ activeUser }) {
  const dispatch = useDispatch();
  const {
    materials,
    units,
    locations,
    settings,
    materialNames = [],
  } = useSelector((state) => state.inventory);

  const isViewer = activeUser.role === "Viewer";

  // State
  const [search, setSearch] = useState("");
  const [category, setCategory] = useState("");
  const [status, setStatus] = useState("");
  const [showFilters, setShowFilters] = useState(false);
  const [supplier, setSupplier] = useState("");
  const [unitFilter, setUnitFilter] = useState("");
  const [minMoq, setMinMoq] = useState("");

  // Pagination & Sorting state
  const [currentPage, setCurrentPage] = useState(1);
  const [sortKey, setSortKey] = useState("sku");
  const [sortDir, setSortDir] = useState(1); // 1 = asc, -1 = desc

  // Modal form state
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalMode, setModalMode] = useState("add"); // 'add' or 'edit'
  const [formSku, setFormSku] = useState("");
  const [formName, setFormName] = useState("");
  const [formCategory, setFormCategory] = useState("");
  const [formSubCategory, setFormSubCategory] = useState("");
  const [formUnit, setFormUnit] = useState("");
  const [formLocation, setFormLocation] = useState("");
  const [formOpening, setFormOpening] = useState(0);
  const [formAdc, setFormAdc] = useState(0);
  const [formLeadTime, setFormLeadTime] = useState(0);
  const [formSafetyFactor, setFormSafetyFactor] = useState(0);
  const [formMoq, setFormMoq] = useState(0);
  const [formSupplierName, setFormSupplierName] = useState("");
  const [formSupplierCode, setFormSupplierCode] = useState("");
  const [formStatus, setFormStatus] = useState("Active");
  const [showCategoryDropdown, setShowCategoryDropdown] = useState(false);
  const [showNameDropdown, setShowNameDropdown] = useState(false);

  // Categories list
  const categories = useMemo(() => {
    return [...new Set(materials.map((m) => m.category))].filter(Boolean);
  }, [materials]);

  // Material names list
  const materialNamesSuggestions = useMemo(() => {
    const activeNames = materials.map((m) => m.name);
    return [...new Set([...materialNames, ...activeNames])].filter(Boolean);
  }, [materials, materialNames]);

  const DEFAULT_CATEGORIES = ["Raw Material", "F G Material"];

  const filteredCategorySuggestions = useMemo(() => {
    const allCategories = [...new Set([...DEFAULT_CATEGORIES, ...categories])];
    return allCategories.filter((c) =>
      c.toLowerCase().includes(formCategory.toLowerCase()),
    );
  }, [categories, formCategory]);

  const filteredNameSuggestions = useMemo(() => {
    return materialNamesSuggestions.filter((n) =>
      n.toLowerCase().includes(formName.toLowerCase()),
    );
  }, [materialNamesSuggestions, formName]);

  // Derived columns calculation
  const calculatedRows = useMemo(() => {
    return materials.map((m) => {
      const safetyStock = (Number(m.adc) || 0) * (Number(m.safetyFactor) || 0);
      const reorderLevel =
        (Number(m.adc) || 0) * (Number(m.leadTime) || 0) + safetyStock;
      const maxLevel = reorderLevel + (Number(m.moq) || 0);
      return {
        ...m,
        safetyStock,
        reorderLevel,
        maxLevel,
      };
    });
  }, [materials]);

  // Filtered materials
  const filteredMaterials = useMemo(() => {
    let rows = activeUser.location
      ? calculatedRows.filter((m) => m.location === activeUser.location)
      : calculatedRows;

    if (search) {
      const q = search.toLowerCase();
      rows = rows.filter(
        (r) =>
          r.sku.toLowerCase().includes(q) ||
          r.name.toLowerCase().includes(q) ||
          r.category.toLowerCase().includes(q) ||
          (r.supplierName || "").toLowerCase().includes(q),
      );
    }
    if (category) {
      rows = rows.filter((r) => r.category === category);
    }
    if (status) {
      rows = rows.filter((r) => r.status === status);
    }
    if (supplier) {
      rows = rows.filter((r) =>
        (r.supplierName || "").toLowerCase().includes(supplier.toLowerCase()),
      );
    }
    if (unitFilter) {
      rows = rows.filter((r) => r.unit === unitFilter);
    }
    if (minMoq) {
      rows = rows.filter((r) => r.moq >= Number(minMoq));
    }

    // Sort
    return rows.sort((a, b) => {
      let va = a[sortKey],
        vb = b[sortKey];
      if (typeof va === "string") va = va.toLowerCase();
      if (typeof vb === "string") vb = vb.toLowerCase();
      if (va < vb) return -1 * sortDir;
      if (va > vb) return 1 * sortDir;
      return 0;
    });
  }, [
    calculatedRows,
    search,
    category,
    status,
    supplier,
    unitFilter,
    minMoq,
    sortKey,
    sortDir,
    activeUser,
  ]);

  // Pagination details
  const pageSize = settings?.pageSize?.master || 6;
  const totalPages = Math.max(
    1,
    Math.ceil(filteredMaterials.length / pageSize),
  );
  const paginatedMaterials = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return filteredMaterials.slice(start, start + pageSize);
  }, [filteredMaterials, currentPage, pageSize]);

  // Handle Sort Request
  const requestSort = (key) => {
    if (sortKey === key) {
      setSortDir((prev) => -prev);
    } else {
      setSortKey(key);
      setSortDir(1);
    }
    setCurrentPage(1);
  };

  // Calculations for Add/Edit Modal
  const modalSafetyStock =
    (Number(formAdc) || 0) * (Number(formSafetyFactor) || 0);
  const modalReorderLevel =
    (Number(formAdc) || 0) * (Number(formLeadTime) || 0) + modalSafetyStock;
  const modalMaxLevel = modalReorderLevel + (Number(formMoq) || 0);

  // Edit action
  const handleEdit = (sku) => {
    const item = materials.find((m) => m.sku === sku);
    if (!item) return;
    setModalMode("edit");
    setFormSku(item.sku);
    setFormName(item.name);
    setFormCategory(item.category);
    setFormSubCategory(item.subCategory || "");
    setFormUnit(item.unit);
    setFormLocation(item.location || "");
    setFormOpening(item.opening || 0);
    setFormAdc(item.adc || 0);
    setFormLeadTime(item.leadTime || 0);
    setFormSafetyFactor(item.safetyFactor || 0);
    setFormMoq(item.moq || 0);
    setFormSupplierName(item.supplierName || "");
    setFormSupplierCode(item.supplierCode || "");
    setFormStatus(item.status || "Active");
    setIsModalOpen(true);
  };

  // Delete action
  const handleDelete = (sku) => {
    if (
      window.confirm(
        `Are you sure you want to delete material ${sku}? This cannot be undone.`,
      )
    ) {
      dispatch(deleteMaterial({ sku, currentUser: activeUser.name }));
    }
  };

  // Open Add modal
  const handleAdd = () => {
    setModalMode("add");
    setFormSku("");
    setFormName("");
    setFormCategory("");
    setFormSubCategory("");
    setFormUnit(units[0] || "KG");
    setFormLocation(locations[0] || "");
    setFormOpening(0);
    setFormAdc(0);
    setFormLeadTime(0);
    setFormSafetyFactor(0);
    setFormMoq(0);
    setFormSupplierName("");
    setFormSupplierCode("");
    setFormStatus("Active");
    setIsModalOpen(true);
  };

  // Save material handler
  const handleSave = (e) => {
    e.preventDefault();
    if (!formSku || !formName || !formCategory || !formUnit) {
      alert("Please fill out all required fields marked with *");
      return;
    }

    if (
      modalMode === "add" &&
      materials.some(
        (m) => m.sku.toLowerCase() === formSku.trim().toLowerCase(),
      )
    ) {
      alert(`SKU ${formSku} already exists in master data!`);
      return;
    }

    const payload = {
      sku: formSku.trim(),
      name: formName.trim(),
      category: formCategory.trim(),
      subCategory: formSubCategory.trim(),
      unit: formUnit,
      location: formLocation,
      opening: Number(formOpening) || 0,
      adc: Number(formAdc) || 0,
      leadTime: Number(formLeadTime) || 0,
      safetyFactor: Number(formSafetyFactor) || 0,
      moq: Number(formMoq) || 0,
      supplierName: formSupplierName.trim(),
      supplierCode: formSupplierCode.trim(),
      status: formStatus,
    };

    dispatch(saveMaterial({ material: payload, currentUser: activeUser.name }));
    setIsModalOpen(false);
  };

  const handleAddNewUnitPrompt = () => {
    const val = prompt("Enter new Unit of Measurement (e.g. BAG, DRUM):");
    if (!val) return;
    const formatted = val.trim().toUpperCase();
    if (!formatted) return;
    if (units.includes(formatted)) {
      alert("Unit already exists.");
      return;
    }
    const updated = [...units, formatted];
    dispatch(
      saveList({ type: "units", list: updated, currentUser: activeUser.name }),
    );
    setFormUnit(formatted);
  };

  const handleAddNewCategoryPrompt = () => {
    const val = prompt("Enter new Category Name (e.g. Packaging, Spares):");
    if (!val) return;
    const formatted = val.trim();
    if (!formatted) return;
    setFormCategory(formatted);
  };

  // Export CSV
  const handleExport = () => {
    const exportData = filteredMaterials.map((m) => ({
      "SKU Code": m.sku,
      "Material Name": m.name,
      Category: m.category,
      "Sub Category": m.subCategory || "",
      Unit: m.unit,
      "Storage Location": m.location || "",
      "Opening Stock": m.opening || 0,
      "Average Daily Consumption (ADC)": m.adc,
      "Lead Time (Days)": m.leadTime,
      "Safety Factor": m.safetyFactor,
      MOQ: m.moq,
      "Supplier Name": m.supplierName || "",
      "Supplier Code": m.supplierCode || "",
      "Material Status": m.status,
    }));

    const csv = Papa.unparse(exportData);
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute(
      "download",
      `Master_Materials_${new Date().toISOString().slice(0, 10)}.csv`,
    );
    link.style.visibility = "hidden";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Download template
  const handleDownloadTemplate = () => {
    const headers = [
      [
        "SKU Code",
        "Material Name",
        "Category",
        "Sub Category",
        "Unit",
        "Storage Location",
        "Opening Stock",
        "Average Daily Consumption (ADC)",
        "Lead Time (Days)",
        "Safety Factor",
        "MOQ",
        "Supplier Name",
        "Supplier Code",
        "Material Status",
      ],
    ];
    const csv = Papa.unparse(headers);
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `Master_Data_Template.csv`);
    link.style.visibility = "hidden";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Import CSV
  const handleImportFile = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        try {
          let added = 0;
          let updated = 0;
          results.data.forEach((row) => {
            const sku = String(row["SKU Code"] || "").trim();
            if (!sku) return;

            const payload = {
              sku,
              name: String(row["Material Name"] || "").trim(),
              category: String(row["Category"] || "").trim(),
              subCategory: String(row["Sub Category"] || "").trim(),
              unit: String(row["Unit"] || "KG").trim(),
              location: String(row["Storage Location"] || "").trim(),
              opening: Number(row["Opening Stock"]) || 0,
              adc: Number(row["Average Daily Consumption (ADC)"]) || 0,
              leadTime: Number(row["Lead Time (Days)"]) || 0,
              safetyFactor: Number(row["Safety Factor"]) || 0,
              moq: Number(row["MOQ"]) || 0,
              supplierName: String(row["Supplier Name"] || "").trim(),
              supplierCode: String(row["Supplier Code"] || "").trim(),
              status:
                String(row["Material Status"] || "Active").trim() || "Active",
            };

            dispatch(
              saveMaterial({ material: payload, currentUser: activeUser.name }),
            );
            if (materials.some((m) => m.sku === sku)) updated++;
            else added++;
          });
          alert(`Import complete: ${added} added, ${updated} updated.`);
        } catch (err) {
          alert("Failed to parse file. Please verify CSV headers.");
        }
      },
    });
