// src/systems/inventory/components/TransactionsView.jsx
import React, { useState, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import {
  Search,
  SlidersHorizontal,
  FileSpreadsheet,
  ArrowDownLeft,
  ArrowUpRight
} from 'lucide-react';
import Papa from 'papaparse';
import { postTransaction, saveSettings } from '../redux/slice/inventorySlice';

export default function TransactionsView({ activeUser }) {
  const dispatch = useDispatch();
  const { materials, transactions, settings, locations = [] } = useSelector((state) => state.inventory);

  const isViewer = activeUser.role === 'Viewer';

  // Filters
  const [search, setSearch] = useState('');
  const [typeFilter, setTypeFilter] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');

  // Pagination & Sorting state
  const [currentPage, setCurrentPage] = useState(1);
  const [sortKey, setSortKey] = useState('date');
  const [sortDir, setSortDir] = useState(-1);

  // Filter transactions
  const filteredTxns = useMemo(() => {
    let rows = transactions.slice();

    // Visibility filter based on warehouse location restrictions
    if (activeUser.location) {
      const locationSkus = new Set(materials.filter(m => m.location === activeUser.location).map(m => m.sku));
      rows = rows.filter(t => locationSkus.has(t.sku));
    }

    if (search) {
      const q = search.toLowerCase();
      rows = rows.filter(r =>
        r.id.toLowerCase().includes(q) ||
        r.sku.toLowerCase().includes(q) ||
        r.name.toLowerCase().includes(q) ||
        (r.ref || '').toLowerCase().includes(q) ||
        (r.user || '').toLowerCase().includes(q)
      );
    }
    if (typeFilter) {
      rows = rows.filter(r => r.type === typeFilter);
    }
    if (fromDate) {
      rows = rows.filter(r => r.date >= fromDate);
    }
    if (toDate) {
      rows = rows.filter(r => r.date <= toDate);
    }

    // Sort
    return rows.sort((a, b) => {
      let va = a[sortKey], vb = b[sortKey];
      if (typeof va === 'string') va = va.toLowerCase();
      if (typeof vb === 'string') vb = vb.toLowerCase();
      if (va < vb) return -1 * sortDir;
      if (va > vb) return 1 * sortDir;
      return 0;
    });
  }, [transactions, search, typeFilter, fromDate, toDate, sortKey, sortDir, materials, activeUser]);

  // Pagination details
  const pageSize = settings?.pageSize?.txn || 6;
  const totalPages = Math.max(1, Math.ceil(filteredTxns.length / pageSize));
  const paginatedTxns = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return filteredTxns.slice(start, start + pageSize);
  }, [filteredTxns, currentPage, pageSize]);

  const handlePageSizeChange = (e) => {
    const newSize = Number(e.target.value);
    dispatch(saveSettings({
      settings: {
        ...settings,
        pageSize: {
          ...settings?.pageSize,
          txn: newSize
        }
      },
      currentUser: activeUser.name
    }));
    setCurrentPage(1);
  };

  // Handle sort request
  const requestSort = (key) => {
    if (sortKey === key) {
      setSortDir(prev => -prev);
    } else {
      setSortKey(key);
      setSortDir(1);
    }
    setCurrentPage(1);
  };

  // Export CSV
  const handleExport = () => {
    const exportData = filteredTxns.map(t => ({
      'Transaction ID': t.id,
      'Date': t.date,
      'SKU Code': t.sku,
      'Material Name': t.name,
      'Quantity': t.qty,
      'Transaction Type': t.type,
      'Reference Number': t.ref || '',
      'Remarks': t.remarks || '',
      'Operator': t.user || ''
    }));

    const csv = Papa.unparse(exportData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `Stock_Transactions_${new Date().toISOString().slice(0, 10)}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      {/* Toolbar */}
      <div className="flex flex-wrap items-center gap-3 bg-white border border-gray-200 rounded-3xl p-4 shadow-xs">
        <div className="relative flex-1 min-w-[220px]">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input
            type="text"
            value={search}
            onChange={(e) => { setSearch(e.target.value); setCurrentPage(1); }}
            placeholder="Search Txn ID, SKU, material, reference, user..."
            className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-xl bg-gray-50 text-gray-900 text-sm focus:ring-2 focus:ring-indigo-500 outline-hidden"
          />
        </div>

        <select
          value={typeFilter}
          onChange={(e) => { setTypeFilter(e.target.value); setCurrentPage(1); }}
          className="px-3 py-2 border border-gray-200 rounded-xl bg-gray-50 text-gray-900 text-sm cursor-pointer"
        >
          <option value="">All Types</option>
          <option value="IN">IN (Stock Received)</option>
          <option value="OUT">OUT (Stock Issued)</option>
        </select>

        <button
          onClick={() => setShowFilters(prev => !prev)}
          className={`flex items-center gap-2 px-4 py-2 border rounded-xl text-sm font-bold transition-all cursor-pointer ${
            showFilters
              ? 'border-indigo-500 bg-indigo-50 text-indigo-700'
              : 'border-gray-200 text-gray-700 hover:border-indigo-500 hover:text-indigo-600'
          }`}
        >
          <SlidersHorizontal size={16} />
          Date Filter
        </button>

        <button
          onClick={handleExport}
          className="flex items-center gap-1.5 px-4 py-2 border border-gray-200 rounded-xl text-sm font-bold text-gray-700 bg-white cursor-pointer"
        >
          <FileSpreadsheet size={16} />
          Export CSV
        </button>

      </div>

      {/* Expanded Date Filters */}
      {showFilters && (
        <div className="flex flex-wrap gap-4 bg-gray-50 border border-dashed border-gray-200 p-4 rounded-2xl">
          <div className="flex flex-col gap-1.5">
            <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">From Date</label>
            <input
              type="date"
              value={fromDate}
              onChange={(e) => { setFromDate(e.target.value); setCurrentPage(1); }}
              className="px-3.5 py-1.5 border border-gray-200 rounded-xl bg-white text-sm text-gray-950"
            />
          </div>
          <div className="flex flex-col gap-1.5">
            <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">To Date</label>
            <input
              type="date"
              value={toDate}
              onChange={(e) => { setToDate(e.target.value); setCurrentPage(1); }}
              className="px-3.5 py-1.5 border border-gray-200 rounded-xl bg-white text-sm text-gray-955"
            />
          </div>
          <div className="flex items-end">
            <button
              onClick={() => { setFromDate(''); setToDate(''); }}
              className="px-4 py-2 text-xs font-bold text-indigo-650 bg-indigo-50 rounded-xl cursor-pointer"
            >
              Clear
            </button>
          </div>
        </div>
      )}

      {/* Grid Ledger Table */}
      <div className="bg-white border border-gray-200 rounded-3xl overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse text-sm">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-200 text-gray-500 text-xs font-bold uppercase tracking-wider select-none">
                <th className="px-5 py-4 cursor-pointer hover:text-indigo-500" onClick={() => requestSort('id')}>Txn ID</th>
                <th className="px-5 py-4 cursor-pointer hover:text-indigo-500" onClick={() => requestSort('date')}>Date</th>
                <th className="px-5 py-4 cursor-pointer hover:text-indigo-500" onClick={() => requestSort('sku')}>SKU</th>
                <th className="px-5 py-4 cursor-pointer hover:text-indigo-500" onClick={() => requestSort('name')}>Material Name</th>
                <th className="px-5 py-4 cursor-pointer hover:text-indigo-500" onClick={() => requestSort('qty')}>Quantity</th>
                <th className="px-5 py-4 cursor-pointer hover:text-indigo-500" onClick={() => requestSort('type')}>Type</th>
                <th className="px-5 py-4 cursor-pointer hover:text-indigo-500" onClick={() => requestSort('ref')}>Reference #</th>
                <th className="px-5 py-4 cursor-pointer hover:text-indigo-500" onClick={() => requestSort('user')}>User</th>
                <th className="px-5 py-4">Remarks</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-150 text-gray-700">
              {paginatedTxns.length === 0 ? (
                <tr>
                  <td colSpan={9} className="text-center py-10 text-gray-400">No stock movements recorded.</td>
                </tr>
              ) : (
                paginatedTxns.map(t => (
                  <tr key={t.id} className="hover:bg-gray-50/50">
                    <td className="px-5 py-4 font-mono font-bold text-gray-900">{t.id}</td>
                    <td className="px-5 py-4 whitespace-nowrap">{t.date}</td>
                    <td className="px-5 py-4 font-mono font-bold text-gray-800">{t.sku}</td>
                    <td className="px-5 py-4 font-bold text-gray-900 whitespace-nowrap">{t.name}</td>
                    <td className="px-5 py-4 font-black text-sm">{t.qty.toLocaleString()}</td>
                    <td className="px-5 py-4">
                      {t.type === 'IN' ? (
                        <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-bold bg-teal-100 text-teal-850">
                          <ArrowDownLeft size={12} className="text-teal-600" />
                          IN (Receive)
                        </span>
                      ) : (
                        <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-bold bg-rose-100 text-rose-850">
                          <ArrowUpRight size={12} className="text-rose-600" />
                          OUT (Issue)
                        </span>
                      )}
                    </td>
                    <td className="px-5 py-4 font-mono whitespace-nowrap">{t.ref || '—'}</td>
                    <td className="px-5 py-4 font-semibold whitespace-nowrap">{t.user || '—'}</td>
                    <td className="px-5 py-4 max-w-[200px] truncate" title={t.remarks}>{t.remarks || '—'}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination bar */}
        <div className="flex flex-col sm:flex-row items-center justify-between gap-4 px-6 py-4 bg-gray-50 border-t border-gray-200 text-xs font-bold text-gray-550">
          <div className="flex flex-col sm:flex-row items-center gap-4">
            <div>
              Showing {filteredTxns.length === 0 ? 0 : Math.min(filteredTxns.length, (currentPage - 1) * pageSize + 1)}–
              {Math.min(filteredTxns.length, currentPage * pageSize)} of {filteredTxns.length} records
            </div>
            <div className="flex items-center gap-1.5">
              <span className="text-[10px] uppercase text-gray-400 tracking-wider">Rows per page:</span>
              <select
                value={pageSize}
                onChange={handlePageSizeChange}
                className="px-2 py-0.5 border border-gray-200 rounded-md bg-white text-gray-700 cursor-pointer focus:ring-1 focus:ring-indigo-500 font-normal"
              >
                <option value="6">6</option>
                <option value="12">12</option>
                <option value="25">25</option>
                <option value="50">50</option>
                <option value="100">100</option>
              </select>
            </div>
          </div>
          {totalPages > 1 && (
            <div className="flex items-center gap-1.5">
              {Array.from({ length: totalPages }).map((_, idx) => (
                <button
                  key={idx}
                  onClick={() => setCurrentPage(idx + 1)}
                  className={`w-7 h-7 rounded-lg transition-colors cursor-pointer flex items-center justify-center border text-[11px] ${
                    currentPage === idx + 1
                      ? 'bg-indigo-600 text-white border-indigo-600'
                      : 'bg-white border-gray-200 text-gray-650 hover:bg-gray-50'
                  }`}
                >
                  {idx + 1}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useMemo } from "react";
import { useDispatch, useSelector } from "react-redux";
import { useParams, useNavigate } from "react-router-dom";
import { fetchInventoryData } from "../redux/slice/inventorySlice";

// Icons for sub-tabs
import {
  LayoutDashboard,
  Boxes,
  Database,
  History,
  AlertTriangle,
  ClipboardList,
  ShieldCheck,
  Settings,
  Sparkles,
  RefreshCw,
} from "lucide-react";

// Import sub-views
import DashboardView from "../components/DashboardView";
import StockDashboardView from "../components/StockDashboardView";
// import MasterDataView from '../components/MasterDataView';
import TransactionsView from "../components/TransactionsView";
import ReorderView from "../components/ReorderView";
import IndentView from "../components/IndentView";
import SettingsView from "../components/SettingsView";

const PAGE_META = {
  dashboard: { title: "Dashboard", icon: LayoutDashboard },
  stock: { title: "IMS", icon: Boxes },
  // master: { title: 'Master Data', icon: Database },
  transactions: { title: "Stock Transactions", icon: History },
  reorder: { title: "Reorder Management", icon: AlertTriangle },
  indent: { title: "Indent Management", icon: ClipboardList },
  settings: { title: "Master", icon: Settings },
};

export default function InventoryPage() {
  const dispatch = useDispatch();
  const {
    loading,
    error,
    materials,
    transactions,
    indents = [],
  } = useSelector((state) => state.inventory);

  const { tabId } = useParams();
  const navigate = useNavigate();
  const activeTab = tabId || "dashboard";

  const setActiveTab = (newTabId) => {
    navigate(`/dashboard/inventory/${newTabId}`);
  };

  const [userStateSeq, setUserStateSeq] = useState(0); // Sequence to force reload credentials

  // Load database values on component mount
  useEffect(() => {
    dispatch(fetchInventoryData());
  }, [dispatch]);

  // Derived user credentials from simulation switches
  const activeUser = useMemo(() => {
    const realName = localStorage.getItem("user-name") || "Guest User";
    const realRole = localStorage.getItem("role") || "user";

    // Simulated overrides
    const simRole = localStorage.getItem("sp_simulated_role") || realRole;
    const simDept = localStorage.getItem("sp_simulated_dept") || "General";
    const simLoc = localStorage.getItem("sp_simulated_loc") || "";

    // Standardize role display: Capitalize first letter if lowercase
    const formattedRole =
      simRole.charAt(0).toUpperCase() + simRole.slice(1).toLowerCase();

    return {
      name: realName,
      role: formattedRole,
      department: simDept,
      location: simLoc,
      isSimulated: !!(
        localStorage.getItem("sp_simulated_role") ||
        localStorage.getItem("sp_simulated_dept") ||
        localStorage.getItem("sp_simulated_loc")
      ),
    };
  }, [userStateSeq]);

  // Filter visible tabs based on role page restriction
  const visibleTabs = useMemo(() => {
    const role = activeUser.role;
    const realRole = localStorage.getItem("role") || "user";
    const formattedRealRole =
      realRole.charAt(0).toUpperCase() + realRole.slice(1).toLowerCase();

    return Object.keys(PAGE_META).filter((tabId) => {
      // Exclude settings for regular users (allow if current simulated role is Admin/Superadmin OR real role is Admin/Superadmin)
      if (tabId === "settings") {
        return (
          role === "Admin" ||
          role === "Superadmin" ||
          formattedRealRole === "Admin" ||
          formattedRealRole === "Superadmin"
        );
      }
      return true;
    });
  }, [activeUser]);

  // If active tab becomes hidden after role change, fallback to dashboard
  useEffect(() => {
    if (!visibleTabs.includes(activeTab)) {
      setActiveTab("dashboard");
    }
  }, [visibleTabs, activeTab]);

  const handleReloadCredentials = () => {
    setUserStateSeq((prev) => prev + 1);
  };

  // Reorder warnings badge count
  const reorderBadgeCount = useMemo(() => {
    // 1. Calculate stock balances per SKU
    const matClosing = {};
    materials.forEach((m) => {
      matClosing[m.sku] = Number(m.opening) || 0;
    });

    transactions.forEach((t) => {
      if (matClosing[t.sku] !== undefined) {
        if (t.type === "IN") {
          matClosing[t.sku] += Number(t.qty) || 0;
        } else {
          matClosing[t.sku] -= Number(t.qty) || 0;
        }
      }
    });

    let count = 0;
    materials.forEach((m) => {
      const hasPendingIndent = indents.some(
        (i) =>
          i.sku === m.sku &&
          (i.status === "Pending" || i.status === "Approved"),
      );
      if (hasPendingIndent) return;

      const closingStock = matClosing[m.sku] || 0;
      const safetyStock = (Number(m.adc) || 0) * (Number(m.safetyFactor) || 0);
      const reorderLevel =
        (Number(m.adc) || 0) * (Number(m.leadTime) || 0) + safetyStock;

      if (m.status === "Active" && closingStock <= reorderLevel) {
        // If location filter applies, check matching location
        if (!activeUser.location || m.location === activeUser.location) {
          count++;
        }
      }
    });
    return count;
  }, [materials, transactions, indents, activeUser.location]);

  return (
    <>
      <div className="max-w-7xl mx-auto p-4 md:p-6 space-y-6 theme-transition">
        {/* Module Header Banner */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-gray-200 pb-5">
          <div className="flex items-center gap-3">
            <div className="p-3 bg-indigo-650/10 text-indigo-750 rounded-2xl shadow-xs">
              <Boxes size={28} />
            </div>
            <div>
              <div className="flex items-center gap-2 mb-0.5">
                <h1 className="text-2xl md:text-3xl font-black text-gray-900 tracking-tight">
                  Inventory Management{" "}
                  <span className="text-indigo-600">
                    IMS
                  </span>
                </h1>
                {activeUser.isSimulated && (
                  <span className="inline-flex items-center gap-1 px-2 py-0.5 bg-blue-100 text-blue-800 rounded-md text-[10px] font-black uppercase tracking-wider">
                    <Sparkles size={8} />
                    Simulated
                  </span>
                )}
              </div>
              <p className="text-gray-500 text-xs font-semibold">
                Enterprise Inventory Tracking &amp; Reorder Management System
              </p>
            </div>
          </div>

          {/* Active Credentials profile tag */}
          <div className="flex flex-wrap items-center gap-3">
            <div className="flex items-center gap-3 bg-white border border-gray-200 px-4 py-2.5 rounded-2xl shadow-xs">
              <div className="h-8 w-8 rounded-xl bg-gradient-to-br from-indigo-500 to-blue-600 text-white font-black text-xs flex items-center justify-center shadow-md shadow-indigo-500/10">
                {activeUser.name.slice(0, 2).toUpperCase()}
              </div>
              <div>
                <div className="text-xs font-bold text-gray-900 truncate max-w-[120px]">
                  {activeUser.name}
                </div>
                <div className="text-[10px] text-gray-400 flex items-center gap-1.5 font-bold uppercase tracking-wider">
                  <span>{activeUser.role}</span>
                  {activeUser.location && (
                    <>
                      <span>·</span>
                      <span className="text-indigo-500">
                        {activeUser.location}
                      </span>
                    </>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Inner Content - Full Width */}
        <div className="space-y-4">
          {loading ? (
            <div className="bg-white border border-gray-200 rounded-3xl p-20 text-center space-y-3 shadow-sm">
              <RefreshCw
                size={32}
                className="animate-spin text-indigo-500 mx-auto"
              />
              <p className="text-sm font-bold text-gray-500">
                Loading IMS data stream...
              </p>
            </div>
          ) : error ? (
            <div className="bg-rose-50 border border-rose-250 text-rose-700 rounded-3xl p-6 shadow-sm">
              <h3 className="text-lg font-black mb-2">IMS Loading Failure</h3>
              <p className="text-sm">{error}</p>
            </div>
          ) : (
            /* Component rendering block */
            <div className="animate-fade-in">
              {activeTab === "dashboard" && (
                <DashboardView
                  activeUser={activeUser}
                  onTabChange={setActiveTab}
                />
              )}
              {activeTab === "stock" && (
                <StockDashboardView activeUser={activeUser} />
              )}
              {/* {activeTab === 'master' && (
                <MasterDataView activeUser={activeUser} />
              )} */}
              {activeTab === "transactions" && (
                <TransactionsView activeUser={activeUser} />
              )}
              {activeTab === "reorder" && (
                <ReorderView
                  activeUser={activeUser}
                  onTabChange={setActiveTab}
                />
              )}
              {activeTab === "indent" && <IndentView activeUser={activeUser} />}
              {activeTab === "settings" && (
                <SettingsView
                  activeUser={activeUser}
                  onReloadUser={handleReloadCredentials}
                />
              )}
            </div>
          )}
        </div>
      </div>
    </>
  );
}

