export const resetToDummyDataApi = async (currentUser = 'Admin') => {
  try {
    // Delete all records from all tables
    await Promise.all([
      supabase.from('inventory_materials').delete().neq('sku', ''),
      supabase.from('inventory_transactions').delete().neq('id', ''),
      supabase.from('inventory_indents').delete().neq('indent_no', ''),
      supabase.from('inventory_units').delete().neq('id', 0),
      supabase.from('inventory_locations').delete().neq('id', 0),
      supabase.from('inventory_settings').delete().neq('id', 0),
      supabase.from('inventory_audit').delete().neq('id', 0)
    ]);

    const fresh = seedInitialData();

    // 1. Save materials
    const dbMaterials = fresh.materials.map(mapUIMaterialToDB);
    const { error: matErr } = await supabase.from('inventory_materials').insert(dbMaterials);
    if (matErr) throw new Error(matErr.message);

    // 2. Save transactions
    const dbTxns = fresh.transactions.map(mapUITxnToDB);
    const { error: txnErr } = await supabase.from('inventory_transactions').insert(dbTxns);
    if (txnErr) throw new Error(txnErr.message);

    // 3. Save units
    const { error: unitErr } = await supabase.from('inventory_units').insert(fresh.units.map(u => ({ unit: u })));
    if (unitErr) throw new Error(unitErr.message);

    // 4. Save locations
    const { error: locErr } = await supabase.from('inventory_locations').insert(fresh.locations.map(l => ({ location: l })));
    if (locErr) throw new Error(locErr.message);

    // 5. Save settings
    const dbSettings = mapUISettingsToDB(fresh.settings);
    const { error: setErr } = await supabase.from('inventory_settings').insert(dbSettings);
    if (setErr) throw new Error(setErr.message);

    // 6. Write database reset audit log
    await writeAudit('Database Reset', currentUser, 'All tables reset to system default dummy seed configuration.');

    return await fetchInventoryDataApi();
  } catch (err) {
    console.error("resetToDummyDataApi failed", err);
    return { data: null, error: err.message };
  }
};

/**
 * MIS Summary System — Master System Registration
 *
 * Registers the MIS Summary module with the master systemRegistry so it
 * appears in the sidebar navigation and its routes are loaded into the
 * master app's router.
 *
 * Auth Bridge Strategy:
 * ─────────────────────
 * The MIS pages use `useAuth()` from their own `AuthContext.jsx`, which
 * normally requires the MIS system's own `AuthProvider` (Google Sheets login).
 * Inside the master system we DON'T want a second login — users are already
 * authenticated via Supabase/localStorage.
 *
 * Solution: Each route element wraps the page in a `MisAuthBridgeProvider`
 * that reads from the master system's localStorage and injects the value
 * directly into the same `AuthContext` object the pages read from.
 * This makes `useAuth()` work in every MIS page without any page modifications.
 */

import React from 'react';
import systemRegistry from '../../core/registry/systemRegistry';
import { AuthContext } from './src/contexts/AuthContext';
import { MasterAuthBridgeProvider, useMasterAuthBridge } from './src/contexts/MasterAuthBridge';

// Import MIS pages
import AdminDashboard from './src/pages/admin/Dashboard';
import AdminHistoryCommitment from './src/pages/admin/HistoryCommitment';
import KpiKra from './src/pages/admin/KpiKra';

// ─── Bridge Injector ─────────────────────────────────────────────────────────

/**
 * Reads auth data from MasterAuthBridgeProvider and injects it into the
 * MIS system's own AuthContext so all pages' useAuth() calls are satisfied.
 */
function MisAuthBridgeInjector({ children }) {
  const bridge = useMasterAuthBridge();
  return (
    <AuthContext.Provider value={bridge}>
      {children}
    </AuthContext.Provider>
  );
}

/**
 * Wraps any MIS page with the full auth bridge stack.
 */
function MisPageWrapper({ children }) {
  return (
    <MasterAuthBridgeProvider>
      <MisAuthBridgeInjector>
        {children}
      </MisAuthBridgeInjector>
    </MasterAuthBridgeProvider>
  );
}

/** Helper — wraps a component in the auth bridge */
const wrap = (PageComponent) => (
  <MisPageWrapper>
    <PageComponent />
  </MisPageWrapper>
);

// ─── System Registration ─────────────────────────────────────────────────────

systemRegistry.register({
  id: 'mis-summary',
  name: 'MIS Summary',
  icon: 'BarChart2',

  menuItems: [
    {
      label: 'MIS Dashboard',
      href: '/dashboard/mis-summary',
      icon: 'LayoutDashboard',
      showFor: ['admin', 'HOD', 'user'],
    },
    {
      label: 'MIS History',
      href: '/dashboard/mis-history',
      icon: 'History',
      showFor: ['admin', 'HOD', 'user'],
    },
    {
      label: 'KPI & KRA',
      href: '/dashboard/mis-kpi-kra',
      icon: 'Target',
      showFor: ['admin', 'HOD', 'user'],
    },
  ],

  routes: [
    {
      path: '/dashboard/mis-summary',
      element: wrap(AdminDashboard),
      protected: true,
    },
    {
      path: '/dashboard/mis-history',
      element: wrap(AdminHistoryCommitment),
      protected: true,
    },
    {
      path: '/dashboard/mis-kpi-kra',
      element: wrap(KpiKra),
      protected: true,
    },
  ],
});

import { Routes, Route, Navigate } from 'react-router-dom';
import { useAuth } from './contexts/AuthContext';
import Login from './pages/Login';
import AdminDashboard from './pages/admin/Dashboard';
import AdminHistoryCommitment from './pages/admin/HistoryCommitment';
import AdminTodayTasks from './pages/admin/TodayTasks';
import AdminPendingTasks from './pages/admin/PendingTasks';
import KpiKra from './pages/admin/KpiKra';
import AdminLayout from './layouts/AdminLayout';
import NotFound from './pages/NotFound';
import Report from './pages/admin/Report';

function App() {
  const { user, loading } = useAuth();

  // Show loading spinner while checking authentication
  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  const isAdminOrSuper = user && (user.role === 'admin' || user.role === 'superadmin');

  return (
    <Routes>
      <Route
        path="/login"
        element={
          user ? (
            <Navigate to={isAdminOrSuper ? '/admin' : '/user'} replace />
          ) : (
            <Login />
          )
        }
      />

      {/* Admin Routes */}
      <Route
        path="/admin/*"
        element={
          <RequireAuth role="admin">
            <AdminLayout />
          </RequireAuth>
        }
      >
        <Route index element={<Navigate to="/admin/dashboard" replace />} />
        <Route path="dashboard" element={<AdminDashboard />} />
        <Route path="history-commitment" element={<AdminHistoryCommitment />} />
        <Route path="today-tasks" element={<AdminTodayTasks />} />
        <Route path="pending-tasks" element={<AdminPendingTasks />} />
        <Route path="kpi-kra" element={<KpiKra />} />
        <Route path="department" element={<Report />} />
      </Route>

      {/* User Routes */}
      <Route
        path="/user/*"
        element={
          <RequireAuth role="user">
            <AdminLayout />
          </RequireAuth>
        }
      >
        <Route index element={<Navigate to="/user/dashboard" replace />} />
        <Route path="dashboard" element={<AdminDashboard />} />
        <Route path="history-commitment" element={<AdminHistoryCommitment />} />
        <Route path="kpi-kra" element={<KpiKra />} />
      </Route>

      {/* Root route */}
      <Route
        path="/"
        element={
          <Navigate to={user ? (isAdminOrSuper ? '/admin' : '/user') : '/login'} replace />
        }
      />

      <Route path="*" element={<NotFound />} />
    </Routes>
  );
}

// Authentication guard component
function RequireAuth({ children, role }) {
  const { user, loading } = useAuth();

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (!user) {
    return <Navigate to="/login" replace />;
  }

  const isAdminOrSuper = user.role === 'admin' || user.role === 'superadmin';

  if (role === 'admin' && !isAdminOrSuper) {
    return <Navigate to="/user" replace />;
  }

  if (role === 'user' && user.role !== 'user' && user.role !== 'hod' && !isAdminOrSuper) {
    return <Navigate to="/login" replace />;
  }

  return children;
}

export default App;

