  }, [userRole]);

  const ensureAbsoluteUrl = (url) => {
    if (!url) return '';
    const strUrl = String(url).trim();
    if (strUrl.startsWith('http://') || strUrl.startsWith('https://')) return strUrl;
    return `https://${strUrl}`;
  };

  const showNotification = (message, type = 'success') => {
