import React, { useEffect, useRef, useState } from 'react';
import { ChevronDown } from 'lucide-react';

/**
 * A free-text input that also offers a searchable dropdown of existing
 * records. Typing is always allowed (primary path); picking a suggestion
 * calls onSelectOption with the full record so the parent can autofill
 * other fields.
 */
export default function EntitySelectInput({
    value,
    onChange,
    options,
    onSelectOption,
    placeholder,
    className = 'form-input',
}) {
    const [open, setOpen] = useState(false);
    const wrapRef = useRef(null);

    useEffect(() => {
        function handleClickOutside(e) {
            if (wrapRef.current && !wrapRef.current.contains(e.target)) setOpen(false);
        }
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const term = (value || '').toLowerCase().trim();
    const filtered = term
        ? options.filter((o) => (o.name || '').toLowerCase().includes(term))
        : options;

    return (
        <div className="relative" ref={wrapRef}>
            <div className="relative">
                <input
                    className={className}
                    value={value}
                    placeholder={placeholder}
                    onChange={(e) => {
                        onChange(e.target.value);
                        setOpen(true);
                    }}
                    onFocus={() => setOpen(true)}
                />
                <button
                    type="button"
                    onClick={() => setOpen((o) => !o)}
                    className="absolute right-2.5 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                    tabIndex={-1}
                >
                    <ChevronDown size={14} />
                </button>
            </div>

            {open && filtered.length > 0 && (
                <div className="absolute z-20 mt-1 w-full max-h-56 overflow-y-auto rounded-xl border border-gray-200 bg-white shadow-lg">
                    {filtered.slice(0, 30).map((o) => (
                        <button
                            key={o.id}
                            type="button"
                            className="block w-full px-3.5 py-2 text-left text-[12.5px] hover:bg-gray-50"
                            onClick={() => {
                                onSelectOption(o);
                                setOpen(false);
                            }}
                        >
                            <div className="font-semibold text-gray-900">{o.name}</div>
                            {(o.contact || o.gstin) && (
                                <div className="text-[11px] text-gray-500">
                                    {[o.contact, o.gstin].filter(Boolean).join(' · ')}
                                </div>
                            )}
                        </button>
                    ))}
                </div>
            )}
        </div>
    );
}

import React, { useRef, useState } from 'react';
import * as XLSX from 'xlsx';
import { UploadCloud } from 'lucide-react';
import { importIndentRows } from '../services/purchaseService';
import { CardPanel } from './ui';
import { findColIndex } from '../utils/helpers';

export default function ImportView({ onImported }) {
  const fileInputRef = useRef(null);
  const [result, setResult] = useState(null);
  const [importing, setImporting] = useState(false);

  const handleFile = (file) => {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (evt) => {
      try {
        const data = new Uint8Array(evt.target.result);
        const wb = XLSX.read(data, { type: 'array' });
        const sheet = wb.Sheets[wb.SheetNames[0]];
        const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '' });

        let headerRowIdx = rows.findIndex((r) => r.some((c) => String(c).trim().toLowerCase() === 'item details'));
        if (headerRowIdx === -1)
          headerRowIdx = rows.findIndex((r) => r.some((c) => String(c).trim().toLowerCase().includes('item details')));
        if (headerRowIdx === -1) {
          setResult({ type: 'danger', text: 'Could not find an "Item Details" column header. Please check the file format.' });
          return;
        }
        const headers = rows[headerRowIdx].map((h) => String(h).trim());
        const idx = {
          item: findColIndex(headers, ['item details']),
          cat: findColIndex(headers, ['product category']),
          vendor: findColIndex(headers, ['vendor']),
          unit: headers.findIndex((h) => h.toLowerCase() === 'unit'),
          altUnit: findColIndex(headers, ['alt unit']),
          parentGroup: findColIndex(headers, ['parent group']),
          shelf: findColIndex(headers, ['shelf capacity']),
          maxLevel: findColIndex(headers, ['max level']),
          rol: findColIndex(headers, ['rol qty']),
          clQty: findColIndex(headers, ['cl. qty', 'cl qty']),
          conv: findColIndex(headers, ['conversion unit']),
          orderFormula: findColIndex(headers, ['order formula']),
        };
        const dataRows = rows.slice(headerRowIdx + 1).filter((r) => r.some((c) => String(c).trim() !== ''));
        const parsed = [];
        dataRows.forEach((r) => {
          const itemDetails = idx.item > -1 ? String(r[idx.item] || '').trim() : '';
          if (!itemDetails) return;
          parsed.push({
            itemDetails,
            category: idx.cat > -1 ? String(r[idx.cat] || '').trim() : 'Uncategorized',
            vendor: idx.vendor > -1 ? String(r[idx.vendor] || '').trim() : '',
            unit: idx.unit > -1 ? String(r[idx.unit] || '').trim() : 'Pcs.',
            altUnit: idx.altUnit > -1 ? String(r[idx.altUnit] || '').trim() : '',
            parentGroup: idx.parentGroup > -1 ? String(r[idx.parentGroup] || '').trim() : '',
            shelfCapacity: idx.shelf > -1 ? String(r[idx.shelf] || '').trim() : '',
            maxLevelQty: idx.maxLevel > -1 ? Number(r[idx.maxLevel]) || 0 : 0,
            rolQty: idx.rol > -1 ? Number(r[idx.rol]) || 0 : 0,
            clQty: idx.clQty > -1 ? Number(r[idx.clQty]) || 0 : 0,
            conversionUnit: idx.conv > -1 ? String(r[idx.conv] || '').trim() : '',
            orderFormula: idx.orderFormula > -1 ? Number(r[idx.orderFormula]) || 0 : 0,
          });
        });
        if (parsed.length === 0) {
          setResult({ type: 'warning', text: 'No data rows found below the header.' });
          return;
        }
        setImporting(true);
        const { firstNo, lastNo } = await importIndentRows(parsed);
        setResult({
          type: 'success',
          text: `${parsed.length} item(s) imported successfully. Unique numbers generated from ${firstNo} to ${lastNo}.`,
        });
        onImported && onImported();
      } catch (err) {
        console.error(err);
        setResult({ type: 'danger', text: err.message || 'Error reading file. Please upload a valid .xlsx / .xls / .csv file.' });
      } finally {
        setImporting(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const alertClasses = {
    success: 'bg-emerald-50 text-emerald-800 border-emerald-200',
    warning: 'bg-amber-50 text-amber-800 border-amber-200',
    danger: 'bg-rose-50 text-rose-800 border-rose-200',
  };

  return (
    <div className="mb-3">
      <div className="flex items-center gap-3">
        <button
          type="button"
          disabled={importing}
          onClick={() => fileInputRef.current.click()}
          className={`inline-flex items-center gap-2 rounded-lg bg-[#173254] px-4 py-2 text-[13px] font-semibold text-white transition ${importing ? 'cursor-wait opacity-60' : 'hover:bg-[#10243e]'}`}
        >
          <UploadCloud size={16} />
          {importing ? 'Importing…' : 'Import Indent (Excel)'}
        </button>
        <span className="text-[11.8px] text-gray-500">Supported: .xlsx, .xls, .csv</span>
      </div>
      <input
        ref={fileInputRef}
        type="file"
        accept=".xlsx,.xls,.csv"
        className="hidden"
        disabled={importing}
        onChange={(e) => {
          handleFile(e.target.files[0]);
          e.target.value = '';
        }}
      />
      {result && (
        <div className={`mt-2.5 rounded-lg border px-3.5 py-2.5 text-sm ${alertClasses[result.type]}`}>{result.text}</div>
      )}
    </div>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { CardPanel, FilterBar, StatusBadge, EmptyState } from './ui';
import ImportView from './ImportView';
import { uniqueValues } from '../utils/helpers';
import { fetchIndents } from '../services/purchaseService';
import { FileText, Loader2, ChevronDown, ChevronRight } from 'lucide-react';
export default function IndentView({ onTabChange, refreshKey, onImported }) {
  const [indents, setIndents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('');
  const [vendor, setVendor] = useState('');
  const [status, setStatus] = useState('');
  const [expanded, setExpanded] = useState({});

  const toggleVendor = (v) => {
    setExpanded((prev) => ({ ...prev, [v]: !prev[v] }));
  };

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    fetchIndents()
      .then((rows) => {
        if (!cancelled) setIndents(rows);
      })
      .catch((err) => {
        if (!cancelled) setError(err.message || 'Failed to load indent data.');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [refreshKey]);

  const categories = useMemo(() => uniqueValues(indents, 'category'), [indents]);
  const vendors = useMemo(() => uniqueValues(indents, 'vendor'), [indents]);

  const rows = useMemo(() => {
    const term = search.toLowerCase().trim();
    return indents.filter((i) => {
      if (term && !`${i.itemDetails} ${i.vendor} ${i.category}`.toLowerCase().includes(term)) return false;
      if (category && i.category !== category) return false;
      if (vendor && i.vendor !== vendor) return false;
      if (status && i.status !== status) return false;
      return true;
    });
  }, [indents, search, category, vendor, status]);

  const groups = useMemo(() => {
    const g = {};
    rows.forEach((i) => {
      const v = i.vendor || 'Unspecified Vendor';
      (g[v] = g[v] || []).push(i);
    });
    return g;
  }, [rows]);

  const clear = () => {
    setSearch('');
    setCategory('');
    setVendor('');
    setStatus('');
  };

  return (
    <CardPanel
      title="Indent Data"
      desc="Every item imported from Excel, with its generated Unique Number."
      action={<ImportView onImported={onImported} />}
    >
      <FilterBar onClear={clear}>
        <input
          type="text"
          placeholder="Search item, vendor..."
          className="min-w-[150px] flex-1 rounded-lg border border-gray-300 px-2.5 py-1.5 text-[12.5px]"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
