function RecordPaymentModal({ approval, po, onClose, onSuccess }) {
    const [amountPaid, setAmountPaid] = useState('');
    const [remarks, setRemarks] = useState('');
    const [proofFile, setProofFile] = useState(null);
    const [submitting, setSubmitting] = useState(false);
    const [error, setError] = useState('');

    function handleFileChange(e) {
        setProofFile(e.target.files?.[0] || null);
    }

    async function handleSubmit(e) {
        e.preventDefault();
        setError('');
        if (!amountPaid) {
            setError('Amount paid is required.');
            return;
        }
        setSubmitting(true);
        try {
            await submitPayment({ paymentApprovalId: approval.id, poId: approval.poId, proofFile, remarks, amountPaid });
            onSuccess();
        } catch (err) {
            setError(err.message || 'Failed to record payment.');
        } finally {
            setSubmitting(false);
        }
    }

    return (
        <Modal open={true} onClose={onClose} title={`Record Payment — ${po?.poNo || ''}`} size="md">
            <form onSubmit={handleSubmit} className="space-y-4">
                <div className="rounded-xl bg-gray-50 px-4 py-2.5 text-[12.5px] text-gray-600">
                    PO <span className="font-bold text-gray-900">{po?.poNo}</span> ({po?.vendor?.name}) — Grand Total ₹ {fmt(po?.grandTotal)}
                </div>

                <div>
                    <label className="mb-1 block text-[12px] font-bold text-gray-600">Amount Paid (₹)</label>
                    <input type="number" step="0.01" className="input" value={amountPaid} onChange={(e) => setAmountPaid(e.target.value)} placeholder="0.00" />
                </div>

                <div>
                    <label className="mb-1 block text-[12px] font-bold text-gray-600">Payment Proof</label>
                    <label className="flex h-[42px] cursor-pointer items-center gap-2 rounded-xl border border-dashed border-gray-300 px-3 text-[13px] text-gray-500 hover:border-gray-400">
                        <Upload size={16} />
                        {proofFile ? proofFile.name : 'Choose file'}
                        <input type="file" accept="image/*,.pdf" className="hidden" onChange={handleFileChange} />
                    </label>
                </div>

                <div>
                    <label className="mb-1 block text-[12px] font-bold text-gray-600">Remark</label>
                    <textarea className="input h-20 py-2" value={remarks} onChange={(e) => setRemarks(e.target.value)} placeholder="Optional remark" />
                </div>

                {error && <div className="text-[12.5px] font-semibold text-rose-600">{error}</div>}

                <div className="flex justify-end gap-2 border-t border-gray-100 pt-2">
                    <button type="button" onClick={onClose} className="rounded-xl border border-gray-300 px-4 py-2 text-[13px] font-semibold text-gray-700 hover:bg-gray-50">
                        Cancel
                    </button>
                    <button type="submit" disabled={submitting} className="inline-flex items-center gap-2 rounded-xl bg-[#173254] px-5 py-2 text-[13px] font-bold text-white hover:bg-[#10243e] disabled:opacity-50">
                        <Wallet size={16} />
                        {submitting ? 'Saving…' : 'Record Payment'}
                    </button>
                </div>
            </form>

            <style>{`
        .input { min-height: 42px; border-radius: 0.75rem; border: 1px solid #e5e7eb; padding: 0 0.75rem; font-size: 13px; width: 100%; }
        .input:focus { outline: none; border-color: #173254; }
      `}</style>
        </Modal>
    );
}

import React, { useEffect, useMemo, useState } from 'react';
import { submitNewPO, revisePO } from '../services/purchaseService';
import { sendPOCreatedNotification } from '../services/purchaseWhatsappService';
import { generatePOPdfBlob } from '../utils/generatePOPdf';
import { uploadPOPdf } from '../utils/uploadPOPdf';
import { fmt } from '../utils/helpers';
import PreviewModal from './PreviewModal';
import EntitySelectInput from './EntitySelectInput';
import supabase from '../../../SupabaseClient';

const DEFAULT_TERMS = `1. We deserve the right to cancel the purchase order anytime before product shipment.
2. Invoice raised to us should contain the details of purchase order with data mentioned.
3. Adherence to agreed product specifications is a must. Any deviation during delivery will result in cancellation of PO.
4. Packing and shipping charges to be borne by vendor, unless mentioned.
5. Delivery should be strictly done within 5 days from the date of purchase order.`;

function itemsFromIndents(items) {
  return items.map((i) => ({
    indentId: i.dbId,
    productCode: '',
    productName: i.itemDetails,
    hsn: '',
    qty: (i.approvedQty != null ? i.approvedQty : i.orderFormula) || 0,
    units: i.unit || 'Pcs.',
    rate: 0,
    tax: 5,
    amount: 0,
    isExtra: false,
  }));
}

export default function PoCreateView({ draft, onDone, onCancel }) {
  const existingPO = draft && draft.existingPO;
  const isRevision = !!existingPO;

  const [form, setForm] = useState(() => buildInitialForm(draft));
  const [items, setItems] = useState(() => (isRevision ? existingPO.items.map((it) => ({ ...it })) : itemsFromIndents(draft.items)));
  const [preview, setPreview] = useState(null);
  const [saving, setSaving] = useState(false);
  const [submitError, setSubmitError] = useState('');
  const [vendors, setVendors] = useState([]);

  useEffect(() => {
    supabase
      .from('vendors')
      .select('*')
      .order('name', { ascending: true })
      .then(({ data }) => setVendors(data || []));
  }, []);

  useEffect(() => {
    if (!form.vendorName || vendors.length === 0) return;
    const match = vendors.find((v) => (v.name || '').trim().toLowerCase() === form.vendorName.trim().toLowerCase());
    if (!match) return;
   setForm((prev) => {
      if (prev.vendorAddr || prev.vendorGstin || prev.vendorContact || prev.vendorEmail) return prev;
      return {
        ...prev,
        vendorAddr: match.address || '',
        vendorGstin: match.gstin || '',
        vendorContact: match.contact || '',
        vendorEmail: match.email || '',
        vendorCity: match.city || '',
        fixTransporter: match.fix_transporter || '',
        vendorPaymentTerms: match.payment_terms || '',
      };
    });

  }, [form.vendorName, vendors]);

  useEffect(() => {
    setForm(buildInitialForm(draft));
    setItems(draft && draft.existingPO ? draft.existingPO.items.map((it) => ({ ...it })) : itemsFromIndents(draft ? draft.items : []));
    setSubmitError('');
  }, [draft]);

  const totals = useMemo(() => {
    const total = items.reduce((s, it) => s + (Number(it.qty) || 0) * (Number(it.rate) || 0), 0);
    const taxAmount = items.reduce((s, it) => {
      const amt = (Number(it.qty) || 0) * (Number(it.rate) || 0);
      return s + amt * ((Number(it.tax) || 0) / 100);
    }, 0);
    const discount = Number(form.discount) || 0;
    return { total, taxAmount, grandTotal: total + taxAmount - discount };
  }, [items, form.discount]);

  const updateField = (field, value) => setForm((prev) => ({ ...prev, [field]: value }));
  const updateItem = (idx, field, value) => {
    setItems((prev) =>
      prev.map((it, i) => {
        if (i !== idx) return it;
        const next = { ...it, [field]: ['qty', 'rate', 'tax'].includes(field) ? Number(value) || 0 : value };
        next.amount = (Number(next.qty) || 0) * (Number(next.rate) || 0);
        return next;
      }),
    );
  };
  const removeItem = (idx) => setItems((prev) => prev.filter((_, i) => i !== idx));
  const addExtra = () =>
    setItems((prev) => [...prev, { indentId: null, productCode: '', productName: '', hsn: '', qty: 1, units: 'Pcs.', rate: 0, tax: 5, amount: 0, isExtra: true }]);

  const buildPayload = () => ({
    poNo: form.poNo,
    poDate: form.poDate,
    requisitioner: form.requisitioner,
    shipVia: form.fixTransporter,
    fob: form.fob,
    shipTerms: form.shipTerms,
    vendor: { name: form.vendorName, addr: form.vendorAddr, gstin: form.vendorGstin, contact: form.vendorContact, email: form.vendorEmail, fixTransporter: form.fixTransporter, paymentTerms: form.vendorPaymentTerms },
    shipTo: { gstin: form.shipGstin, contact: form.shipContact, email: form.shipEmail },
    terms: form.terms,
    discount: form.discount,
  });

  const handlePreview = () => {
    if (items.length === 0) return;
    const { total, taxAmount, grandTotal } = totals;
    setPreview({
      po: { ...buildPayload(), items, total, taxAmount, grandTotal },
      note: isRevision && existingPO.revision > 1 ? 'Revision' : '',
    });
  };

  const handleSubmit = async () => {
    if (items.length === 0) return;
    if (!form.vendorName) return;
if (!form.vendorContact) { setSubmitError('Contact number is required.'); return; }
    const payload = buildPayload();
    setSaving(true);
    setSubmitError('');
    try {
      if (isRevision) {
        await revisePO({ poId: existingPO.id, form: payload, items });
      } else {
        const newPO = await submitNewPO({ form: payload, items });

        // Generate PDF, upload to storage, then send WhatsApp — all non-blocking
        (async () => {
          try {
            const poForPdf = {
              poNo      : newPO.poNo,
              poDate    : form.poDate,
              requisitioner: form.requisitioner,
              shipVia   : form.fixTransporter,
              fob       : form.fob,
              shipTerms : form.shipTerms,
              vendor    : { name: form.vendorName, addr: form.vendorAddr, gstin: form.vendorGstin, contact: form.vendorContact, email: form.vendorEmail },
              shipTo    : { gstin: form.shipGstin, contact: form.shipContact, email: form.shipEmail },
              terms     : form.terms,
              items,
            };
            const blob        = await generatePOPdfBlob(poForPdf);
            const documentUrl = await uploadPOPdf(blob, newPO.poNo);
            await sendPOCreatedNotification({
              vendorName    : form.vendorName,
              vendorContact : form.vendorContact,
              poNo          : newPO.poNo,
              poDate        : form.poDate,
              documentUrl,
            });
          } catch (err) {
            console.error('PO PDF/WhatsApp error:', err);
          }
        })();
      }
      onDone();
    } catch (err) {
      setSubmitError(err.message || 'Failed to save purchase order.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="mb-4 rounded-2xl border border-gray-200 bg-white p-5">
      <div className="mb-4 flex flex-wrap items-center justify-between gap-2">
        <div>
          <h2 className="mb-0.5 text-[15px] font-bold text-gray-900">{isRevision ? 'Revise Purchase Order' : 'Create Purchase Order'}</h2>
          <div className="text-[12.3px] text-gray-500">One PO per vendor — every selected product from that vendor appears together.</div>
        </div>
        <span className="inline-block whitespace-nowrap rounded-full bg-indigo-50 px-2.5 py-1 text-[10.6px] font-bold text-indigo-700">
          {isRevision ? `Revising ${existingPO.poNo}` : 'New PO'}
        </span>
      </div>

      <div className="mb-2 grid grid-cols-1 gap-3 sm:grid-cols-2">
        <Field label="PO No.">
          <input className="form-input" value={form.poNo || 'Auto-generated on submit'} readOnly />
        </Field>
        <Field label="PO Date">
          <input type="date" className="form-input" value={form.poDate} onChange={(e) => updateField('poDate', e.target.value)} />
        </Field>

      </div>

      <hr className="my-4 border-gray-200" />
      <div className="mb-2 grid grid-cols-1 gap-4 md:grid-cols-2">
        <div>
          <div className="mb-2 text-[13px] font-bold text-[#173254]">Vendor (Supplier) — all products below belong to this vendor</div>
          <EntitySelectInput
            className="form-input mb-2"
            placeholder="Supplier name (type new, or pick existing)"
            value={form.vendorName}
            onChange={(v) => updateField('vendorName', v)}
            options={vendors}
            onSelectOption={(v) =>
              setForm((prev) => ({
                ...prev,
                vendorName: v.name || '',
                vendorAddr: v.address || '',
                vendorGstin: v.gstin || '',
               vendorContact: v.contact || '',
                vendorEmail: v.email || '',
                vendorCity: v.city || '',
               fixTransporter: v.fix_transporter || '',
                vendorPaymentTerms: v.payment_terms || '',
              }))
            }
          />
          <input className="form-input mb-2" placeholder="Supplier address" value={form.vendorAddr} onChange={(e) => updateField('vendorAddr', e.target.value)} />
         <div className="grid grid-cols-2 gap-2">
            <input className="form-input" placeholder="GSTIN" value={form.vendorGstin} onChange={(e) => updateField('vendorGstin', e.target.value)} />
            <input className="form-input" placeholder="Contact no. *" value={form.vendorContact} onChange={(e) => updateField('vendorContact', e.target.value)} required />
          </div>
          <input className="form-input mt-2" placeholder="City" value={form.vendorCity} onChange={(e) => updateField('vendorCity', e.target.value)} />
         <div className="mt-2 grid grid-cols-2 gap-2">
            <input className="form-input" placeholder="Email" value={form.vendorEmail} onChange={(e) => updateField('vendorEmail', e.target.value)} />
            <input className="form-input" placeholder="Ship Via" value={form.fixTransporter} onChange={(e) => updateField('fixTransporter', e.target.value)} />
          </div>
        </div>
        <div>
          <div className="mb-2 text-[13px] font-bold text-[#173254]">Ship To</div>
          <input className="form-input mb-2 bg-gray-50" value="Bhatia Enterprises" readOnly />
          <input className="form-input mb-2 bg-gray-50" value="Nehru Chowk, Bilaspur (C.G.)" readOnly />
          <div className="grid grid-cols-2 gap-2">
            <input className="form-input" placeholder="GSTIN" value={form.shipGstin} onChange={(e) => updateField('shipGstin', e.target.value)} />
            <input className="form-input" placeholder="Contact no." value={form.shipContact} onChange={(e) => updateField('shipContact', e.target.value)} />
          </div>
          <input className="form-input mt-2" placeholder="Email" value={form.shipEmail} onChange={(e) => updateField('shipEmail', e.target.value)} />
        </div>
      </div>

      <hr className="my-4 border-gray-200" />
      <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
        <div className="text-[13px] font-bold text-[#173254]">Items</div>
        <button className="rounded-lg border border-[#173254] px-3 py-1.5 text-xs font-semibold text-[#173254]" onClick={addExtra}>
          + Add Extra Material
        </button>
      </div>
      <div className="mb-2 overflow-x-auto rounded-xl border border-gray-200">
        <table className="w-full text-[12.6px]">
          <thead>
            <tr className="bg-gray-50 text-gray-500">
              {['S.No', 'Product Name', 'Qty', 'Units', ''].map((h) => (
                <th key={h} className="whitespace-nowrap border-b border-gray-200 px-2.5 py-2 text-left text-[10.3px] font-bold uppercase tracking-wide">
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {items.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-2.5 py-4 text-center text-gray-500">
                  No items yet — add extra material or go back and select items.
                </td>
              </tr>
            ) : (
              items.map((it, idx) => (
                <tr key={idx} className="border-t border-gray-100">
                  <td className="whitespace-nowrap px-2.5 py-1.5">
                    {idx + 1}
                    {it.isExtra && <span className="ml-1.5 inline-block rounded-full bg-purple-50 px-2 py-0.5 text-[10px] font-bold text-purple-700">Extra</span>}
                  </td>
                  <td className="px-1.5 py-1.5">
                    <input className="table-input min-w-[160px]" value={it.productName} onChange={(e) => updateItem(idx, 'productName', e.target.value)} />
                  </td>
                  <td className="px-1.5 py-1.5">
                    <input type="number" className="table-input min-w-[70px]" value={it.qty} onChange={(e) => updateItem(idx, 'qty', e.target.value)} />
                  </td>
                  <td className="px-1.5 py-1.5">
                    <input className="table-input min-w-[60px]" value={it.units} onChange={(e) => updateItem(idx, 'units', e.target.value)} />
                  </td>
                  <td className="px-1.5 py-1.5">
                    <button className="rounded-md border border-rose-300 px-2 py-1 text-rose-600 hover:bg-rose-50" onClick={() => removeItem(idx)} title="Delete">
                      &times;
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <div className="mt-2">
        <label className="field-label">Terms &amp; Conditions</label>
        <textarea className="form-input" rows={4} value={form.terms} onChange={(e) => updateField('terms', e.target.value)} />
      </div>

      {submitError && <div className="mt-3 text-right text-sm text-rose-600">{submitError}</div>}
      <div className="mt-5 flex flex-wrap justify-end gap-2">
        <button className="rounded-lg border border-[#173254] px-4 py-2 text-sm font-semibold text-[#173254]" onClick={onCancel} disabled={saving}>
          Cancel
        </button>
        <button className="rounded-lg border border-[#173254] px-4 py-2 text-sm font-semibold text-[#173254]" onClick={handlePreview} disabled={saving}>
          Preview
        </button>
        <button className="rounded-lg bg-[#C99A3E] px-4 py-2 text-sm font-semibold text-[#1B2A3D] hover:bg-[#B98A2E] disabled:opacity-60" onClick={handleSubmit} disabled={saving}>
          {saving ? 'Saving…' : isRevision ? 'Update / Revise PO' : 'Submit PO'}
        </button>
      </div>

      <PreviewModal po={preview && preview.po} revisionNote={preview && preview.note} onClose={() => setPreview(null)} />
    </div>
  );
}

function buildInitialForm(draft) {
  const existingPO = draft && draft.existingPO;
  if (existingPO) {
    return {
      poNo: existingPO.poNo,
      poDate: existingPO.poDate,
      requisitioner: existingPO.requisitioner,
      shipVia: existingPO.shipVia,
      fob: existingPO.fob,
      shipTerms: existingPO.shipTerms,
      vendorName: existingPO.vendor.name,
      vendorAddr: existingPO.vendor.addr,
      vendorGstin: existingPO.vendor.gstin,
      vendorContact: existingPO.vendor.contact,
      vendorEmail: existingPO.vendor.email,
      fixTransporter: existingPO.vendor.fixTransporter || '',
      vendorPaymentTerms: existingPO.vendor.paymentTerms || '',
      vendorCity: existingPO.vendor.city || '',
      shipGstin: existingPO.shipTo.gstin,
      shipContact: existingPO.shipTo.contact,
      shipEmail: existingPO.shipTo.email,
      terms: existingPO.terms,
      discount: existingPO.discount,
    };
  }
  return {
    poNo: '',
    poDate: new Date().toISOString().slice(0, 10),
    requisitioner: 'Store Manager',
    shipVia: 'Road by truck',
    fob: 'On destination',
    shipTerms: 'Free shipping to destination',
    vendorName: (draft && draft.vendorName) || '',
    vendorAddr: '',
    vendorGstin: '',
    vendorContact: '',
    vendorEmail: '',
    fixTransporter: '',
    vendorPaymentTerms: '',
    vendorCity: '',
    shipGstin: '',
    shipContact: '',
    shipEmail: 'purchase-team@bhatia.com',
    terms: DEFAULT_TERMS,
    discount: 0,
  };
}

function Field({ label, children, className = '' }) {
  return (
    <div className={className}>
      <label className="field-label">{label}</label>
      {children}
    </div>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { Loader2 } from 'lucide-react';
import { CardPanel, FilterBar, EmptyState, RevisionChip } from './ui';
import Modal from './Modal';
import PreviewModal from './PreviewModal';
import { fmt, uniqueValues } from '../utils/helpers';
import { fetchPOs, fetchPoRevisions } from '../services/purchaseService';

export default function PoListView({ onRevise }) {
  const [pos, setPos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [search, setSearch] = useState('');
  const [vendor, setVendor] = useState('');
  const [versionsPO, setVersionsPO] = useState(null);
  const [preview, setPreview] = useState(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    fetchPOs()
      .then((rows) => {
        if (!cancelled) setPos(rows);
      })
      .catch((err) => {
        if (!cancelled) setError(err.message || 'Failed to load purchase orders.');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const openPreview = (po, note) => setPreview({ po, note });

  const vendors = useMemo(() => uniqueValues(pos.map((p) => ({ vendor: p.vendor.name })), 'vendor'), [pos]);

  const rows = useMemo(() => {
    const term = search.toLowerCase().trim();
    return pos
      .filter((po) => {
        if (term && !`${po.poNo} ${po.vendor.name}`.toLowerCase().includes(term)) return false;
        if (vendor && po.vendor.name !== vendor) return false;
        return true;
      })
      .slice()
      .reverse();
  }, [pos, search, vendor]);

  const clear = () => {
    setSearch('');
    setVendor('');
  };

  return (
    <CardPanel title="Purchase Orders" desc="All POs raised so far. Preview to print, or revise to correct and re-issue.">
      <FilterBar onClear={clear}>
        <input
          type="text"
          placeholder="Search PO no, vendor..."
          className="min-w-[150px] flex-1 rounded-lg border border-gray-300 px-2.5 py-1.5 text-[12.5px]"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <select className="min-w-[130px] rounded-lg border border-gray-300 px-2.5 py-1.5 text-[12.5px]" value={vendor} onChange={(e) => setVendor(e.target.value)}>
          <option value="">All Vendors</option>
          {vendors.map((v) => (
            <option key={v} value={v}>{v}</option>
          ))}
        </select>
      </FilterBar>

     {loading ? (
        <EmptyState icon={<Loader2 size={36} className="animate-spin" />}>Loading purchase orders…</EmptyState>
      ) : error ? (
        <EmptyState>{error}</EmptyState>
      ) : pos.length === 0 ? (
        <div className="overflow-x-auto rounded-xl border border-gray-200">
          <table className="w-full text-[12.6px]">
            <thead>
              <tr className="bg-gray-50 text-gray-500">
                {['PO No.', 'Date', 'Vendor', 'Items', 'Grand Total', 'Revision', ''].map((h) => (
                  <th key={h} className="whitespace-nowrap border-b border-gray-200 px-2.5 py-2 text-left text-[10.3px] font-bold uppercase tracking-wide">
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              <tr><td colSpan={7} className="px-2.5 py-10 text-center text-gray-500">No Purchase Orders created yet.</td></tr>
            </tbody>
          </table>
        </div>
      ) : rows.length === 0 ? (
        <div className="overflow-x-auto rounded-xl border border-gray-200">
          <table className="w-full text-[12.6px]">
            <thead>
              <tr className="bg-gray-50 text-gray-500">
                {['PO No.', 'Date', 'Vendor', 'Items', 'Grand Total', 'Revision', ''].map((h) => (
                  <th key={h} className="whitespace-nowrap border-b border-gray-200 px-2.5 py-2 text-left text-[10.3px] font-bold uppercase tracking-wide">
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              <tr><td colSpan={7} className="px-2.5 py-10 text-center text-gray-500">No POs match the current filters.</td></tr>
            </tbody>
          </table>
        </div>
      ) : (
        <div className="overflow-x-auto rounded-xl border border-gray-200">
          <table className="w-full text-[12.6px]">
            <thead>
              <tr className="bg-gray-50 text-gray-500">
                {['PO No.', 'Date', 'Vendor', 'Items', 'Grand Total', 'Revision', ''].map((h) => (
                  <th key={h} className="whitespace-nowrap border-b border-gray-200 px-2.5 py-2 text-left text-[10.3px] font-bold uppercase tracking-wide">
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map((po) => (
                <tr key={po.id} className="border-t border-gray-100 hover:bg-gray-50">
                  <td className="px-2.5 py-2 font-semibold">{po.poNo}</td>
                  <td className="px-2.5 py-2">{po.poDate}</td>
                  <td className="px-2.5 py-2">{po.vendor.name}</td>
                  <td className="px-2.5 py-2">{po.items.length}</td>
                  <td className="px-2.5 py-2 font-semibold">₹ {fmt(po.grandTotal)}</td>
                  <td className="px-2.5 py-2">
                    <RevisionChip revision={po.revision} />
                  </td>
                  <td className="whitespace-nowrap px-2.5 py-2">
                    <button
                      className="mr-1 rounded-lg border border-[#173254] px-2.5 py-1 text-xs font-semibold text-[#173254]"
                      onClick={() => openPreview(po, po.revision > 1 ? `Revision ${po.revision}` : '')}
                    >
                      Preview
                    </button>
                    {po.revision > 1 && (
                      <button className="mr-1 rounded-lg border border-[#173254] px-2.5 py-1 text-xs font-semibold text-[#173254]" onClick={() => setVersionsPO(po)}>
                        Versions
                      </button>
                    )}
                    <button className="rounded-lg bg-[#C99A3E] px-2.5 py-1 text-xs font-semibold text-[#1B2A3D]" onClick={() => onRevise(po)}>
                      Revise
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <VersionsModal po={versionsPO} onClose={() => setVersionsPO(null)} onPreviewVersion={(v) => openPreview(v, 'Old version — replaced by current PO')} />
      <PreviewModal po={preview && preview.po} revisionNote={preview && preview.note} onClose={() => setPreview(null)} />
    </CardPanel>
  );
}

function VersionsModal({ po, onClose, onPreviewVersion }) {
  const [versions, setVersions] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!po) return;
    let cancelled = false;
    setLoading(true);
    fetchPoRevisions(po.id)
      .then((rows) => {
        if (!cancelled) setVersions(rows);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [po]);

  if (!po) return null;
  return (
    <Modal open={!!po} onClose={onClose} title={`Previous Versions — ${po.poNo}`} size="lg">
      {loading ? (
        <div className="py-3 text-sm text-gray-500">Loading versions…</div>
      ) : versions.length === 0 ? (
        <EmptyState>No previous versions.</EmptyState>
      ) : (
        versions.map((v, idx) => (
          <div key={idx} className="mb-3 rounded-xl border border-gray-200 bg-white p-4 last:mb-0">
            <div className="mb-2 flex items-center justify-between">
              <div>
                <span className="text-[14px] font-bold text-[#173254]">{v.poNo}</span>{' '}
                <span className="text-[11.5px] text-gray-500">revised at {v.revisedAt}</span>
              </div>
              <button className="rounded-lg border border-[#173254] px-2.5 py-1 text-xs font-semibold text-[#173254]" onClick={() => onPreviewVersion(v)}>
                Preview
              </button>
            </div>
            <div className="flex justify-between text-[12.5px]">
              <span>Items: {v.items.length}</span>
              <span className="font-semibold">Grand Total: ₹ {fmt(v.grandTotal)}</span>
            </div>
          </div>
        ))
      )}
    </Modal>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { CardPanel, FilterBar, EmptyState } from './ui';
import Modal from './Modal';
import { uniqueValues } from '../utils/helpers';
import { fetchIndents, fixIndentVendor, deleteIndents } from '../services/purchaseService';
import { Loader2, ChevronDown, ChevronRight } from 'lucide-react';

export default function PoPendingView({ onCreatePO }) {
  const [indents, setIndents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('');
  const [vendor, setVendor] = useState('');
 const [checkedByVendor, setCheckedByVendor] = useState({});
  const [expanded, setExpanded] = useState({});
  const [fixingVendorGroup, setFixingVendorGroup] = useState(null);

  function reload() {
    setLoading(true);
    fetchIndents()
      .then((rows) => setIndents(rows))
      .catch((err) => setError(err.message || 'Failed to load indent data.'))
      .finally(() => setLoading(false));
  }

  async function handleDeleteSelected(v, items) {
    const checkedItems = items.filter((i) => isChecked(v, i.id));
    if (checkedItems.length === 0) return;
    if (!window.confirm(`Delete ${checkedItems.length} selected item(s) from ${v}? This cannot be undone.`)) return;
    try {
      await deleteIndents(checkedItems.map((i) => i.dbId));
      reload();
    } catch (err) {
      setError(err.message || 'Failed to delete items.');
    }
  }

  const toggleVendor = (v) => {
    setExpanded((prev) => ({ ...prev, [v]: !prev[v] }));
  };
function DiffCell({ orderQty, approvedQty }) {
  if (approvedQty == null) return <span className="text-gray-400">—</span>;
  const diff = Number(approvedQty) - Number(orderQty);
  if (diff === 0) return <span className="text-gray-400">0</span>;
  const positive = diff > 0;
  return (
    <span className={`font-bold ${positive ? 'text-emerald-600' : 'text-rose-600'}`}>
      {positive ? `+${diff}` : diff}
    </span>
  );
}
  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    fetchIndents()
      .then((rows) => {
        if (!cancelled) setIndents(rows);
      })
      .catch((err) => {
        if (!cancelled) setError(err.message || 'Failed to load indent data.');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const allPending = useMemo(() => indents.filter((i) => i.status === 'Approved' && !i.poId), [indents]);
  const categories = useMemo(() => uniqueValues(allPending, 'category'), [allPending]);
  const vendors = useMemo(() => uniqueValues(allPending, 'vendor'), [allPending]);

  const filtered = useMemo(() => {
    const term = search.toLowerCase().trim();
    return allPending.filter((i) => {
      if (term && !`${i.itemDetails} ${i.vendor}`.toLowerCase().includes(term)) return false;
      if (category && i.category !== category) return false;
      if (vendor && i.vendor !== vendor) return false;
      return true;
    });
  }, [allPending, search, category, vendor]);

  const groups = useMemo(() => {
    const g = {};
    filtered.forEach((i) => {
      const v = i.vendor || 'Unspecified Vendor';
      (g[v] = g[v] || []).push(i);
    });
    return g;
  }, [filtered]);

  const isChecked = (v, id) => {
    const map = checkedByVendor[v];
    return map && map[id] !== undefined ? map[id] : true;
  };
  const setCheck = (v, id, val) => {
    setCheckedByVendor((prev) => ({ ...prev, [v]: { ...(prev[v] || {}), [id]: val } }));
  };
  const toggleAllForVendor = (v, items, val) => {
    const map = {};
    items.forEach((i) => (map[i.id] = val));
    setCheckedByVendor((prev) => ({ ...prev, [v]: map }));
  };

  const clear = () => {
    setSearch('');
    setCategory('');
    setVendor('');
  };

  return (
    <CardPanel title="PO Pending" desc="Approved items grouped by vendor. A Purchase Order is always created vendor-wise — select items from a vendor group and create one PO for all of them.">
      <FilterBar onClear={clear}>
        <input
          type="text"
          placeholder="Search item, vendor..."
          className="min-w-[150px] flex-1 rounded-lg border border-gray-300 px-2.5 py-1.5 text-[12.5px]"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <select className="min-w-[130px] rounded-lg border border-gray-300 px-2.5 py-1.5 text-[12.5px]" value={category} onChange={(e) => setCategory(e.target.value)}>
          <option value="">All Categories</option>
          {categories.map((c) => (
            <option key={c} value={c}>{c}</option>
          ))}
        </select>
        <select className="min-w-[130px] rounded-lg border border-gray-300 px-2.5 py-1.5 text-[12.5px]" value={vendor} onChange={(e) => setVendor(e.target.value)}>
          <option value="">All Vendors</option>
          {vendors.map((v) => (
            <option key={v} value={v}>{v}</option>
          ))}
        </select>
      </FilterBar>

      {loading ? (
        <EmptyState icon={<Loader2 size={36} className="animate-spin" />}>Loading approved items…</EmptyState>
      ) : error ? (
        <EmptyState>{error}</EmptyState>
      ) : allPending.length === 0 ? (
        <div className="overflow-x-auto rounded-xl border border-gray-200">
          <table className="w-full text-[12.6px]">
            <thead>
              <tr className="bg-gray-50 text-gray-500">
                {['', 'Unique No.', 'Item Details', 'Category', 'Unit', 'Order Qty', 'Approved Qty', 'Difference'].map((h) => (
                  <th key={h} className="whitespace-nowrap border-b border-gray-200 px-2.5 py-2 text-left text-[10.3px] font-bold uppercase tracking-wide">
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              <tr><td colSpan={8} className="px-2.5 py-10 text-center text-gray-500">No approved items waiting for a Purchase Order.</td></tr>
            </tbody>
          </table>
        </div>
      ) : filtered.length === 0 ? (
        <div className="overflow-x-auto rounded-xl border border-gray-200">
          <table className="w-full text-[12.6px]">
            <thead>
              <tr className="bg-gray-50 text-gray-500">
                {['', 'Unique No.', 'Item Details', 'Category', 'Unit', 'Order Qty', 'Approved Qty', 'Difference'].map((h) => (
                  <th key={h} className="whitespace-nowrap border-b border-gray-200 px-2.5 py-2 text-left text-[10.3px] font-bold uppercase tracking-wide">
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              <tr><td colSpan={8} className="px-2.5 py-10 text-center text-gray-500">No items match the current filters.</td></tr>
            </tbody>
          </table>
        </div>
      ) : (
        Object.keys(groups).map((v) => {
          const items = groups[v];
          const allChecked = items.every((i) => isChecked(v, i.id));
          return (
           <div key={v} className="mb-5 overflow-hidden rounded-xl border border-gray-200">
              <div className="flex flex-wrap items-center justify-between gap-2 bg-gray-50 px-3.5 py-2.5">
                <button
                  type="button"
                  onClick={() => toggleVendor(v)}
                  className="flex items-center gap-1.5 text-left text-[13px] font-bold text-[#173254]"
                >
                  {expanded[v] ? <ChevronDown size={15} /> : <ChevronRight size={15} />}
                  {v} <span className="font-normal text-gray-500">({items.length} item{items.length > 1 ? 's' : ''})</span>
                </button>
               <div className="flex items-center gap-2">
                  <button
                    className="rounded-lg border border-rose-300 bg-rose-50 px-3 py-1.5 text-xs font-semibold text-rose-700 hover:bg-rose-100"
                    onClick={() => handleDeleteSelected(v, items)}
                  >
                    Delete Selected
                  </button>
                  {v === 'Unspecified Vendor' ? (
                    <button
                      className="rounded-lg border border-rose-300 bg-rose-50 px-3 py-1.5 text-xs font-semibold text-rose-700 hover:bg-rose-100"
                      onClick={() => setFixingVendorGroup({ vendor: v, items })}
                    >
                      Fix Vendor Before Ordering
                    </button>
                  ) : (
                    <button
                      className="rounded-lg bg-[#C99A3E] px-3 py-1.5 text-xs font-semibold text-[#1B2A3D] hover:bg-[#B98A2E]"
                      onClick={() => {
                        const checkedItems = items.filter((i) => isChecked(v, i.id));
                        if (checkedItems.length === 0) return;
                        onCreatePO(checkedItems, v);
                      }}
                    >
                      Create PO for selected
                    </button>
                  )}
                </div>
              </div>
              {expanded[v] && (
              <div className="overflow-x-auto border-t border-gray-200">
                <table className="w-full text-[12.6px]">
                  <thead>
                    <tr className="bg-gray-50 text-gray-500">
                      <th className="px-2.5 py-2">
                        <input type="checkbox" checked={allChecked} onChange={(e) => toggleAllForVendor(v, items, e.target.checked)} />
                      </th>
                     {['Unique No.', 'Item Details', 'Category', 'Unit', 'Order Qty', 'Approved Qty', 'Difference'].map((h) => (
                        <th key={h} className="whitespace-nowrap border-b border-gray-200 px-2.5 py-2 text-left text-[10.3px] font-bold uppercase tracking-wide">
                          {h}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {items.map((i) => (
                      <tr key={i.id} className="border-t border-gray-100 hover:bg-gray-50">
                        <td className="px-2.5 py-2">
                          <input type="checkbox" checked={isChecked(v, i.id)} onChange={(e) => setCheck(v, i.id, e.target.checked)} />
                        </td>
                        <td className="px-2.5 py-2">{i.id}</td>
                        <td className="px-2.5 py-2">{i.itemDetails}</td>
                        <td className="px-2.5 py-2">{i.category}</td>
                        <td className="px-2.5 py-2">{i.unit}</td>
                       <td className="px-2.5 py-2">{i.orderFormula}</td>
                        <td className="px-2.5 py-2 font-semibold">{i.approvedQty != null ? i.approvedQty : i.orderFormula}</td>
                        <td className="px-2.5 py-2">
                          <DiffCell orderQty={i.orderFormula} approvedQty={i.approvedQty} />
                        </td>
                      </tr>
                    ))}
                 </tbody>
                </table>
              </div>
              )}
            </div>
          );
        })
      )}

      <FixVendorModal
        group={fixingVendorGroup}
        onClose={() => setFixingVendorGroup(null)}
        onFixed={() => {
          setFixingVendorGroup(null);
          reload();
        }}
      />
    </CardPanel>
  );
}

function FixVendorModal({ group, onClose, onFixed }) {
  const [vendorName, setVendorName] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  if (!group && vendorName) setVendorName('');

  async function handleSave() {
    if (!vendorName.trim()) {
      setError('Enter a vendor name.');
      return;
    }
    setSaving(true);
    setError('');
    try {
      await fixIndentVendor(group.items.map((i) => i.dbId), vendorName.trim());
      onFixed();
    } catch (err) {
      setError(err.message || 'Failed to update vendor.');
    } finally {
      setSaving(false);
    }
  }

  return (
    <Modal
      open={!!group}
      onClose={onClose}
      title="Fix Vendor"
      footer={
        <>
          <button className="rounded-lg border border-[#173254] px-4 py-2 text-sm font-semibold text-[#173254]" onClick={onClose} disabled={saving}>
            Cancel
          </button>
          <button className="rounded-lg bg-[#173254] px-4 py-2 text-sm font-semibold text-white disabled:opacity-60" onClick={handleSave} disabled={saving}>
            {saving ? 'Saving…' : 'Save Vendor'}
          </button>
        </>
      }
    >
      {group && (
        <>
          <p className="mb-3 text-[12.5px] text-gray-600">
            These {group.items.length} item(s) were imported without a vendor. Assign the correct vendor name so a Purchase Order can be created.
          </p>
          <input
            type="text"
            autoFocus
